  ('cpiuris2025::96c35bcf40bac58ccdc6e28f6ae97c86', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Mandados de criminalização no crime de terrorismo', '## Mandados de criminalização no crime de terrorismo

A Lei regulamenta o disposto no inciso XLIII do art. 50 da Constituição Federal, disciplinando o terrorismo e definindo mandados de criminalização.

### Conceitos
- **Mandado de criminalização**: Obrigação do legislador ordinário de atuar disciplinando condutas
- **Terrorismo**: Prática de atos com finalidade de provocar terror social ou generalizado
- **Proporcionalidade**: Princípio que exige a necessidade de proteção a determinados bens jurídicos e observância ao princípio da razoabilidade

### Referências legais
- Art. 50 da Constituição Federal
- Lei n.º 13.260/2016

### Dicas de prova
- Entenda a distinção entre mandado de criminalização e tratamento dispensado aos crimes hediondos
