  ('cpiuris2025::b56942339e52c759f3492088201972a5', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes no Estatuto da Criança e do Adolescente', '## Crimes no Estatuto da Criança e do Adolescente

O texto discute as regras sobre crimes contra crianças e adolescentes, prevendo condutas específicas e competência da Justiça Estadual.

### Conceitos
- **Estatuto da Criança e do Adolescente**: Lei que regula os direitos das crianças e adolescentes no Brasil
- **Art. 244-C ECA**: Prevê conduta específica contra crianças e adolescentes
- **Lei Henry Borel**: Lei que estabelece as regras sobre crimes contra crianças e adolescentes
- **Vítima de crime**: Pessoa que sofreu um dano ou lesão por meio de uma conduta criminosa
- **Crime próprio especial**: Tipo de crime que tem regras específicas e não é considerado como crime comum
- **Ação penal pública incondicionada**: Procedimento judicial que não exige a condenação do réu para ser iniciado

### Referências legais
- Art. 244-C do ECA
- Lei 14.344/2022 (Lei Henry Borel)

### Dicas de prova
- Entenda a diferença entre crime próprio especial e crime comum
