  ('cpiuris2025::ddafdaf944a94b65367aa83dda683154', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Uso e posse de explosivos e meios capazes de causar danos', '## Uso e posse de explosivos e meios capazes de causar danos

Artigos I a III da Lei N.º 13.260/2016 definem o crime de terrorismo, proibindo o uso ou ameaça de explosivos, gases tóxicos, venenos, entre outros meios capazes de causar danos.

### Conceitos
- **Explosivos**: Materiais que podem causar danos por meio da expansão rápida de gases
- **Terrorismo**: Ação ou prática destinada a criar pânico, medo ou terror em massa
- **Meios capazes de causar danos**: Substâncias, materiais ou dispositivos que podem causar dano ou destruição

### Referências legais
- Art. I da Lei N.º 13.260/2016

### Dicas de prova
- Distinção entre o uso e a posse de explosivos
- Entendimento do termo ''meios capazes de causar danos''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. I da Lei N.º 13.260/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:14:02.121261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=131", "doc_key": "ddafdaf944a94b65367aa83dda683154"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1b3b9fd160bc5e21abb96b3a924734426df69a71d67172fbd61ea1daf83af311'),
  ('cpiuris2025::cd05216a6bf61dfcdb810539d8694a63', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra o consumidor e terrorismo', '## Crimes contra o consumidor e terrorismo

Artigos que regulamentam crimes contra o consumidor e terrorismo, incluindo penas e exceções.

