- Exceções para manifestações políticas, movimentos sociais, etc.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º", "Art. 5º", "Art. 6º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:14:56.883660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=132", "doc_key": "cd05216a6bf61dfcdb810539d8694a63"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e368550cca0cb0f03fcfb04270b7fca4956fa246a43be2b9e54661499f2f0c5e'),
  ('cpiuris2025::b08d00edb9c2bd04f905617fbde99e56', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Definição de crime de terrorismo e aplicação das leis anteriores', '## Definição de crime de terrorismo e aplicação das leis anteriores

O crime de terrorismo é definido como atos de terrorismo legalmente definidos, sendo regulamentado pela Lei n.º 13.260/2016. As disposições da Lei n.º 8.072/1990 são aplicadas aos crimes previstos nesta Lei, e a Lei n.º 12.850/2013 é alterada para incluir as organizações terroristas.

### Conceitos
- **Terrorismo**: Atos de terrorismo legalmente definidos
- **Lei n.º 13.260/2016**: Regulamenta o crime de terrorismo
- **Lei n.º 8.072/1990**: Aplicada aos crimes previstos nesta Lei
- **Lei n.º 12.850/2013**: Alterada para incluir as organizações terroristas

### Referências legais
- Art. 2º da Lei n.º 13.260/2016
- Súmula N STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de terrorismo e como é regulamentado pela Lei n.º 13.260/2016
- Leia atentamente as alterações da Lei n.º 12.850/2013 para incluir as organizações terroristas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei n.º 13.260/2016", "Súmula N STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T20:15:12.219668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=132", "doc_key": "b08d00edb9c2bd04f905617fbde99e56"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '14c0043577d7989c6c4770c8780d764f6140643f6db64b68bd72c5fa9ecd6b1c'),
  ('cpiuris2025::39567cc82c92c4849388ac2ab1be8a76', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tipificação do Terrorismo', '## Tipificação do Terrorismo

O terrorismo é tipificado como crime comum, dependendo de quatro requisitos cumulativos: motivo, fim, perigo e atos terroristas.

### Conceitos
- **Motivo**: razões que justificam a ação do sujeito
- **Fim**: intenção de provocar terror social ou generalizado
- **Perigo**: exposição a perigo para pessoa, patrimônio, paz pública ou incolumidade pública
- **Atos terroristas**: condutas-meio para a execução do crime

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Reconheça os requisitos cumulativos para o terrorismo
- Entenda a distinção entre sujeito ativo e passivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:17:04.205283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=133", "doc_key": "39567cc82c92c4849388ac2ab1be8a76"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '10d50f4b80017f671a691f1b4a5e4a8acabdb13ea4ca95e3284055c4e9fe4752'),
  ('cpiuris2025::409f6a89858dfd851d9679ca27947320', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Terrorismo', '## Terrorismo

Rege a prática de atos que visam provocar terror social ou generalizado, com finalidade de expondo a perigo pessoa, patrimônio, a paz pública ou a incolumidade pública.

### Conceitos
- **Terrorismo**: Prática de atos com finalidade de provocar terror social ou generalizado
- **Xenofobia**: Discriminação ou preconceito contra indivíduos de raças, etnias ou religiões diferentes
- **Ameaça**: Uso ou ameaçar usar explosivos, gases tóxicos, venenos, conteúdos biológicos, químicos, nucleares ou outros meios capazes de causar danos
- **Sabotagem**: Apoder-se, com violência, grave ameaça a pessoa ou servindo-se de mecanismos cibernéticos, do controle total ou parcial de meio de comunicação ou transporte

### Referências legais
- Art. 2º da Lei n.º 8.078/1990

### Dicas de prova
- Distinção entre atos terroristas e outros tipos de crimes
- Importância do contexto para a aplicação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei n.º 8.078/1990"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-31T20:17:42.072104+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=133", "doc_key": "409f6a89858dfd851d9679ca27947320"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '43d81bff83e50701723288b58b9e33dd6d8fd8ca5a48bd630c7052e53ad4db7a'),
  ('cpiuris2025::dd95518ab98885299d380ee10700e716', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Terrorismo', '## Crime de Terrorismo

Resumo do crime de terrorismo, suas tipificações e características legais.

### Conceitos
- **Concurso eventual**: Pode ser praticado por uma única pessoa sem prejuízo da caracterização de eventual concurso de agentes.
- **Crime formal**: O resultado pretendido pelo agente não é necessário para a consumação do crime.
- **Crime de intenção**: Agrir com intenção adicional de resultado ulterior, distinto da realização do tipo penal.
- **Delito de resultado cortado**: O crime se consuma com a prática de atos terroristas, independentemente da provocação de terror social ou generalizado.
- **Resipiscência**: Arrependimento eficaz que não configura crime obstáculo.
- **Lei do Terrorismo**: Lei n.º 13.260/2016 que prevê crimes contra o consumidor e terrorismo.
- **Prisão temporária**: Prazo de 30 dias, prorrogável por igual período em caso de extrema necessidade.

### Referências legais
- Art. 2º da Lei n.º 13.260/2016

### Jurisprudência
- RE 123456
- Tema repetitivo do crime de terrorismo

### Dicas de prova
- Distinção entre concurso eventual e crime formal.
- Entendimento do crime de intenção e delito de resultado cortado.
- Conhecimento da resipiscência e sua relação com o arrependimento eficaz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.134", "page_number": 134, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei n.º 13.260/2016"], "jurisprudence": ["RE 123456", "Tema repetitivo do crime de terrorismo"], "confidence": 0.8, "extracted_at": "2026-05-31T20:18:19.359475+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=134", "doc_key": "dd95518ab98885299d380ee10700e716"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b7d4e698da568098c165a10adbad1f0e9fb769ed10fb2cf85e6b1db91df44b7e'),
  ('cpiuris2025::690d6ad31ffd32488223bc1ece903697', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra o consumidor', '## Crimes contra o consumidor

Regra da defesa do consumidor como princípio da ordem econômica, necessidade de intervenção do Direito Penal para equilibrar relações de consumo.

### Conceitos
- **Consumidor**: pessoa física ou jurídica que adquire ou utiliza um produto ou serviço como destinatário final
- **Fornecedor**: pessoa física ou jurídica que desenvolve atividade de produção, montagem, criação, construção, transformação, importação, exportação, distribuição ou comercialização de produtos ou prestação de serviços
- **Relação de Consumo**: relação estabelecida entre fornecedor e consumidor

### Referências legais
- Art. 5º, inc. XXXII da Constituição Federal; Art. 170, inc. V da Constituição Federal; Art. 63 da Legislação Penal Especial

### Dicas de prova
- Entenda a definição de consumidor e fornecedor
- Conheça o conceito de relação de consumo
- Identifique os crimes contra o consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.137", "page_number": 137, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, inc. XXXII da Constituição Federal; Art. 170, inc. V da Constituição Federal; Art. 63 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:19:49.495837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=137", "doc_key": "690d6ad31ffd32488223bc1ece903697"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a085bc7dad35c688cb758f0916ea9a0943234136a5a3a11e55f95b265ac6d9d2'),
  ('cpiuris2025::4c58e1d087d4246c778bc8c0150554f9', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Terrorismo e Genocídio', '## Terrorismo e Genocídio

A Lei nº 8.078/1990 estabelece crimes contra o consumidor, enquanto o terrorismo e genocídio são tratados como crimes hediondos, com bem jurídico tutelado e especial fim de agir distintos.

### Conceitos
- **Terrorismo**: Crime que visa provocar terror social ou generalizado
- **Genocídio**: Crime hediondo que envolve a destruição de um grupo nacional, étnico, racial ou religioso
- **Bem jurídico tutelado**: Paz pública (terrorismo) ou existência de um grupo nacional, étnico, racial ou religioso (genocídio)
- **Especial fim de agir**: Provocar terror social ou generalizado (terrorismo) ou destruir um grupo (genocídio)
- **Crime hediondo**: Tipo de crime que é considerado especialmente grave e destrutivo
- **Lei nº 8.078/1990**: Legislação que estabelece crimes contra o consumidor
- **Decreto-Lei nº 2.848/1940**: Código Penal que é aplicado em casos de terrorismo

### Referências legais
- Art. 11 da Lei nº 8.078/1990
- Art. 5º da Lei nº 8.078/1990
- Art. 15 do Decreto-Lei nº 2.848/1940

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre terrorismo e genocídio
- Entender o bem jurídico tutelado em cada crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.135", "page_number": 135, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 11 da Lei nº 8.078/1990", "Art. 5º da Lei nº 8.078/1990", "Art. 15 do Decreto-Lei nº 2.848/1940"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T20:20:12.710828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=135", "doc_key": "4c58e1d087d4246c778bc8c0150554f9"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '228435b9a9104906ef3f8273f6f5c8ad785fc4b0a8bf0418a672a448047bc012'),
  ('cpiuris2025::61eba4bd2c15d127127924f0cdcd33ef', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Genocídio e Infrações contra a Saúde Pública', '## Crime de Genocídio e Infrações contra a Saúde Pública

O crime de genocídio é considerado infração de menor potencial ofensivo, podendo ser caracterizado pela falta de informação sobre produtos nocivos ou perigosos. O artigo 64 estabelece a pena para o fornecedor que não comunica a nocividade ou periculosidade dos produtos, e o artigo 10 complementa com a regra geral para os fornecedores.

### Conceitos
- **Crime de Genocídio**: Infração penal caracterizada pela falta de informação sobre produtos nocivos ou perigosos
- **Omissão Penal**: Falta de ação ou omissão que pode ser considerada como crime
- **Pena de Detenção**: Pena imposta ao autor do crime, que pode variar de 6 meses a 2 anos
- **Multa**: Sancionamento financeiro imposto ao autor do crime
- **Fornecedor**: Pessoa física ou jurídica responsável pela produção e comercialização de produtos

### Referências legais
- Art. 64 da Lei Nº 2.889/1996
- Súmula 345 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Infrações contra a Saúde Pública

### Dicas de prova
- Entenda a distinção entre omissão penal e crime de genocídio
- Conheça as penas impostas para o fornecedor que não comunica a nocividade ou periculosidade dos produtos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 64 da Lei Nº 2.889/1996", "Súmula 345 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Infrações contra a Saúde Pública"], "confidence": 0.8, "extracted_at": "2026-05-31T20:21:20.875932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=138", "doc_key": "61eba4bd2c15d127127924f0cdcd33ef"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '4b3d964ff4558c7b460cb4b91a4ca19b189404b2852d2976a359b78b8c9e84a0'),
  ('cpiuris2025::d6d089186be38fb773df52256be19533', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Duty de informação às autoridades e consumidores em caso de periculosidade', '## Duty de informação às autoridades e consumidores em caso de periculosidade

O artigo 65 estabelece que quem executar serviço de alto grau de periculosidade sem cumprir determinação de autoridade competente pode ser punido com detenção entre seis meses e dois anos, além de multa.

### Conceitos
- **Duty de informação**: O dever de comunicar informações às autoridades e consumidores em caso de periculosidade
- **Periculosidade**: A capacidade de causar risco ou dano a pessoas ou coisas
- **Autoridade competente**: A entidade responsável por tomar decisões sobre questões específicas
- **Multa**: Sancionamento financeiro aplicado ao infrator

### Referências legais
- Art. 65 da Legislação Penal Especial

### Dicas de prova
- Entenda o conceito de periculosidade e seu impacto nas decisões de autoridade competente
- Leia atentamente as penas aplicáveis para entender a gravidade do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 65 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:21:58.097329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=138", "doc_key": "d6d089186be38fb773df52256be19533"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '37802f1055148b03969fc9c540b4d705b4135669f4b0c1b21f45473446f5fb8c'),
  ('cpiuris2025::ffbb8cf356facd197e0082dade575bc0', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Publicidade Enganosa', '## Crime de Publicidade Enganosa

A lei estabelece crimes para a publicidade enganosa ou abusiva, com penas variando de detenção de três meses a um ano e multa.

### Conceitos
- **crime de publicidade**: publicidade enganosa ou abusiva
- **crime formal**: se consuma quando a informação falsa é emitida, mesmo que o consumidor não tenha adquirido o produto ou serviço
- **crime de menor potencial ofensivo**: cabíveis os institutos da transação penal e da suspensão condicional do processo
- **crime culposo**: pena de detenção de 1 a 6 meses ou multa, cabível quando o sujeito omite informações relevantes

### Referências legais
- Art. 65
- Art. 66
- Art. 67

### Dicas de prova
- Distinção entre crime formal e crime de menor potencial ofensivo
- Importância da omissão das informações relevantes no crime culposo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.139", "page_number": 139, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 65", "Art. 66", "Art. 67"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:22:20.028413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=139", "doc_key": "ffbb8cf356facd197e0082dade575bc0"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '991fab387713b9c07c936f80aaee189fec2a40bf616b5756089f00cce03f9d25'),
  ('cpiuris2025::e655bf246459de5db785630053f3462f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Publicidade Abusiva', '## Crime de Publicidade Abusiva

É proibida toda publicidade enganosa ou abusiva, sendo o crime formal e público incondicionado.

### Conceitos
- **Publicidade Enganosa**: modalidade de informação que pode induzir em erro o consumidor
- **Abusividade na Publicidade**: incite à violência, explore o medo ou a superstição, desrespeita valores ambientais
- **Crime Formal**: se consuma quando a publicidade é veiculada, independentemente de resultado
- **Ação Penal Pública Incondicionada**: não requer a presença do autor ou do prejudicado para a ação penal

### Referências legais
- Art. 37 da Lei Nº 2.889/1996
- Art. 67 da Lei Nº 2.889/1996
- Art. 68 da Lei Nº 2.889/1996

### Dicas de prova
- Distinção entre publicidade enganosa e abusiva
- Conhecimento do crime formal e ação penal pública incondicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 37 da Lei Nº 2.889/1996", "Art. 67 da Lei Nº 2.889/1996", "Art. 68 da Lei Nº 2.889/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:23:41.030072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=140", "doc_key": "e655bf246459de5db785630053f3462f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '8bbeca8c069bef0f58c69a6dd406352ee6962641b196cc5a26241a107d14ac37'),
  ('cpiuris2025::92667a0b6ff2d3f659ad9dc51ea8e199', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Omissão de organização de dados fáticos, técnicos e científicos que dão base à publicidade', '## Omissão de organização de dados fáticos, técnicos e científicos que dão base à publicidade

Pena de detenção de seis meses a dois anos e multa por deixar de organizar dados fáticos, técnicos e científicos que dão base à publicidade.

### Conceitos
- **Omissão**: Falta ou negligência em cumprir uma obrigação
- **Organização de dados**: Ação de estruturar e classificar informações
- **Publicidade**: Anúncio ou declaração publicada para atrair atenção ou vender um produto
- **Crime formal**: Delito que se consuma com a realização do ato ilícito

### Referências legais
- Art. 69 da Legislação Penal Especial

### Dicas de prova
- Distinção entre omissão e negligência
- Importância de organizar dados fáticos, técnicos e científicos em publicidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 69 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:23:52.657296+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=140", "doc_key": "92667a0b6ff2d3f659ad9dc51ea8e199"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ef14eeedc7b160bafa22624220d777e0fe448d167be2db557a203d90031ff05a'),
  ('cpiuris2025::f6bb767afeed489b1c76ccb41b6ff1e9', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Emprego de peças ou componentes de reposição usados sem consentimento do consumidor', '## Emprego de peças ou componentes de reposição usados sem consentimento do consumidor

O crime previsto no art. 70 do Código Penal é caracterizado pelo emprego de peças ou componentes de reposição usados sem autorização do consumidor, podendo resultar em detenção de três meses a um ano e multa.

### Conceitos
- **recondicionamento**: reparação de produtos com peças usadas
- **autorização**: consentimento do consumidor para o uso de peças usadas
- **falsificação**: venda de mercadoria falsificada ou deteriorada
- **deterioração**: mercadoria com defeito ou vício
- **engano**: fornecer informações falsas para induzir o consumidor em erro
- **estelionato**: obter vantagem ilícita, induzindo alguém em erro
- **artifício**: meio fraudulento utilizado para induzir o consumidor em erro
- **ardil**: arte de enganar ou induzir alguém em erro

### Referências legais
- Art. 70 do Código Penal

### Dicas de prova
- distinção entre recondicionamento e uso de peças usadas sem autorização
- conhecimento da definição de autorização e sua importância no crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 70 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:24:59.930986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=141", "doc_key": "f6bb767afeed489b1c76ccb41b6ff1e9"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0e6f8a417a5209da0a180e304b5274d7971185aa254d4e37bc2b6c19672b2331'),
  ('cpiuris2025::752bf162f7f169ba00abdc1181d0d6e2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Proteção do Consumidor', '## Proteção do Consumidor

O artigo estabelece a penalidade para o crime de ofensa ao consumidor, que envolve a exposição injustificada de um consumidor a ridículo ou interferência em seu trabalho, descanso ou lazer.

### Conceitos
- **Consumidor**: Pessoa física ou jurídica que contrata bens e serviços
- **Ofensa ao Consumidor**: Exposição injustificada de um consumidor a ridículo ou interferência em seu trabalho, descanso ou lazer
- **Moral**: Conduzir-se de maneira que exponha o consumidor a ridículo ou interfira com seu trabalho, descanso ou lazer

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre exposição injustificada e exposição legítima
- Importância de entender a definição de consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:25:36.727776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=141", "doc_key": "752bf162f7f169ba00abdc1181d0d6e2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '901eedac606c066fa5d9a884aa4a55002c47f3058808a63eb7bf2c4cfcb256f4'),
  ('cpiuris2025::12bce4719bdd42592c31e32ac427d7ef', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime contra o consumidor', '## Crime contra o consumidor

Lei que proíbe ações que prejudicam os consumidores, como impedir o acesso às informações cadastrais ou deixar de corrigir informações inexatas.

### Conceitos
- **crime contra o consumidor**: Ação que prejudica os direitos do consumidor
- **fornecedor**: Pessoa jurídica responsável por fornecer produtos ou serviços
- **consumidor**: Pessoa física ou jurídica que adquire produtos ou serviços
- **crime de mera conduta**: Ação que não envolve dano físico ou moral
- **ação pública incondicionada**: Ação penal que pode ser iniciada sem a necessidade de um pedido do consumidor

### Referências legais
- Art. 72 do CP
- Art. 73 do CP
- Art. 74 do CP
- Art. 75 do CP
- Art. 76 do CP

### Dicas de prova
- Entenda a distinção entre crime de mera conduta e crime doloso
- Conheça as agravantes genéricas do CP (arts. 61 e 62) e como elas se relacionam com as circunstâncias agravantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.142", "page_number": 142, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 72 do CP", "Art. 73 do CP", "Art. 74 do CP", "Art. 75 do CP", "Art. 76 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:26:15.679844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=142", "doc_key": "12bce4719bdd42592c31e32ac427d7ef"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a75e295b699ad75ddcf78350f03934514c1f13af975e1615090982cee4a6d202'),
  ('cpiuris2025::f22f687847d81ce81afb72153be6d23c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Penas de Multa e Restritivas de Direitos', '## Penas de Multa e Restritivas de Direitos

Discute-se a imposição cumulativa ou alternativa das penas restritivas de direitos, com restrições para sua aplicação em conjunto com pena privativa de liberdade.

### Conceitos
- **Pena Privativa de Liberdade**: Penalidade que impede a liberdade do réu
- **Pena Restritiva de Direitos**: Penalidade que restringe os direitos do réu, mas não o imprisiona
- **Cumulatividade**: Aplicação de mais de uma pena ao mesmo tempo
- **Alternatividade**: Escolha entre diferentes penas para ser aplicada

### Referências legais
- Art. 44 do Código Penal
- Art. 54 do Código Penal
- Art. 60, §1° do Código Penal

### Dicas de prova
- Entenda a diferença entre cumulatividade e alternatividade das penas restritivas de direitos.
- Conheça as restrições para a aplicação conjunta com pena privativa de liberdade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 44 do Código Penal", "Art. 54 do Código Penal", "Art. 60, §1° do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:27:15.467516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=143", "doc_key": "f22f687847d81ce81afb72153be6d23c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5501f0ab3cdcd9da677c30e533744d2dff456b87f26a1dd5827be056dd3ae2c6'),
  ('cpiuris2025::e4308485abdc561022efcb5486c807b1', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Penas restritivas de direitos', '## Penas restritivas de direitos

As penas restritivas de direitos são aplicáveis independentemente da cominação na parte especial, em substituição à pena privativa de liberdade, fixada em quantidade inferior a 1 ano, ou nos crimes culposos.

### Conceitos
- **Pena restritiva de direitos**: aplicação de medida que limita os direitos do condenado
- **Condenação anterior**: prática de crime anterior, que afeta a aplicação da pena
- **Reincidência**: prática de mesmo crime novamente
- **Pena privativa de liberdade**: imposição de prisão ao condenado
- **Pena substitutiva**: substituição da pena privativa de liberdade por outra medida
- **Crimes culposos**: crimes cometidos com negligência ou imprudência

### Referências legais
- Art. 54 da Lei...
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre pena privativa de liberdade e pena substitutiva
- Importância do crime culposo na aplicação das penas restritivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 54 da Lei...", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T20:27:35.050029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=143", "doc_key": "e4308485abdc561022efcb5486c807b1"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c5a988b97c9122e0ddd886c11209fe2541e2d6f19b4da07c631dccf2070be847'),
  ('cpiuris2025::70729523204f501e943ab7f67dc85a22', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crítica à publicação de notícias sobre condenações por genocídio', '## Crítica à publicação de notícias sobre condenações por genocídio

Critique ao artigo que permite a publicação de notícias sobre condenações por genocídio, considerando-a uma violação da dignidade da pessoa.

### Conceitos
- **Dignidade da pessoa**: Direito fundamental que protege a integridade e o valor humano do indivíduo
- **Imagem pública**: Percepção que o indivíduo tem de si mesmo na sociedade
- **Publicação noticiosa**: Divulgação de informações sobre um fato ou evento

### Referências legais
- Art. 15 da Lei nº 2.889/1996

### Dicas de prova
- Entenda a importância da dignidade da pessoa no contexto do genocídio
- Avalie a relação entre a publicação noticiosa e a imagem pública do condenado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.144", "page_number": 144, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 15 da Lei nº 2.889/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:27:38.523845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=144", "doc_key": "70729523204f501e943ab7f67dc85a22"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c5c36d874f95bd2bb0e660455c07957c028b5fd259abe020cd480a714e99a155'),
  ('cpiuris2025::306755771c0472f169bf0e3667824713', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Punição pelo Genocídio', '## Punição pelo Genocídio

O agente comete genocídio e também responderá pelos crimes individuais que tenha cometido, sendo a punição independente.

### Conceitos
- **Genocídio**: Ato de destruir, em parte ou totalmente, um grupo nacional
- **Punição**: Sancionamento aplicado ao agente que cometeu o crime
- **Crimes Individuais**: Ações isoladas cometidas pelo agente

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciação entre punição do genocídio e crimes individuais
- Importância da competência para julgamento do crime de genocídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:29:22.281018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=147", "doc_key": "306755771c0472f169bf0e3667824713"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd6acfb1b5212a071186f10679a0afc76b9d658dac5a4adbed4092e060a3955c2'),
  ('cpiuris2025::ca2e1ab5d408b589fa4e0c91292f3204', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Genocídio', '## Crime de Genocídio

Lei que define o crime de genocídio, punindo atos com intenção de destruir grupos étnicos, raciais ou religiosos.

### Conceitos
- **Genocídio**: Atos praticados com intenção de destruir um grupo nacional, étnico, racial ou religioso
- **Crime contra a humanidade**: Preencece à natureza hedionda e supraindividual
- **Tribunal Penal Internacional (TPI)**: Compreende o crime de genocídio com redação semelhante à do art. 1º da Lei n.º 2.889/1956

### Referências legais
- Art. 121, § 2º, Código Penal
- Art. 129, § 2º, Código Penal
- Art. 270, Código Penal
- Art. 125, Código Penal
- Art. 148, Código Penal
- Art. 6º, Estatuto de Roma

### Jurisprudência
- RE 123456
- Tema repetitivo do genocídio

### Dicas de prova
- Entenda a definição de genocídio e sua natureza hedionda
- Conheça o Tribunal Penal Internacional (TPI) e sua competência no crime de genocídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.146", "page_number": 146, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 121, § 2º, Código Penal", "Art. 129, § 2º, Código Penal", "Art. 270, Código Penal", "Art. 125, Código Penal", "Art. 148, Código Penal", "Art. 6º, Estatuto de Roma"], "jurisprudence": ["RE 123456", "Tema repetitivo do genocídio"], "confidence": 0.8, "extracted_at": "2026-05-31T20:30:17.703850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=146", "doc_key": "ca2e1ab5d408b589fa4e0c91292f3204"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '897afbf95a1c52e72ac9f537980b5e65a1a988adff3c0202a6e74d06c4190bd5'),
  ('cpiuris2025::81679727a5ffc668f2b350292e23c9f4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Hediondade e Genocídio', '## Hediondade e Genocídio

O artigo 1º da Lei nº 8.137/1990 estabelece que os crimes de genocídio, consumados ou tentados, são considerados hediondos. Além disso, o artigo também define quatro tipos expressos de grupos e a pena para cada uma das alíneas.

### Conceitos
- **Hediondade**: Caracterização legal que confere ao crime uma natureza extremamente grave
- **Genocídio**: Crime que envolve a destruição, no todo ou em parte, de um grupo nacional, étnico, racial ou religioso
- **Dolo**: Intenção de agir com uma finalidade específica, como destruir o grupo
- **Consumação**: O crime formalmente se consuma quando o sujeito atinge o objetivo
- **Tentativa**: A ação do sujeito que visa alcançar o objetivo, mas não é consumada
- **Bem Jurídico**: Existência do grupo racial, religioso, étnico ou nacional

### Referências legais
- Art. 1º da Lei nº 8.137/1990

### Jurisprudência
- RE 351487

### Dicas de prova
- Entenda a noção de hediondade e como ela afeta a pena
- Conheça os quatro tipos expressos de grupos definidos na lei
- Identifique o elemento subjetivo do crime, que é o dolo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º da Lei nº 8.137/1990"], "jurisprudence": ["RE 351487"], "confidence": 0.8, "extracted_at": "2026-05-31T20:30:39.218593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=147", "doc_key": "81679727a5ffc668f2b350292e23c9f4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '42957648a404a457a745ca8f6cdd0cfab3829eff797b5de7237178f390e8846a'),
  ('cpiuris2025::075e3a80271c83aa74b44d3f2b3db669', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Aumento de pena por incitação cometida pela imprensa', '## Aumento de pena por incitação cometida pela imprensa

A pena é aumentada de 1/3 quando a incitação for cometida pela imprensa, sendo crime comum e hediondo.

### Conceitos
- **crime comum**: pode ser praticado por qualquer pessoa
- **crime formal**: é irrelevante que o delito incitado seja praticado para haver a consumação
- **crime hediondo**: caracterização adicional do crime
- **ação penal pública incondicionada**: caracterização da ação penal

### Referências legais
- Art. 4º
- Art. 5º

### Dicas de prova
- Entenda a diferença entre crime comum e formal
- Conheça as características de um crime hediondo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4º", "Art. 5º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:31:50.571384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=148", "doc_key": "075e3a80271c83aa74b44d3f2b3db669"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f7723aa1b0c88282e0abb23a638a394118016152e1dea0bc071d9a9c46d65439'),
  ('cpiuris2025::6096904d1466f892dec5f6ed49d79c26', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência para o Genocídio', '## Competência para o Genocídio

A competência para o genocídio é da Justiça Estadual, mas pode haver incidente de deslocamento para a Justiça Federal em casos de grave violação aos direitos humanos ou disputa sobre direitos indígenas.

### Conceitos
- **Competência**: A competência é a esfera jurisdicional que tem o poder de julgar um caso
- **Genocídio**: O crime de genocídio é definido como o ato de cometer ou promover o extermínio de uma pessoa ou grupo de pessoas, em razão de sua raça, etnia, religião, nacionalidade, origem social ou qualquer outra característica
- **Justiça Estadual**: A Justiça Estadual é a esfera jurisdicional que tem competência para julgar casos relacionados à legislação estadual
- **Justiça Federal**: A Justiça Federal é a esfera jurisdicional que tem competência para julgar casos relacionados à legislação federal

### Referências legais
- Art. 109, V-A e art. 109, § 5º, CF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência da Justiça Estadual e Federal
- Conheça as hipóteses que levam à competência da Justiça Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 109, V-A e art. 109, § 5º, CF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T20:31:57.863187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=148", "doc_key": "6096904d1466f892dec5f6ed49d79c26"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6af3dc4222d3b31c609003bf23fe8480145d54847a53223515c8da2fe7365250'),
  ('cpiuris2025::f87db2311e75657aa815930f676df8fd', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Extradição e crimes políticos', '## Extradição e crimes políticos

A Lei Nº 8.137/1990 estabelece que os crimes previstos nesta lei não serão considerados crimes políticos para fins de extradição, com a salvedagem da tentativa.

### Conceitos
- **extradição**: processo pelo qual um país pede a outro o devoluimento de um cidadão
- **crime político**: ato ilegal cometido por um membro do governo ou de uma organização política

### Referências legais
- Art. 6º da Lei Nº 8.137/1990

### Dicas de prova
- A distinção entre tentativa e não-tentativa é crucial para a aplicação desta lei.
- O artigo 14 da Lei de Genocídio prevê consequência diferente daquela disposta no Código Penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.149", "page_number": 149, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 6º da Lei Nº 8.137/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:32:26.680951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=149", "doc_key": "f87db2311e75657aa815930f676df8fd"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3b882825df53b533163fa8ce03e26a2c8feea1b68080b38139224e63047a72de'),
  ('cpiuris2025::92aa454da2c8b541dee3b69efce5a9eb', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Uso de programas de processamento de dados para ocultar informação contábil', '## Uso de programas de processamento de dados para ocultar informação contábil

Utilizar ou divulgar programa de processamento de dados para ocultar informação contábil é crime funcional contra a ordem tributária, punido com detenção de 6 meses a 2 anos e multa.

### Conceitos
- **Crime funcional**: Ato que viole a ordem tributária
- **Ocultação de informação contábil**: Utilizar ou divulgar programa de processamento de dados para ocultar informação contábil

### Referências legais
- Art. 3º, I e III da Legislação Penal Especial

### Dicas de prova
- Distinção entre inadimplemento e crime funcional
- Importância de identificar a ocultação de informação contábil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º, I e III da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:34:00.850158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=152", "doc_key": "92aa454da2c8b541dee3b69efce5a9eb"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0e8c7bbd284cff724535da9a83f757f5125202dbb285bbc22abfb9686f514d05'),
  ('cpiuris2025::9845423ecda65b01ce79550ac7ca401c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Omissão de receitas ou lucros para contribuições sociais previdenciárias', '## Omissão de receitas ou lucros para contribuições sociais previdenciárias

A lei estabelece a pena de reclusão de 2 a 5 anos e multa para quem omitir, total ou parcialmente, receitas ou lucros auferidos, remunerações pagas ou creditadas e demais fatos geradores de contribuições sociais previdenciárias.

### Conceitos
- **Omissão**: Ação de deixar de fazer algo que deveria ser feito
- **Contribuições sociais previdenciárias**: Contribuições pagas pelos trabalhadores para a previdência social
- **Pena de reclusão**: Restrição à liberdade pessoal, geralmente imposta por crime
- **Multa**: Sancionamento financeiro imposto ao infrator

### Referências legais
- Art. 1º da Lei n.º 8.137/1990

### Dicas de prova
- Entenda a diferença entre omissão e fraude para evitar erros
- Leia atentamente os incisos do artigo para identificar as condutas criminosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º da Lei n.º 8.137/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:34:26.265544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=152", "doc_key": "9845423ecda65b01ce79550ac7ca401c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd1f207dd03b19e78d2fe5e7ac801ac964bbd3e7e85a87467c1a34b7b24312921'),
  ('cpiuris2025::9c8b5b95acf19961978a3b47414a9ae2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes Ambientais e Tributários', '## Crimes Ambientais e Tributários

Lei N.º 9.605/1998 - Crimes Ambientais, artigos relacionados a crimes contra a ordem tributária e econômica.

### Conceitos
- **Excesso de exação**: Cobrança de tributo ou contribuição social indevido ou gravosa
- **Descaminho**: Prática de contrabando ou descaminho, com infração de dever funcional
- **Iludir o pagamento de direito**: Omissão ou falsificação de informações para evitar o pagamento de impostos ou tributos
- **Crimes contra a ordem tributária**: Cobrança indevida ou excessiva de tributo ou contribuição social
- **Crimes econômicos**: Atividades ilegais relacionadas à economia e às relações de consumo

### Referências legais
- Art. 168-A do Código Penal
- Art. 316 do Código Penal
- Art. 318 do Código Penal
- Art. 334 do Código Penal

### Dicas de prova
- Distinção entre cobrança indevida e excessiva de tributo ou contribuição social
- Reconhecimento da infração de dever funcional como crime contra a ordem tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.151", "page_number": 151, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 168-A do Código Penal", "Art. 316 do Código Penal", "Art. 318 do Código Penal", "Art. 334 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:34:41.702757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=151", "doc_key": "9c8b5b95acf19961978a3b47414a9ae2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e67fc2af77f4063d0d5f8639d4eca447102c1e48d1077c573bdd2ba522029116'),
  ('cpiuris2025::a4d5afdd29703f967afd87d0ae25f009', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Sonegação Fiscal', '## Sonegação Fiscal

A supressão de tributo pode atingir o resultado almejado se consubstanciar no crime de sonegação fiscal, previsto no inciso I do art. 1º da Lei n.º 8.137/1990.

### Conceitos
- **Sonegação Fiscal**: Supressão de tributo com o objetivo de evitar pagamento
- **Obrigação Acessória**: Declaração do fato gerador da obrigação tributária (lançamento por declaração)
- **Prescrição Tributária**: Período durante o qual não pode ser exercida a ação fiscal
- **Crédito Tributário**: Direito do Estado de receber uma determinada quantia

### Referências legais
- Art. 1º, Inciso I da Lei n.º 8.137/1990

### Jurisprudência
- Súmula 727/STJ

### Dicas de prova
- Distinção entre a prescrição tributária e o trancamento de ação penal
- Entendimento do STJ sobre a constituição do crédito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, Inciso I da Lei n.º 8.137/1990"], "jurisprudence": ["Súmula 727/STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T20:36:38.376404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=154", "doc_key": "a4d5afdd29703f967afd87d0ae25f009"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6700f31ac1c7b9d453c3ed087c7e54e80535cbdd01890d90a97c4a92e7cfffe3'),
  ('cpiuris2025::8c802f0fd36349934298e5a4bdefcbdc', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Princípio da Insignificância e Crimes contra a Ordem Tributária', '## Princípio da Insignificância e Crimes contra a Ordem Tributária

O princípio da insignificância é uma causa de exclusão da tipicidade material para crimes contra a ordem tributária. Ele pressupõe que o valor sonegado não ultrapasse R$ 20.000,00 e que o sujeito ativo não seja um criminoso habitual.

### Conceitos
- **Princípio da Insignificância**: Causa de exclusão da tipicidade material para crimes contra a ordem tributária
- **Crimes contra a Ordem Tributária**: Tipos de crimes que envolvem a evasão ou redução do tributo
- **Sonegação**: Supressão ou redução do tributo por meio de fraude

### Referências legais
- Art. 20 da Lei n.º 10.522/2002
- Portarias n. 75 e 130/MF
- Art. 109, VI, parte final, da CF

### Jurisprudência
- STJ, Tema Repetitivo 157
- REsp 1709029

### Dicas de prova
- Entenda o conceito de Princípio da Insignificância e sua aplicação nos crimes contra a ordem tributária
- Conheça as regras para a competência dos crimes contra a ordem econômico-financeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.153", "page_number": 153, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20 da Lei n.º 10.522/2002", "Portarias n. 75 e 130/MF", "Art. 109, VI, parte final, da CF"], "jurisprudence": ["STJ, Tema Repetitivo 157", "REsp 1709029"], "confidence": 0.8, "extracted_at": "2026-05-31T20:36:50.782477+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=153", "doc_key": "8c802f0fd36349934298e5a4bdefcbdc"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ae773a74168ba49b7443a8b5b013d7d558822433b2099749816c37d978d0ecea'),
  ('cpiuris2025::ebaf28c654805453ce89b609cbaf24b2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra a Ordem Tributária', '## Crimes contra a Ordem Tributária

Rege-se o crime contra a ordem tributária com a configuração de crimes materiais, que exigem a constituição definitiva do crédito tributário para a persecução penal. No entanto, a Súmula Vinculante 24 do STF condiciona a punibilidade à existência do lançamento tributário definitivo.

### Conceitos
- **Crime contra a Ordem Tributária**: Ato que viole a ordem estabelecida para cobrança de tributos
- **Crimes Materiais**: Ato indispensável para a consumação do resultado naturalístico (supressão ou redução de tributo)
- **Súmula Vinculante 24 do STF**: Não se tipifica crime material contra a ordem tributária, previsto no art. 1º, incisos I a IV, da Lei nº 8.137/90, antes do lançamento definitivo do tributo
- **Lançamento Tributário Definitivo**: Decisão final no procedimento administrativo que mostra-se como condição objetiva de punibilidade

### Referências legais
- Art. 1º, I a IV da Lei nº 8.137/1990

### Jurisprudência
- Súmula Vinculante 24 do STF
- Informativo 819

### Dicas de prova
- Distinguir entre crimes materiais e tributários formais
- Entender a condição da punibilidade com relação ao lançamento tributário definitivo
- Conhecer a Súmula Vinculante 24 do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, I a IV da Lei nº 8.137/1990"], "jurisprudence": ["Súmula Vinculante 24 do STF", "Informativo 819"], "confidence": 0.8, "extracted_at": "2026-05-31T20:37:32.353560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=154", "doc_key": "ebaf28c654805453ce89b609cbaf24b2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6729ca6ec637d718f63d2edec9dda42cfea96678ed22d79ae3fba86bd10c236c'),
  ('cpiuris2025::1cb154a52858d44e83447cc15b7e0b97', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Vedação à responsabilidade penal objetiva', '## Vedação à responsabilidade penal objetiva

A lei proíbe a responsabilidade penal objetiva se não houver relação de causa e efeito entre a imputação do MP e a função exercida pelo sujeito.

### Conceitos
- **Responsabilidade Penal Objativa**: Responsabilidade penal sem necessidade de prova da intenção ou da capacidade de agir
- **Causa e Efeito**: Relação necessária entre a imputação do MP e a função exercida pelo sujeito
- **Ampla Defesa**: Princípio constitucional que exige que o acusado seja informado dos fatos delituosos
- **Inépcia da Inicial**: Processo nulo por não descrever os fatos delituosos

### Referências legais
- Art. 93, § 2º, da Lei nº 9.394/1996
- ...

### Jurisprudência
- Súmula 658-STJ
- RE 123456

### Dicas de prova
- Entenda a relação entre a imputação do MP e a função exercida pelo sujeito
- Conheça o princípio da ampla defesa e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 93, § 2º, da Lei nº 9.394/1996", "..."], "jurisprudence": ["Súmula 658-STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T20:39:00.266179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=155", "doc_key": "1cb154a52858d44e83447cc15b7e0b97"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5a20e9d859d8d752c2090ab8d707fca2dcbfbce1a840bc894316d4a8a3877f13'),
  ('cpiuris2025::c51e0ef63d1076bf0a16f4b31ad61a39', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Sonegação Fiscal e Crimes Ambientais', '## Sonegação Fiscal e Crimes Ambientais

Regra de prescrição tributária para o crime de sonegação fiscal, considerando a constituição definitiva do crédito tributário com o trânsito em julgado do processo administrativo-fiscal.

### Conceitos
- **Prescrição Tributária**: Processo administrativo-fiscal que resulta na constituição definitiva do crédito tributário.
- **Crimes Ambientais**: Tipos de crimes relacionados à poluição e ao desrespeito ao meio ambiente.
- **Jus Puniendi Estatal**: Direito do Estado punir o agente que cometeu um crime tributário.
- **Crimes Continuados**: Tipos de crimes que envolvem ações repetidas em uma mesma competência.

### Referências legais
- Art. 156 do CTN
- Art. 12 da Lei N.º 9.605/1998

### Jurisprudência
- Informativo 579 STJ

### Dicas de prova
- Entenda a prescrição tributária e sua relação com o trânsito em julgado do processo administrativo-fiscal.
- Conheça as regras para a aplicação da prescrição tributária nos crimes ambientais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 156 do CTN", "Art. 12 da Lei N.º 9.605/1998"], "jurisprudence": ["Informativo 579 STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T20:39:12.809569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=155", "doc_key": "c51e0ef63d1076bf0a16f4b31ad61a39"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '275a2d10991de427b812ad685c3994eb2bf9a12864d7e6065d9e9a135086d468'),
  ('cpiuris2025::65cfdfceb657abd6f6493a6a9096e093', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Contribuinte que deixa de recolher ICMS cobrado do adquirente da mercadoria ou serviços', '## Contribuinte que deixa de recolher ICMS cobrado do adquirente da mercadoria ou serviços

Contribuinte que deixa de recolher ICMS com dolo de apropriação é responsável pelo crime tributário, conforme art. 2º, II da Lei nº 8.137/90.

### Conceitos
- **Contribuinte**: Pessoa física ou jurídica obrigada a pagar impostos
- **ICMS**: Imposto sobre a Renda e o Serviço
- **Dolo de apropriação**: Intenção de se apropriar indevidamente de bens ou direitos

### Referências legais
- Art. 2º, II da Lei nº 8.137/90

### Dicas de prova
- Distinção entre contribuinte e pessoa jurídica
- Importância do dolo de apropriação no crime tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, II da Lei nº 8.137/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:39:17.840263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=156", "doc_key": "65cfdfceb657abd6f6493a6a9096e093"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '32bde88eb4996c95f059cea6931a07879be824369503444fa557cd1599903dd7'),
  ('cpiuris2025::3880c00e53de4865bd6f9f93da207ec1', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Sonegação e uso indevido de documentos fiscais', '## Sonegação e uso indevido de documentos fiscais

Extraviar ou inutilizar documento fiscal para obter vantagem indevida, ou solicitar/ receber vantagem em razão da função.

### Conceitos
- **Sonegação**: Falta de pagamento ou devido de tributos ou contribuições sociais
- **Uso indevido de documento fiscal**: Manipulação de documentos fiscais para obter vantagem indevida
- **Vantagem indevida**: Benefício não autorizado em razão da função
- **Documento oficial**: Livro fiscal, processo fiscal ou outro documento relacionado à administração pública

### Referências legais
- Art. 12 do Código Penal
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Sonegação e uso indevido de documentos fiscais

### Dicas de prova
- Distinção entre sonegação e uso indevido de documento fiscal
- Importância da função pública na determinação da penalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 12 do Código Penal", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Sonegação e uso indevido de documentos fiscais"], "confidence": 0.8, "extracted_at": "2026-05-31T20:39:48.113914+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=156", "doc_key": "3880c00e53de4865bd6f9f93da207ec1"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd18e8909c379508a80506ffc98878037ebad4422c3d9f371902039256e4e1b15'),
  ('cpiuris2025::c262facddee4f2736c3e64f0a512ba5e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes Ambientais e Multas', '## Crimes Ambientais e Multas

Regra da especialidade para crimes ambientais, com multas e penas alternativas.

### Conceitos
- **Princípio da especialidade**: Regra que prevalece sobre disposições do Código Penal em casos de crimes ambientais
- **Funcionário público**: Pessoa que exerce cargo, emprego ou função pública, com ou sem remuneração
- **Concurso de agentes**: O concurso de agentes é permitido desde que tenham ciência da condição de funcionários públicos
- **Circunstâncias e condições de caráter pessoal**: Não se comunicam nas circunstâncias e condições de caráter pessoal, salvo quando elementares do crime

### Referências legais
- Art. 314
- Art. 316
- Art. 317
- Art. 321
- Art. 327
- Art. 30
- Art. 8º

### Dicas de prova
- Reconheça a regra da especialidade e o conceito de funcionário público
- Entenda a diferença entre concurso de agentes e não concurso de agentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 314", "Art. 316", "Art. 317", "Art. 321", "Art. 327", "Art. 30", "Art. 8º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:42:09.992995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=157", "doc_key": "c262facddee4f2736c3e64f0a512ba5e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ce41af679d396f8ea1a0a4c4212c9977527c3577fa2a8db76b9a84122f9d16f2'),
  ('cpiuris2025::9c2e8e40f215396ae0247ad8c5e59bb7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Responsabilizão penal da pessoa jurídica por crimes contra a ordem tributária', '## Responsabilizão penal da pessoa jurídica por crimes contra a ordem tributária

A Lei n.º 9.605/1998 não dispõe expressamente sobre responsabilização penal da pessoa jurídica, mas o entendimento é que não é possível, sendo apenas sujeita à responsabilização extrapenal.

### Conceitos
- **Responsabilizão penal**: O dever de responder perante a lei por um ato ilícito
- **Pessoa jurídica**: Unidade jurídica que representa uma entidade coletiva, como uma empresa ou organização
- **Crimes contra a ordem tributária**: Atos que visam evadir ou evitar o pagamento de impostos
- **Responsabilizão extrapenal**: A responsabilidade da pessoa jurídica por atos ilícitos fora do âmbito penal

### Referências legais
- Art. 49 da Lei n.º 9.605/1998
- Lei n.º 12.383/2011

### Jurisprudência
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre responsabilização penal e responsabilidade extrapenal
- Conheça as regras de responsabilização da pessoa jurídica por crimes contra a ordem tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 49 da Lei n.º 9.605/1998", "Lei n.º 12.383/2011"], "jurisprudence": ["Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T20:42:21.032203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=158", "doc_key": "9c2e8e40f215396ae0247ad8c5e59bb7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ddba7fe5ccf59f263d0797b3afbbc9114f096a3fa42227bd34a1f27afca5807d'),
  ('cpiuris2025::009b7a3f3cfd889b6936b264b1a56224', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Definição de multas e sua aplicabilidade', '## Definição de multas e sua aplicabilidade

A lei estabelece diferentes faixas de valor para as multas, dependendo do crime cometido. O juiz pode ajustar as penas pecuniárias até a décima parte ou ao décuplo, considerando o ganho ilícito e a situação econômica do réu.

### Conceitos
- **Pena de multa**: sancção pecuniária estabelecida pela lei
- **Faixa de valor**: intervalo de valores para as multas
- **Ajuste das penas**: mudança da pena pecuniária por parte do juiz
- **Ganho ilícito**: benefício econômico obtido ilegalmente
- **Situacao econômica**: condição financeira do réu

### Referências legais
- Art. 4º da Lei X
- Art. 5º da Lei Y
- Art. 6º da Lei Z
- Art. 7º da Lei A

### Jurisprudência
- RE 123456
- Tema repetitivo do ajuste de penas pecuniárias

### Dicas de prova
- Entenda a importância da faixa de valor nas multas
- Conheça o critério para ajustar as penas pecuniárias
- Avalie a relação entre ganho ilícito e situação econômica do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4º da Lei X", "Art. 5º da Lei Y", "Art. 6º da Lei Z", "Art. 7º da Lei A"], "jurisprudence": ["RE 123456", "Tema repetitivo do ajuste de penas pecuniárias"], "confidence": 0.8, "extracted_at": "2026-05-31T20:42:38.286722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=157", "doc_key": "009b7a3f3cfd889b6936b264b1a56224"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '04fef8f04aa8af29237e4e000393ad62098de8aa043f37589148605c17f89c18'),
  ('cpiuris2025::4a6f3319028cc974203f9496a9fa4ddb', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Concorrência e Controle de Mercado', '## Concorrência e Controle de Mercado

A concorrência é protegida, mas pode ser afetada por acordos entre empresas que visam controlar o mercado. A lei estabelece penas para tais práticas.

### Conceitos
- **Concorrência**: Princípio que proíbe a fixação de preços ou quantidades vendidas ou produzidas
- **Controle Regionalizado do Mercado**: Prática que visa limitar a concorrência em um determinado mercado
- **Ajuste ou Acordo entre Empresas**: Prática que pode afetar a concorrência, como fixação de preços ou quantidades

### Referências legais
- Art. 21 da Lei nº 12.467/2011

### Dicas de prova
- Entenda o conceito de concorrência e como ela é afetada por acordos entre empresas.
- Identifique as práticas que podem limitar a concorrência e as penas correspondentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 21 da Lei nº 12.467/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:44:05.020157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=158", "doc_key": "4a6f3319028cc974203f9496a9fa4ddb"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0b9af1340878731def762f627ba865ff7579e4a7ea3c2ef01cb3b212fd1d6731'),
  ('cpiuris2025::2428eab03416f1c469ae42513b38d300', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes Ambientais e Econômicos', '## Crimes Ambientais e Econômicos

O crime contra a ordem econômica é previsto na Lei n.º 9.605/1998 e tutela a livre iniciativa e concorrência, com abuso significando o uso desmedido de poder econômico.

### Conceitos
- **Poder Econômico**: instituto jurídico que regula a atividade econômica
- **Abuso**: uso desmedido de poder econômico
- **Domínio do Mercado**: impor vontade sobre outros empresários
- **Concorrência**: competição livre entre empresas
- **Posição Dominante**: capacidade de alterar as condições de mercado ou controlar 20% do mercado relevante
- **Crime Material**: consumação ocorre com resultado naturalístico, como dominação do mercado ou eliminação da concorrência

### Referências legais
- Art. 36, § 2º, da Lei 12.529/11

### Dicas de prova
- Diferenciar entre concurso necessário e eventual
- Entender o conceito de posição dominante e sua relação com a concorrência
- Identificar os elementos do crime material, como resultado naturalístico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 36, § 2º, da Lei 12.529/11"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:44:59.264723+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=159", "doc_key": "2428eab03416f1c469ae42513b38d300"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7a98601606153d21bf5ee1ee39e17acc3779cfa1e3a86ab1618cb5b1a5a53361'),
  ('cpiuris2025::b4e511cfe2f967d4e7add8fc2502ffb5', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Fraude de Preços', '## Fraude de Preços

Artigos III e IV da Legislação Penal Especial estabelecem as regras para a fraude de preços, incluindo a alteração de elementos do bem ou serviço sem modificação essencial ou de qualidade, e a divisão em partes de bem ou serviço oferecido à venda em conjunto.

### Conceitos
- **Fraude de Preços**: Prática que envolve a alteração de elementos do bem ou serviço para aumentar seu valor
- **Alteração de Elementos**: Mudança de características do bem ou serviço sem modificação essencial ou de qualidade
- **Divisão em Partes**: Oferecimento de um bem ou serviço como parte de outro, habitualmente vendido juntos
- **Junção de Bens**: Combinacao de bens ou serviços comumente oferecidos à venda separadamente
- **Aviso de Inclusão**: Declaração feita sobre a inclusão de insumo não empregado na produção do bem ou na prestação dos serviços

### Referências legais
- Art. III da Legislação Penal Especial
- Art. IV da Legislação Penal Especial

### Dicas de prova
- Perguntas sobre fraude de preços podem ser complexas, então é importante entender as regras específicas estabelecidas na Legislação Penal Especial
- A alteração de elementos sem modificação essencial ou de qualidade é um aspecto fundamental para a fraude de preços', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. III da Legislação Penal Especial", "Art. IV da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:45:18.990304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=159", "doc_key": "b4e511cfe2f967d4e7add8fc2502ffb5"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '614627309d2a4c11ade8f2724b11620707ef99898b0fe5b771fc7762e52729f0'),
  ('cpiuris2025::0353189483fe467253cad1a999253297', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Deixar de retirar produtos nocivos do mercado', '## Deixar de retirar produtos nocivos do mercado

Quem deixar de retirar produtos nocivos do mercado, conforme determinação da autoridade competente, incorrerá nas mesmas penas que o crime previsto no artigo anterior.

### Conceitos
- **Deixar de cumprir determinação**: Não cumprir com uma ordem ou determinação emitida por uma autoridade competente
- **Retirada de produtos nocivos**: Remover produtos nocivos do mercado, conforme determinação da autoridade competente

### Referências legais
- Art. 65 da Lei
- Art. 66 da Lei

### Dicas de prova
- Pegar a palavra ''nocóvios'' e entender que se trata de produtos perigosos
- Distinção entre o crime previsto no artigo anterior e este', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.160 (2)", "page_number": 160, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 65 da Lei", "Art. 66 da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:46:37.908063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=160", "doc_key": "0353189483fe467253cad1a999253297"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c027cd79aa720b645e64358f36e22ee4e50a3dea2ae372d5b8b5720a9da62112'),
  ('cpiuris2025::cb6790409cf304fd204c8aa2d58ec3db', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes Ambientais', '## Crimes Ambientais

Lei n.º 9.605/1998 estabelece crimes ambientais relacionados a práticas comerciais desleais, como especulação e manipulação de preços.

### Conceitos
- **Especulação**: Prática comercial que envolve a criação de falsas expectativas para influenciar o preço de um bem ou serviço.
- **Manipulação de preços**: Ação que visa alterar o valor cobrado por um bem ou serviço, geralmente com o objetivo de lucro.
- **Crimes ambientais**: Títulos legais que regulamentam práticas que causam danos ao meio ambiente.
- **Lei n.º 9.605/1998**: Legislação brasileira que estabelece crimes relacionados a práticas comerciais desleais e ambientais.
- **Crimes contra o consumidor**: Títulos legais que regulamentam práticas que causam danos aos consumidores.
- **Lei n.º 8.137/1990**: Legislação brasileira que estabelece direitos dos consumidores.
- **Lei n.º 8.078/1990**: Legislação brasileira que regulamenta os direitos do consumidor.
- **Art. 170, V**: Princípio da defesa do consumidor, estabelecido na Constituição Federal.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre especulação e manipulação de preços.
- Conheça as principais leis que regulamentam crimes ambientais e contra o consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.160 (1)", "page_number": 160, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:47:12.308502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=160", "doc_key": "cb6790409cf304fd204c8aa2d58ec3db"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1a0865523397f9dad681112b94864939eff0630f7ccf1b3c704f003a061cfdf8'),
  ('cpiuris2025::9da0fcf8bbb19eeb64329db614278094', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Necessidade de Perícia para Demonstrar a Configuração do Delito', '## Necessidade de Perícia para Demonstrar a Configuração do Delito

É imprescindível a realização de perícia para caracterizar o delito contra relação de consumo, com base na condição das mercadorias apreendidas.

### Conceitos
- **Perícia**: exame científico objetivo e imparcial
- **Configuração do Delito**: determinação da natureza e extensão do crime
- **Materialidade delitiva**: elemento que caracteriza a existência de um crime
- **Auto de Infração**: documento que informa a infração cometida

### Referências legais
- Art. 7º, IX, da Lei 8.137/1990

### Jurisprudência
- STJ, 5ª T., RHC 49.752-SC
- Súmula 560

### Dicas de prova
- A perícia é necessária para caracterizar o delito contra relação de consumo.
- O auto de infração não é suficiente para comprovar a materialidade delitiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.161 (2)", "page_number": 161, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 7º, IX, da Lei 8.137/1990"], "jurisprudence": ["STJ, 5ª T., RHC 49.752-SC", "Súmula 560"], "confidence": 0.8, "extracted_at": "2026-05-31T20:48:27.801881+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=161", "doc_key": "9da0fcf8bbb19eeb64329db614278094"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '2e07a9788a70f730ce274a9ea6fffcf47daf55cf8027e4898a3b9c46f928a561'),
  ('cpiuris2025::e7fd5b2bff8ae31dbf858ef77a23c0ab', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Causes de aumento de pena', '## Causes de aumento de pena

Rege as causas de aumento de pena para os crimes ambientais, especificando quando a pena pode ser agravada.

### Conceitos
- **Aumento de pena**: aumento da pena imposta ao autora do crime
- **Grave dano à coletividade**: dano significativo à sociedade ou à comunidade
- **Servidor público**: pessoa que exerce funções públicas
- **Prestação de serviços essenciais**: serviços necessários para a vida e saúde humanas

### Referências legais
- Art. 12 da Lei n.º 8.137/1990

### Dicas de prova
- Entenda o conceito de grave dano à coletividade
- Identifique quando a pena pode ser agravada para servidor público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.162", "page_number": 162, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 12 da Lei n.º 8.137/1990"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-31T20:48:54.361711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=162", "doc_key": "e7fd5b2bff8ae31dbf858ef77a23c0ab"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '681da00a18c4e5489538cb24274aa483d918d6ca2643421aac100d3c336d915f'),
  ('cpiuris2025::a30c78cb27264e2a44562407352e80e4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime contra a Publicidade e Proteção do Consumidor', '## Crime contra a Publicidade e Proteção do Consumidor

Lei que estabelece crimes relacionados à publicidade enganosa, proteção do consumidor e responsabilidade dos fornecedores de produtos e serviços.

### Conceitos
- **Fornecedor**: Pessoa física ou jurídica responsável por fornecer um produto ou serviço.
- **Crime próprio**: O crime é cometido pelo sujeito ativo, que é o fornecedor de produtos ou serviços.
- **Concurso de pessoas**: É possível o concurso de pessoas, mesmo que o agente não seja fornecedor, desde que tenha conhecimento da condição.
- **Corréus e partícipes**: São considerados corréus ou partícipes do crime os que se comunicam as circunstâncias e condições de caráter pessoal do crime.
- **Art. 30 do CP**: Não se comunicam as circunstâncias e as condições de caráter pessoal, salvo quando elementares do crime.
- **Crime contra a Publicidade**: Inclui crimes relacionados à publicidade enganosa, proteção do consumidor e responsabilidade dos fornecedores de produtos e serviços.
- **Proteção do Consumidor**: É um direito fundamental que visa proteger os consumidores de práticas comerciais desleais.
- **Responsabilidade Civil**: A responsabilidade civil é a obrigação de reparar danos causados a terceiros.

### Referências legais
- Art. 67 do Lei nº 9.605/1998
- Art. 68 do Lei nº 9.605/1998
- Art. 69 do Lei nº 9.605/1998
- Art. 70 do Lei nº 9.605/1998
- Art. 71 do Lei nº 9.605/1998
- Art. 72 do Lei nº 9.605/1998
- Art. 73 do Lei nº 9.605/1998
- Art. 74 do Lei nº 9.605/1998

### Jurisprudência
- RE 123456
- Tema repetitivo da proteção do consumidor

### Dicas de prova
- Distinção entre fornecedor e corréu ou partícipe
- Conhecimento das circunstâncias e condições de caráter pessoal do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.161 (1)", "page_number": 161, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 67 do Lei nº 9.605/1998", "Art. 68 do Lei nº 9.605/1998", "Art. 69 do Lei nº 9.605/1998", "Art. 70 do Lei nº 9.605/1998", "Art. 71 do Lei nº 9.605/1998", "Art. 72 do Lei nº 9.605/1998", "Art. 73 do Lei nº 9.605/1998", "Art. 74 do Lei nº 9.605/1998"], "jurisprudence": ["RE 123456", "Tema repetitivo da proteção do consumidor"], "confidence": 0.8, "extracted_at": "2026-05-31T20:49:38.920434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=161", "doc_key": "a30c78cb27264e2a44562407352e80e4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'fbf9cc804a6164bba079d18eb9fc9494b256112f86c48095debc371068759721'),
  ('cpiuris2025::13f1c0f03715eeae41e062d049102799', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Lei n.º 9.605/1998 - Crimes Ambientais', '## Lei n.º 9.605/1998 - Crimes Ambientais

A Lei n.º 9.605/1998 estabelece sanções penais e administrativas para crimes ambientais, com base no art. 225 da Constituição Federal.

### Conceitos
- **Meio Ambiente**: Espaço ocupado pelos seres vivos, onde habitam e há interação recíproca
- **Competência**: A competência é da Justiça Estadual, exceto se houver alguma das hipóteses do art. 109 da CF/88
- **Crimem contra a Fauna**: Em regra, a competência será da Justiça Estadual
- **Crime Ambiental Apurado a Partir de Auto de Infração**: Muitos crimes ambientais são descobertos e processados a partir de um auto de infração administrativa lavrado pelos órgãos de fiscalização ambiental
- **Rios Interestaduais**: São considerados bens da União, de acordo com o art. 20, III, da CF/88

### Referências legais
- Art. 225 da Constituição Federal
- Art. 109 da CF/88
- Lei n.º 9.605/1998

### Jurisprudência
- Súmula 91 do STJ

### Dicas de prova
- Entenda a competência para crimes ambientais
- Conheça as hipóteses de competência da Justiça Federal
- Aprenda sobre os rios interestaduais e sua classificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.164", "page_number": 164, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 225 da Constituição Federal", "Art. 109 da CF/88", "Lei n.º 9.605/1998"], "jurisprudence": ["Súmula 91 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T20:51:27.942788+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=164", "doc_key": "13f1c0f03715eeae41e062d049102799"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '36c6d5350969e398b48050ddab999850588d3cea38d9ec9d83658e8b418e8a9e'),
  ('cpiuris2025::c0bb8dda1e670b3ce6bf8488a2941e2b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Execução ilegal de pesquisa ou extração de recursos minerais', '## Execução ilegal de pesquisa ou extração de recursos minerais

Pena de detenção de 6 meses a 1 ano e multa para executar pesquisa ou extração de recursos minerais sem autorização ou em desacordo com a obtida.

### Conceitos
- **Competência Federal**: A competência para julgá-lo é da Justiça Federal, não importando o local onde foi cometido.
- **Autorização**: É necessária uma autorização, permissão, concessão ou licença para executar pesquisa ou extração de recursos minerais.
- **Pena**: A pena é detenção de 6 meses a 1 ano e multa.
- **Justiça Federal**: Tem competência para julgá-lo, mesmo que o ato tenha sido cometido em uma propriedade particular.

### Referências legais
- Art. 55 da Legislação Penal Especial

### Dicas de prova
- Pegar a competência federal como um fato determinante para a competência do juiz.
- Distinção entre autorização e permissão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 55 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:51:28.615288+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=165", "doc_key": "c0bb8dda1e670b3ce6bf8488a2941e2b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '24ab6477418166821d91ad0848fe54405e14f252228559f19ff42a184188f913'),
  ('cpiuris2025::42d02c609a908735bdb5a6d07a7a1735', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência Federal e Estadual em Crimes Ambientais', '## Competência Federal e Estadual em Crimes Ambientais

A competência para processar e julgar crimes ambientais é da Justiça Federal quando o crime tem reflexos regionais ou nacionais, e da Justiça Estadual em caso contrário.

### Conceitos
- **Competência Federal**: A competência para processar e julgar crimes ambientais que têm reflexos regionais ou nacionais.
- **Competência Estadual**: A competência para processar e julgar crimes ambientais que não têm reflexos regionais ou nacionais.
- **Rio Interestadual**: Um rio que atravessa mais de um estado.
- **Mar Territorial**: A área do mar que é considerada como parte do território nacional.
- **Zona Econômica Exclusiva**: A área do mar que é exclusivamente explorada por um país.
- **Demarcação Oficial**: O processo de definição oficial das fronteiras de um território marítimo.

### Referências legais
- Art. 109, IV, da CF
- Art. 20, VI e VII, da CF/88
- Art. 55 da Lei n.º 9.605/1998

### Jurisprudência
- STJ, 3ª Seção, CC 145.420
- STJ, 5ª T., RHC 50.692/SC

### Dicas de prova
- Pergunte sobre a competência federal e estadual em crimes ambientais.
- Entenda a distinção entre rio interestadual e mar territorial.
- Conheça as regras de demarcação oficial do território marítimo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 109, IV, da CF", "Art. 20, VI e VII, da CF/88", "Art. 55 da Lei n.º 9.605/1998"], "jurisprudence": ["STJ, 3ª Seção, CC 145.420", "STJ, 5ª T., RHC 50.692/SC"], "confidence": 0.8, "extracted_at": "2026-05-31T20:52:14.359815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=165", "doc_key": "42d02c609a908735bdb5a6d07a7a1735"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0dae3f4ed491544cc863d8e5178b9967ef1e9ab7c0cdcddce2b5ec822d144060'),
  ('cpiuris2025::c45e6c90f5c8c2a0456da583cb0d745c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Princípio da Insignificância nos Crimes Ambientais', '## Princípio da Insignificância nos Crimes Ambientais

O princípio da insignificância pode ser aplicado aos crimes ambientais, desde que a lesão seja irrelevante e não afete o equilíbrio ecológico. Exige-se reduzido valor do bem tutelado e favorabilidade das circunstâncias.

### Conceitos
- **Princípio da Insignificância**: aplicação do princípio para crimes ambientais
- **Lesão Irrelevante**: lesão que não afeta o equilíbrio ecológico
- **Valor Reduzido**: diminuição do valor do bem tutelado
- **Circunstâncias Favoráveis**: condições que favorecem a aplicação do princípio

### Referências legais
- Art. 2º da Lei N.º 7.492/1986

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Distinguir entre lesão relevante e irrelevante
- Identificar o valor reduzido do bem tutelado
- Avaliar as circunstâncias favoráveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei N.º 7.492/1986"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T20:53:17.909072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=167", "doc_key": "c45e6c90f5c8c2a0456da583cb0d745c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3633b9c0a97b474dd874451e0694a3c0160504e7d4a2bca4b0563a0f85003394'),
  ('cpiuris2025::43735b54d2bc850a12d94f50ebcada33', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime contra Áreas Ambientais Classificadas como Patrimônio Nacional', '## Crime contra Áreas Ambientais Classificadas como Patrimônio Nacional

O artigo 225 da Constituição Federal de 1988 estabelece que as áreas como Floresta Amazônica, Mata Atlântica e Serra do Mar são patrimônio nacional. O crime cometido contra essas áreas é geralmente de competência da Justiça Estadual, exceto em casos com caráter transnacional.

### Conceitos
- **Patrimônio Nacional**: Áreas protegidas pela Constituição Federal
- **Caráter Transnacional**: Condição que determina a competência da Justiça Federal em casos de crimes ambientais com vínculo internacional

### Referências legais
- Art. 20, IX, da CF/88
- Art. 225, § 4º da CF/88
- STJ, 3ª Seção, CC 116.447/MT
- STJ, 3ª Seção, CC 139.810/GO
- RE 835558-SP

### Jurisprudência
- RE 835558-SP

### Dicas de prova
- Diferenciar entre crimes de competência da Justiça Estadual e Federal
- Entender o conceito de caráter transnacional em crimes ambientais
- Conhecer as áreas protegidas como patrimônio nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.166", "page_number": 166, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20, IX, da CF/88", "Art. 225, § 4º da CF/88", "STJ, 3ª Seção, CC 116.447/MT", "STJ, 3ª Seção, CC 139.810/GO", "RE 835558-SP"], "jurisprudence": ["RE 835558-SP"], "confidence": 0.8, "extracted_at": "2026-05-31T20:53:22.406057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=166", "doc_key": "43735b54d2bc850a12d94f50ebcada33"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '21a9cb4e122adf2d6e1eda360101c8514f5b784ff20ae6a4143ee59533e0492b'),
  ('cpiuris2025::55b56d9feec2e572b73966fc533e6345', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Responsabilidade Penal de Pessoas Jurídicas', '## Responsabilidade Penal de Pessoas Jurídicas

A responsabilidade penal de pessoas jurídicas não exclui a das pessoas físicas, e é prevista no art. 225, § 3º da CF.

### Conceitos
- **Responsabilidade Penal**: O dever de responder perante o Estado por uma infração cometida
- **Pessoas Jurídicas**: Entidades que têm personalidade jurídica própria, como empresas ou organizações
- **Coautoria**: A participação em um fato com outra pessoa, tornando-se responsável pela infração
- **Participação**: A contribuição de uma pessoa para a realização de uma infração

### Referências legais
- Art. 225, § 3º da CF

### Dicas de prova
- Distinção entre coautoria e participação
- Importância do art. 225, § 3º da CF na responsabilidade penal de pessoas jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 225, § 3º da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:55:17.778609+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=167", "doc_key": "55b56d9feec2e572b73966fc533e6345"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6061eafda77c3d5c2fc89843bf520c66c56897b8cd344ee9b20252119e7c558f'),
  ('cpiuris2025::4fbbcc6231f4372483ef362b7786487d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Responsabilidade Penal das Pessoas Jurídicas', '## Responsabilidade Penal das Pessoas Jurídicas

A responsabilidade penal das pessoas jurídicas não exige necessariamente a denúncia de pessoas físicas, conforme o § 3º do art. 225 da CF/88.

### Conceitos
- **Responsabilidade Penal das Pessoas Jurídicas**: A responsabilidade penal das pessoas jurídicas é um conceito que se refere à capacidade de uma pessoa jurídica ser punida por um delito.
- **Denúncia**: A denúncia é o ato pelo qual o Ministério Público apresenta a acusação contra uma pessoa jurídica ou física.
- **Pessoa Jurídica**: Uma entidade que tem personalidade jurídica e pode ser responsabilizada por atos ilícitos.
- **Autoria**: A autoria é o estado de quem é considerado o autor de um delito.

### Referências legais
- Art. 225, § 3º da CF/88

### Dicas de prova
- Entenda a distinção entre denúncia e autoria.
- Conheça as teorias sobre responsabilidade penal das pessoas jurídicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 225, § 3º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:55:51.517191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=168", "doc_key": "4fbbcc6231f4372483ef362b7786487d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '65fbdf5d5ce815d24a793ba5a0dac97636c5ab22ec0c5bc958c2bcccca64bc25'),
  ('cpiuris2025::db75aad996bb49b4e639991f37976fc7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Responsabilidade Penal das Pessoas Jurídicas', '## Responsabilidade Penal das Pessoas Jurídicas

A lei estabelece que as pessoas jurídicas podem ser responsabilizadas penalmente por crimes ambientais, independentemente da obrigação de reparar os danos causados. A teoria da ficção jurídica defende que as pessoas jurídicas não podem ser responsabilizadas criminalmente porque não praticam conduta ou agem com culpabilidade.

### Conceitos
- **Pessoa Jurídica**: Abstração jurídica desprovida de consciência e vontade
- **Teoria da Ficção Jurídica**: Defende que as pessoas jurídicas não podem ser responsabilizadas criminalmente porque não praticam conduta ou agem com culpabilidade
- **Responsabilidade Penal das Pessoas Jurídicas**: A lei estabelece que as pessoas jurídicas podem ser responsabilizadas penalmente por crimes ambientais

### Referências legais
- Art. 225 da CF/88
- § 3º do Art. 225 da CF/88
- STJ REsp 1.977.172/PR
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a teoria da ficção jurídica e sua aplicação na responsabilidade penal das pessoas jurídicas
- Conheça o artigo 225 da CF/88 e seu § 3º
- Análise do caso REsp 1.977.172/PR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 225 da CF/88", "§ 3º do Art. 225 da CF/88", "STJ REsp 1.977.172/PR", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T20:56:27.148590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=168", "doc_key": "db75aad996bb49b4e639991f37976fc7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1638f73b10d83a5c2ac1f42fa83703e46eee95f33a54d4707b705a1d713509fa'),
  ('cpiuris2025::91aa368cad75c8e3cfcbcf0469cd5104', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Penas para crimes ambientais', '## Penas para crimes ambientais

A lei estabelece penas para crimes ambientais, incluindo suspensão de atividades, interdição temporária de estabelecimentos e proibição de contratar com o Poder Público. Além disso, a lei prevê a pena de prestação de serviços à comunidade e a liquidação forçada de pessoas jurídicas que cometem crimes ambientais.

### Conceitos
- **Pena de suspensão de atividades**: Penalidade aplicada quando as atividades não estão obedecendo às disposições legais ou regulamentares
- **Interdição temporária**: Penalidade aplicada quando o estabelecimento está funcionando sem autorização ou em desacordo com a concedida
- **Prestação de serviços à comunidade**: Pena que consiste na prestação de serviços ambientais e culturais
- **Liquidação forçada**: Penalidade aplicada quando a pessoa jurídica é constituída ou utilizada com o fim de permitir, facilitar ou ocultar o crime

### Referências legais
- Art. 23 da Lei Nº 7.492/1986

### Dicas de prova
- Entenda a diferença entre suspensão de atividades e interdição temporária
- Conheça as penas para crimes ambientais previstas na lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.170", "page_number": 170, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 23 da Lei Nº 7.492/1986"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:58:26.905214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=170", "doc_key": "91aa368cad75c8e3cfcbcf0469cd5104"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1daee68fe6f968c113565167c56ab4f66d209f4065487be3ff699ffab511ccdb'),
  ('cpiuris2025::b8a86c71cd229515a7dccfd5ab2dc909', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Penas e Multa', '## Penas e Multa

Descreve as fases da imposição de penas, incluindo a gravidade do fato, antecedentes do infrator e situação econômica, além das circunstâncias que atenuam ou agravam a pena.

### Conceitos
- **Pena-base**: pena inicial imposta pela autoridade competente
- **Pena-provisória**: pena aplicada em caso de circunstâncias que atenuam ou agravam a pena
- **Circunstância que atenua a pena**: fato que reduz a gravidade da pena
- **Circunstância que agraça a pena**: fato que aumenta a gravidade da pena

### Referências legais
- Art. 6º
- Art. 14
- Art. 15
- Art. 18
- Art. 7º

### Dicas de prova
- Entenda as fases da imposição de penas e como são consideradas circunstâncias que atenuam ou agravam a pena.
- Conheça os critérios para calcular a multa e como ela é aumentada em caso de ineficácia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.171", "page_number": 171, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 6º", "Art. 14", "Art. 15", "Art. 18", "Art. 7º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T20:58:46.953491+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=171", "doc_key": "b8a86c71cd229515a7dccfd5ab2dc909"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'bf6adab11f371fc45f2e605b55213606e533e3a7425cffcda833ec3dbd8beedf'),
  ('cpiuris2025::9d0e423fea3a8ad9e6d5d8162b8e45c8', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Responsabilidade Penal da Pessoa Jurídica', '## Responsabilidade Penal da Pessoa Jurídica

A responsabilidade penal da pessoa jurídica depende do caso concreto e pode ser caracterizada por crimes praticados pelo representante legal ou contratual, bem como por decisões tomadas em benefício da pessoa jurídica.

### Conceitos
- **Dupla Imputação**: Teoria que propõe a responsabilidade penal da pessoa jurídica somente se houver persecução penal concomitante da pessoa física responsável.
- **Responsabilidade Penal da Pessoa Jurídica**: O direito de imputar o crime às pessoas naturais e à pessoa jurídica, juntas ou separadamente.
- **Teoria da Dupla Imputação**: Só poderia haver responsabilização penal da pessoa jurídica por crimes ambientais se também fosse processada criminalmente a pessoa física responsável pela conduta prevista como delito ambiental.
- **Penas para Pessoas Jurídicas**: As penas aplicáveis às pessoas jurídicas, de acordo com o disposto no art. 3º, são multa, restritivas de direitos e prestação de serviços à comunidade.
- **Restritivas de Direitos**: Penas que restringem os direitos da pessoa jurídica, como suspensão parcial ou total de atividades, interdição temporária de estabelecimento, obra ou atividade e proibição de contratar com o Poder Público.
- **Interdição Temporária**: Pena que impede a pessoa jurídica de funcionar sem a devida autorização ou em desacordo com a concedida.
- **Proibição de Contratar**: Pena que proíbe a pessoa jurídica de contratar com o Poder Público e obter subsídios, subvenções ou doações.
- **Prazo de Dez Anos**: O prazo máximo para a proibição de contratar com o Poder Público e obter subsídios, subvenções ou doações.

### Referências legais
- Art. 21 da Lei Nº 7.492/1986
- Art. 22 da Lei Nº 7.492/1986

### Jurisprudência
- RE 548181
- 7ª tese da Jurisprudência em Teses do STJ, edição 216

### Dicas de prova
- Pegar a teoria da dupla imputação e entender quando ela pode ser aplicada.
- Entender que as penas para pessoas jurídicas são diferentes das penas para pessoas físicas.
- Identificar as restritivas de direitos e suas consequências para a pessoa jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.169", "page_number": 169, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 21 da Lei Nº 7.492/1986", "Art. 22 da Lei Nº 7.492/1986"], "jurisprudence": ["RE 548181", "7ª tese da Jurisprudência em Teses do STJ, edição 216"], "confidence": 0.8, "extracted_at": "2026-05-31T20:59:58.965657+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=169", "doc_key": "9d0e423fea3a8ad9e6d5d8162b8e45c8"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7aa7777ece568f2bc1664aed85548b2ee670fb9f3a7c466a57718b9989488851'),
  ('cpiuris2025::f8ddb5b8e36f8c0d4f79a0c61fba8f3f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Limitações para contratar com o Poder Público após condenação', '## Limitações para contratar com o Poder Público após condenação

O artigo 10 estabelece limitações para contratar com o Poder Público, de receber incentivos fiscais ou quaisquer outros benefícios, bem como de participar de licitações, após condenação por crimes dolosos e culposos.

### Conceitos
- **Contrato com o Poder Público**: Acordo entre a administração pública e uma pessoa jurídica ou física
- **Incentivos fiscais**: Benefícios tributários concedidos pela administração pública
- **Licitações**: Processo de contratação de bens e serviços da administração pública

### Referências legais
- Art. 10 da Legislação Penal Especial

### Dicas de prova
- Entenda a distinção entre crimes dolosos e culposos
- Conheça as limitações para contratar com o Poder Público após condenação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 10 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:00:42.695052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=172", "doc_key": "f8ddb5b8e36f8c0d4f79a0c61fba8f3f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'a22e177ade7e8fedfe181bd15b351a0a3e601fee05f40d097c4a841a66edb3ba'),
  ('cpiuris2025::1bde215717d486fe41949cb8f1663ea5', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Substituição da pena privativa de liberdade por penas restritivas de direitos', '## Substituição da pena privativa de liberdade por penas restritivas de direitos

A substituição da pena privativa de liberdade por penas restritivas de direitos é permitida para crimes culposos ou com pena inferior a 4 anos, desde que a culpabilidade e as circunstâncias do crime não o impedam.

### Conceitos
- **Substituição da pena privativa de liberdade**: substituição da pena privativa de liberdade por penas restritivas de direitos
- **Penas restritivas de direitos**: penas que não envolvem a privação da liberdade, mas sim restrições à atividade ou ao uso de certos direitos
- **Culpabilidade**: qualidade do autor do crime, medida pela gravidade e natureza do ato criminoso
- **Antecedentes**: histórico prévio de condenações ou comportamentos criminosos
- **Conduta social**: comportamento e atitudes do autor do crime em relação à sociedade
- **Personalidade do condenado**: características pessoais do autor do crime, como sua idade, saúde, etc.

### Referências legais
- Art. 7º da Lei N.º 7.492/1986
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Substituição de penas em crimes culposos

### Dicas de prova
- Entenda a diferença entre substituição e não-substituição da pena privativa de liberdade
- Conheça as condições para a aplicação das penas restritivas de direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 7º da Lei N.º 7.492/1986", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Substituição de penas em crimes culposos"], "confidence": 0.8, "extracted_at": "2026-05-31T21:01:40.606537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=172", "doc_key": "1bde215717d486fe41949cb8f1663ea5"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '1d57f40a8f722c71629740fb7120c3fcec7914c2b0a10fe6a534cc913b2144df'),
  ('cpiuris2025::f84831e2ed45ae36f67243cdda3036f0', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Suspensão Condicional da Pena', '## Suspensão Condicional da Pena

A suspensão condicional da pena é concedida quando o condenado não é reincidente em crime doloso, a culpabilidade e os antecedentes do agente autorizam a concessão do benefício, e não há substituição prevista no art. 44.

### Conceitos
- **Suspensão Condicional da Pena**: Concessão de pena suspensa por determinadas condições
- **Reincidente em crime doloso**: O condenado já cometeu outro crime doloso
- **Culpabilidade**: A responsabilidade do agente pelo crime cometido
- **Antecedentes**: Histórico de crimes anteriores do agente
- **Conduta social e personalidade do agente**: Características da conduta e da personalidade do condenado

### Referências legais
- Art. 77 da Lei n.º 7.492/1986
- Art. 16 da Lei n.º 9.605/1998
- Art. 27 da Lei n.º 9.605/1998

### Dicas de prova
- Distinção entre suspensão condicional e transação penal
- Importância de considerar a culpabilidade, os antecedentes e a conduta social do agente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 77 da Lei n.º 7.492/1986", "Art. 16 da Lei n.º 9.605/1998", "Art. 27 da Lei n.º 9.605/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:02:30.158345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=173", "doc_key": "f84831e2ed45ae36f67243cdda3036f0"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'af3eaac252deb245a4f61b4172b572026e57a2c25bd64fadba22af8de599d8cf'),
  ('cpiuris2025::bf941823bf424969b19270148c5bbe9f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Suspensao do processo', '## Suspensao do processo

O Ministério Público pode propor a suspensão do processo por dois a quatro anos, desde que o acusado não esteja sendo processado ou não tenha sido condenado por outro crime.

### Conceitos
- **Suspensao do processo**: Prorrogação temporária da execução da pena
- **Ministério Público**: Autoridade que procura a justiça e representa o Estado na ação penal
- **Denúncia**: Ação processual iniciada pelo Ministério Público para acusar um indivíduo de crime

### Referências legais
- Art. 119 da Lei nº 9.735/1998

### Dicas de prova
- Perguntas sobre a suspensão do processo podem ser muito específicas, então é importante entender os requisitos e limites dessa medida.
- Lembre-se de que a suspensão do processo não é uma absolvição, mas sim uma prorrogação temporária da execução da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 119 da Lei nº 9.735/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:02:46.771665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=173", "doc_key": "bf941823bf424969b19270148c5bbe9f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'aae0bfa7a6e215e64f0b69f30a9e75f5e2db971e72c48b0b34598e512103d33b'),
  ('cpiuris2025::d03be5948cbc7c8111da7da2e6402d48', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Reparação dos danos causados pela infração', '## Reparação dos danos causados pela infração

O valor mínimo para reparação dos danos é fixado considerando os prejuízos sofridos pelo ofendido ou pelo meio ambiente.

### Conceitos
- **Dano moral**: prejuízo sofrido pelo ofendido, não necessariamente material
- **Execução específica**: execuções ou medidas específicas, não necessariamente condenar a pagar valores em dinheiro
- **Reparação integral do meio ambiente**: condenação simultânea e cumulativa das obrigações de fazer, de não fazer e de indenizar

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Distinção entre dano moral e material
- Execução específica vs condenação em dinheiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T21:04:14.038495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=174", "doc_key": "d03be5948cbc7c8111da7da2e6402d48"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '691004c0e742376d56a263af336eab4e9073078d1b91c579d61741b8547c0201'),
  ('cpiuris2025::9858fbce02acf915b31175143988deeb', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Perícia e Sentença em Processos Penais Ambientais', '## Perícia e Sentença em Processos Penais Ambientais

O art. 19 estabelece que a perícia de constatação do dano ambiental fixará o montante do prejuízo causado, servindo como base para prestação de fiança e cálculo de multa. A sentença penal condenatória também deve considerar essa perícia.

### Conceitos
- **Perícia**: Prova emprestada que migra de um processo a outro, com as mesmas partes.
- **Sentença Penal Condenatória**: Decisão final do juiz que condena o réu
- **Prestação de Fiança**: Medida cautelar adotada pelo juiz para garantir a presença do réu no processo
- **Cálculo de Multa**: Procedimento utilizado para determinar a magnitude da multa imposta ao réu

### Referências legais
- Art. 19 da Lei N.º 11.343/2006
- Art. 158 do CPP

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a diferença entre prova emprestada e prova própria.
- Conheça o procedimento para cálculo de multa nos crimes ambientais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 19 da Lei N.º 11.343/2006", "Art. 158 do CPP"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T21:04:22.330709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=174", "doc_key": "9858fbce02acf915b31175143988deeb"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '40fb9068263f05b6070bd9123e9ad9de04c80dbdf36dea424319a8e5ac58107a'),
  ('cpiuris2025::1fa2f63ee4b3375f120d519ae0876758', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Substituição da pena privativa de liberdade por penas restritivas de direitos', '## Substituição da pena privativa de liberdade por penas restritivas de direitos

A substituição da pena privativa de liberdade por penas restritivas de direitos é uma alternativa aos efeitos traumáticos, estigmatizantes e onerosos do cárcere. O juiz natural da causa deve escolher o tipo alternativo de reprimenda suficiente para castigar e recuperar socialmente o apenado.

### Conceitos
- **Pena privativa de liberdade**: Restrição à liberdade corporal
- **Penas restritivas de direitos**: Alternativas ao cárcere, com o objetivo de retribuir e prevenir comportamentos
- **Substituição da pena**: Troca da pena privativa de liberdade por uma pena restritiva de direitos

### Referências legais
- Art. 8º da Lei n. 9.605/1998
- Súmula 171/STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre pena privativa de liberdade e penas restritivas de direitos.
- Conheça os parâmetros legais para a substituição da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 8º da Lei n. 9.605/1998", "Súmula 171/STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T21:05:18.118731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=175", "doc_key": "1fa2f63ee4b3375f120d519ae0876758"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b204537edd491bb3d910e785474175f386a6ee91277b48faf65e51336371f36d'),
  ('cpiuris2025::6d8f777c85c4c03bccb1e2aaed191da4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Recolhimento de animais após infração', '## Recolhimento de animais após infração

O artigo 25 estabelece regras para o recolhimento de animais após uma infração, incluindo a prioridade dada à libertação em seu habitat e a entrega a jardins zoológicos ou entidades semelhantes.

### Conceitos
- **Apreendidos**: Animais ou produtos relacionados à infração
- **Instrumentos**: Objetos utilizados na prática da infração
- **Bem-estar físico**: Condições adequadas para o cuidado e acomodação dos animais
- **Reciclagem**: Procedimento para descaracterizar os instrumentos após venda

### Referências legais
- Art. 25 da Legislação Penal Especial

### Dicas de prova
- Entenda a importância do bem-estar físico dos animais
- Conheça as regras para o recolhimento de animais após infração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.175 (2)", "page_number": 175, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 25 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:06:16.928754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=175", "doc_key": "6d8f777c85c4c03bccb1e2aaed191da4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'fe8c4809e5902b889be837f8683581fb4e0a6f952dd0690139ee4037612434e7'),
  ('cpiuris2025::da63d1343eee3aeb31ac6b1976747c44', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Espécimes da fauna silvestre', '## Espécimes da fauna silvestre

Define que são espécimes da fauna silvestre aqueles que têm seu ciclo de vida dentro do território brasileiro ou águas jurisdicionais, e estabelece critérios para aumento de pena em caso de infração.

### Conceitos
- **Fauna Silvestre**: espécies nativas, migratórias e outras que ocorrem dentro do território brasileiro ou águas jurisdicionais
- **Ciclo de Vida**: fase de vida de uma espécie
- **Pena Aumentada**: aumento da pena em caso de infração

### Referências legais
- Art. 3º da Lei nº X, de Y
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção à Fauna Silvestre

### Dicas de prova
- Entenda o conceito de fauna silvestre e seu ciclo de vida
- Identifique os critérios para aumento de pena em caso de infração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º da Lei nº X, de Y", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção à Fauna Silvestre"], "confidence": 0.8, "extracted_at": "2026-05-31T21:06:50.936135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=176", "doc_key": "da63d1343eee3aeb31ac6b1976747c44"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '32454970e6343bdc4b7a0d45ef3031a8ab35fe2f8032cc8b9b9acddd006d60fc'),
  ('cpiuris2025::33ce0787cb4465bd70ffd29cb8419c20', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra a Fauna', '## Crimes contra a Fauna

Artigos relacionados a crimes contra a fauna, incluindo penalidades e exceções.

### Conceitos
- **Fauna**: conjunto de animais, terrestres ou aquáticos, próprios de uma determinada região
- **Tentativa**: cabível na maior parte dos crimes ambientes, ressalvando casos específicos
- **Matar**: infração de menor potencial ofensivo, com pena de detenção de 6 meses a 1 ano
- **Persecução**: infração de menor potencial ofensivo, com pena de detenção de 6 meses a 1 ano
- **Caçar**: infração de menor potencial ofensivo, com pena de detenção de 6 meses a 1 ano
- **Apanhar**: infração de menor potencial ofensivo, com pena de detenção de 6 meses a 1 ano
- **Utilizar espécimes da fauna silvestre**: infração de menor potencial ofensivo, com pena de detenção de 6 meses a 1 ano
- **Modificação ou danificação de ninho ou abrigo natural**: crime permanente, com pena mais severa

### Referências legais
- Art. 29 da Lei nº 9.474/1998
- Súmula 91 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre crimes contra a fauna

### Dicas de prova
- Entenda a distinção entre tentativa e crime permanente
- Conheça as penalidades para matar, perseguir, caçar e apanhar animais silvestres', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 29 da Lei nº 9.474/1998", "Súmula 91 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre crimes contra a fauna"], "confidence": 0.8, "extracted_at": "2026-05-31T21:06:54.393531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=176", "doc_key": "33ce0787cb4465bd70ffd29cb8419c20"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c0a0e1518ed1962510ab167644075652e45f035210855ea330cf9a3a74d5d7e8'),
  ('cpiuris2025::cef0b84b46c1fba39825c8f28c59c5e6', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime contra a Natureza e Animais', '## Crime contra a Natureza e Animais

Leis que regulamentam crimes contra a natureza e animais, incluindo exportação ilegal de peles e couros, introdução de espécimes animais sem autorização, abuso de animais silvestres e pescaria em períodos proibidos.

### Conceitos
- **Crime contra a Natureza**: Atos que causam dano ao meio ambiente ou à vida animal
- **Abuso de Animais**: Ato de maltratar, ferir ou mutilar animais silvestres, domésticos ou domesticados
- **Pescaria ilegal**: Pesca em períodos proibidos ou em lugares interditados por órgão competente

### Referências legais
- Art. 30
- Art. 31
- Art. 32
- Art. 34

### Dicas de prova
- Diferenciar entre crimes contra a natureza e animais
- Entender o conceito de abuso de animais e sua punibilidade
- Conhecer as penas para crimes de pescaria ilegal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 30", "Art. 31", "Art. 32", "Art. 34"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:09:04.623181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=177", "doc_key": "cef0b84b46c1fba39825c8f28c59c5e6"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '26a9d7c97ab0e19753e1492e09cf8a4705d0414a52d487aefd3a7e7b85ab6c06'),
  ('cpiuris2025::3f4d7069ed064061d39b44b10bf28e17', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime contra a Flora', '## Crime contra a Flora

O crime de destruição ou dano à floresta de preservação permanente é punido com detenção de 1 a 3 anos ou multa, ou ambas as penas cumulativamente.

### Conceitos
- **Área de Preservação Permanente (APP)**: área protegida, coberta ou não por vegetação nativa
- **Destruição**: remoção ou destruição intencional de uma área de floresta
- **Dano**: danos causados à floresta, independentemente da intenção do agente
- **Floresta de preservação permanente**: área protegida para preservar recursos hídricos e biodiversidade
- **Mata Atlântica**: bioma que inclui vegetação primária ou secundária

### Referências legais
- Art. 38 da Lei nº 7.492/1986
- Art. 3º, II, da Lei nº 12.651/2012

### Dicas de prova
- Entenda a diferença entre destruição e dano à floresta
- Conheça as áreas protegidas como APP e Mata Atlântica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 38 da Lei nº 7.492/1986", "Art. 3º, II, da Lei nº 12.651/2012"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:09:22.701918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=178", "doc_key": "3f4d7069ed064061d39b44b10bf28e17"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '07cf433b68296c976bf715c0b3c854dbd0073b2f30e0313373ea31b2d0778c1d'),
  ('cpiuris2025::954618002ea1edce86f02669a7ee799e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra a Natureza e o Meio Ambiente', '## Crimes contra a Natureza e o Meio Ambiente

O crime consiste na pesca ilegal, comou transporte, comercialização ou beneficiamento de espécies coletadas ilegalmente.

### Conceitos
- **pesca ilegal**: pesca sem autorização ou sem cumprir as quantidades permitidas
- **transporte ilegal**: movimentação de espécies coletadas ilegalmente
- **comercialização ilegal**: venda ou distribuição de espécies coletadas ilegalmente
- **beneficiamento ilegal**: transformação ou processamento de espécies coletadas ilegalmente
- **espécies protegidas**: espécies que necessitam de proteção e conservação
- **período proibido**: périodos específicos do ano em que certas espécies não podem ser coletadas
- **quantidade permitida**: quantidades máximas permitidas de certas espécies para coleta

### Referências legais
- Art. II da Lei X da Natureza

### Dicas de prova
- Diferencie entre a pesca ilegal e a pesca sem autorização
- Entenda o conceito de beneficiamento ilegal e como ele se relaciona com a comercialização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. II da Lei X da Natureza"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:09:40.078929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=177", "doc_key": "954618002ea1edce86f02669a7ee799e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f4266b0bc2854d9dfbed72bb9ac154a338a7b8b67facbd4e180b118835c82151'),
  ('cpiuris2025::188fc09433c96b34c914af45f02683c0', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Corte de árvore em floresta de preservação permanente', '## Corte de árvore em floresta de preservação permanente

Pena para corte de árvores em florestas consideradas de preservação permanente sem permissão, detenção ou multa.

### Conceitos
- **Floresta Ombrófila**: Tipo de floresta nativa brasileira
- **Preservação Permanente**: Condição para proteger a integridade da floresta
- **Corte de Árvore**: Ação que envolve a remoção de árvores

### Referências legais
- Art. 39 da Lei n.º 11.428/2006

### Dicas de prova
- Entenda o conceito de Floresta Ombrófila e Preservação Permanente
- Identifique a pena correta para corte de árvores em florestas protegidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 39 da Lei n.º 11.428/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:11:03.152027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=178", "doc_key": "188fc09433c96b34c914af45f02683c0"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '68c6178d8044bc74b5dc485364e999002933e929eb682dac86a9aead5d11256c'),
  ('cpiuris2025::ec258a75ecaaad17a23a94ecd51c37c1', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Dano às Unidades de Conservação e proteção ambiental', '## Dano às Unidades de Conservação e proteção ambiental

Artigos 40 e 40-A definem crimes relacionados a dano às unidades de conservação e áreas de uso sustentável, com penas que variam de reclusão a multa.

### Conceitos
- **Unidade de Conservação**: Área protegida para preservar a natureza
- **Dano direto ou indireto**: Prejuízo causado à unidade de conservação
- **Circunstância agravante**: Fato que aumenta a gravidade da pena
- **Pena culposa**: Redução da pena para metade em caso de dolo culposo

### Referências legais
- Art. 40 da Lei nº 7.492/1986
- Art. 39 da Lei nº 7.492/1986

### Dicas de prova
- Entenda a distinção entre Unidades de Conservação e áreas de uso sustentável
- Identifique as circunstâncias agravantes para a fixação da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.179", "page_number": 179, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 40 da Lei nº 7.492/1986", "Art. 39 da Lei nº 7.492/1986"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:11:43.615807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=179", "doc_key": "ec258a75ecaaad17a23a94ecd51c37c1"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd92553ef462d2b466456d94134efe903783171b541112f2d63a25e138953ba00'),
  ('cpiuris2025::ff98e22ffed1964f2a0f457246011d0b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Proteção Ambiental', '## Proteção Ambiental

Artigos 44, 48 e 50 da Lei n.º 7.492/1986 estabelecem penalidades para crimes relacionados à extração de minerais, impedimento ou dificultação da regeneração de florestas e destruição ou dano a florestas ou vegetação de especial preservação.

### Conceitos
- **Floresta Nativa**: Floresta que cresce naturalmente
- **Floresta Plantada**: Floresta que se origina de reflorestamento
- **Manguezal**: Ecossistema litorâneo formado por vasas lodosas recentes ou arenosas

### Referências legais
- Art. 44 da Lei n.º 7.492/1986
- Art. 48 da Lei n.º 7.492/1986
- Art. 50 da Lei n.º 7.492/1986

### Jurisprudência
- STJ: [...]

### Dicas de prova
- Entenda a definição de Floresta Nativa e Floresta Plantada.
- Conheça o conceito de Manguezal e sua importância ambiental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.180", "page_number": 180, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 44 da Lei n.º 7.492/1986", "Art. 48 da Lei n.º 7.492/1986", "Art. 50 da Lei n.º 7.492/1986"], "jurisprudence": ["STJ: [...]"], "confidence": 0.8, "extracted_at": "2026-05-31T21:11:56.269267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=180", "doc_key": "ff98e22ffed1964f2a0f457246011d0b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b8631cd3494ef5ad5bd8ba6cd9b5b52a0575495e443cb3f09f91a2372d01021e'),
  ('cpiuris2025::957f222a1cf1d71000be965ee5a105ae', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Ingresso irregular em Unidade de Conservação e Poluição', '## Ingresso irregular em Unidade de Conservação e Poluição

Artigos relacionados a ingresso irregular em Unidades de Conservação e poluição, com penas variando de detenção a reclusão.

### Conceitos
- **Unidade de Conservação**: Área protegida para preservação do meio ambiente
- **Poluição**: Contaminação do meio ambiente causada por atividades humanas
- **Agravantes**: Circunstâncias que aumentam a pena
- **Majorantes**: Aumento da pena devido a circunstâncias específicas

### Referências legais
- Art. 52, Lei n.º 7.492/1986
- Art. 53, Lei n.º 7.492/1986
- Art. 54, Lei n.º 7.492/1986

### Dicas de prova
- Entenda a definição de Unidade de Conservação e como ela é protegida pela lei.
- Conheça as diferentes formas de poluição e suas consequências no meio ambiente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.181 (1)", "page_number": 181, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 52, Lei n.º 7.492/1986", "Art. 53, Lei n.º 7.492/1986", "Art. 54, Lei n.º 7.492/1986"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:13:12.227930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=181", "doc_key": "957f222a1cf1d71000be965ee5a105ae"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd423a150c58749835792fb306459b38a4db23acdd4399e715d1eb881b168bb28'),
  ('cpiuris2025::cba2445657c230709e6a96784d3b9f0e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Medidas de Precaução em Caso de Risco de Dano Ambiental Grave ou Irreversível', '## Medidas de Precaução em Caso de Risco de Dano Ambiental Grave ou Irreversível

Pena de reclusão de um a cinco anos para quem não adota medidas de precaução quando exigidas pela autoridade competente. A jurisprudência do STJ entende que o delito de poluição é formal e não exige perícia.

### Conceitos
- **Medidas de Precaução**: Ações tomadas para evitar danos ambientais graves ou irreversíveis
- **Autoridade Competente**: Entidade responsável por exigir medidas de precaução em casos de risco de dano ambiental

### Referências legais
- Art. 54 da Lei n. 9.605/1998

### Jurisprudência
- Súmula 456 do STJ

### Dicas de prova
- Distinção entre medidas de precaução e perícia em casos de poluição
- Entendimento do STJ sobre a formalidade do delito de poluição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.181 (2)", "page_number": 181, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 54 da Lei n. 9.605/1998"], "jurisprudence": ["Súmula 456 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T21:13:31.574458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=181", "doc_key": "cba2445657c230709e6a96784d3b9f0e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '434d7727916e90a610de6350d8eda0e722c81e3bb77bfc1320ed30562c4e520e'),
  ('cpiuris2025::b973d023dac2fb3d38fa666a8fd7d68d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Dano à Natureza ou Meio Ambiente', '## Dano à Natureza ou Meio Ambiente

Penalidades para dano irreversível à flora ou ao meio ambiente, lesão corporal grave e morte de outrem.

### Conceitos
- **Dano à Natureza**: Lesão irreversível à flora ou ao meio ambiente
- **Lesão Corporal Grave**: Lesão que resulta em prejuízo significativo à saúde ou à vida de outrem
- **Morte de Outrem**: Falecimento de outrem como resultado do crime

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre dano irreversível e lesão corporal grave
- Entender a importância das majorantes ou causas de aumento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:14:46.511305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=182", "doc_key": "b973d023dac2fb3d38fa666a8fd7d68d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e18c76644732816a36111085edcb92ee870510f8845d5f679e84920158c8295d'),
  ('cpiuris2025::11deb783401222a5c6cc7edf46297da1', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Lavra Sem Autorização e Código de Minas', '## Lavra Sem Autorização e Código de Minas

Regra para a realização de pesquisa, lavra ou extração de recursos minerais sem autorização, permissão, concessão ou licença.

### Conceitos
- **Pesquisa Mineral**: Execução dos trabalhos necessários à definição da jazida, sua avaliação e a determinação da exequibilidade do seu aproveitamento econômico.
- **Lavra**: Conjunto de operações coordenadas objetivando o aproveitamento industrial da jazida, desde a extração das substâncias minerais úteis que contiver.
- **Autorização**: Permissão, concessão ou licença necessária para realizar pesquisa, lavra ou extração de recursos minerais.
- **Concessão**: Outorga do Estado para explorar recursos naturais, incluindo minerais.
- **Licença**: Permissão concedida pelo órgão competente para realizar atividades relacionadas a recursos naturais.
- **Crimes Ambientais**: Ações penais previstas na Lei de Crimes Ambientais, que visam proteger o meio ambiente e a saúde humana.
- **Poluição**: Atividade ou situação que causa danos à saúde humana ou ao meio ambiente.

### Referências legais
- Art. 55 da Lei n. 7.492/1986
- Art. 14 do Decreto-Lei n.º 227/1967

### Jurisprudência
- STJ: Teses do STJ, edição 218, 5ª tese; STJ: RHC 111023

### Dicas de prova
- Entenda a diferença entre pesquisa mineral e lavra.
- Conheça as autorizações necessárias para realizar atividades relacionadas a recursos naturais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 55 da Lei n. 7.492/1986", "Art. 14 do Decreto-Lei n.º 227/1967"], "jurisprudence": ["STJ: Teses do STJ, edição 218, 5ª tese; STJ: RHC 111023"], "confidence": 0.8, "extracted_at": "2026-05-31T21:15:13.351072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=182", "doc_key": "11deb783401222a5c6cc7edf46297da1"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b897474a287150127543bb2bff7228c2774e98f7c130004900b1472a5f158498'),
  ('cpiuris2025::2195e1f28716a985a9cd789d6cf13e2e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Principàlis Crimes Contra o Ordemamento Urbano e o Patrimônio Cultural', '## Principàlis Crimes Contra o Ordemamento Urbano e o Patrimônio Cultural

Lei que estabelece crimes contra o ordenamento urbano e o patrimônio cultural, incluindo dano a bem protegido, pichação e grafite, afirmação falsa ou enganosa em procedimentos ambientais, entre outros.

### Conceitos
- **Dano a Bem Protegido**: Destruir, inutilizar ou deteriorar bem especialmente protegido por lei, ato administrativo ou decisão judicial
- **Pichação e Grafite**: Pichar ou conspurcar edificação ou monumento urbano
- **Afirmação Falsa ou Enganosa**: Fazer o funcionário público afirmação falsa ou enganosa, omitir a verdade, sonegar informações ou dados técnico-científicos em procedimentos de autorização ou de licenciamento ambiental
- **Concessão Irregular de Licença**: Conceder o funcionário público licença, autorização ou permissão em desacordo com as normas ambientais

### Referências legais
- Art. 62 da Lei Nº 7.492/1986

### Dicas de prova
- Distinção entre dano a bem protegido e pichação/grafite
- Entendimento de afirmação falsa ou enganosa em procedimentos ambientais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.183", "page_number": 183, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 62 da Lei Nº 7.492/1986"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:16:08.385309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=183", "doc_key": "2195e1f28716a985a9cd789d6cf13e2e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'fcfafd7e292a9c923935d9df6887d12c02f8402a6e26355bfee25cd9a9469fda'),
  ('cpiuris2025::9bb8c16ed0ef85953ed8b27aa2efee11', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Impedimento do agravamento da pena', '## Impedimento do agravamento da pena

A comercialização das ATPFs impede o agravamento da pena na segunda fase da dosimetria, de acordo com o art. 15 da lei.

### Conceitos
- **ATPF**: Atividade Tecnológica de Produção de Fertilizantes
- **Dosimetria**: Processo de fixação da pena
- **Agravamento da pena**: Aumento da pena

### Referências legais
- Art. 15 da Lei n. 9.605/1998

### Jurisprudência
- HC 281832

### Dicas de prova
- Entenda a relação entre a comercialização das ATPFs e o impedimento do agravamento da pena.
- Conheça as regras de dosimetria e agravamento da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 15 da Lei n. 9.605/1998"], "jurisprudence": ["HC 281832"], "confidence": 0.8, "extracted_at": "2026-05-31T21:16:47.055466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=184", "doc_key": "9bb8c16ed0ef85953ed8b27aa2efee11"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd63a245332b23d7f3d302e83919ae2411b39d9462dbaea15d091d3a1c2e9f56a'),
  ('cpiuris2025::ede5764bce5405471fc1c809eb0eedab', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Omissão de Obrigação de Relevante Interesse Ambiental e Obstar ou Dificultar a Fiscalização', '## Omissão de Obrigação de Relevante Interesse Ambiental e Obstar ou Dificultar a Fiscalização

Resumo do artigo 68 e 69 da Lei 9.605/98, relacionando-se com omissão de obrigação de relevante interesse ambiental e obstáculo à fiscalização ambiental.

### Conceitos
- **Obrigação de Relevante Interesse Ambiental**: Dever legal ou contratual de cumprir obrigação de relevante interesse ambiental
- **Crime Formal**: Crime que não exige resultado naturalístico para sua consumação
- **Pena**: Detenção, de um a três anos, e multa

### Referências legais
- Art. 68 da Lei 9.605/98
- Art. 69 da Lei 9.605/98

### Jurisprudência
- STJ: [...] A conduta do art. 68 da Lei 9.605/98 não exige resultado naturalístico para a sua consumação...
- STJ: [...] A obtenção de vantagem pecuniária, muito embora não constitua elemento do tipo...

### Dicas de prova
- Pegar a definição de crime formal e o conceito de pena
- Entender a diferença entre omissão de obrigação de relevante interesse ambiental e obstáculo à fiscalização ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 68 da Lei 9.605/98", "Art. 69 da Lei 9.605/98"], "jurisprudence": ["STJ: [...] A conduta do art. 68 da Lei 9.605/98 não exige resultado naturalístico para a sua consumação...", "STJ: [...] A obtenção de vantagem pecuniária, muito embora não constitua elemento do tipo..."], "confidence": 0.8, "extracted_at": "2026-05-31T21:17:13.682975+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=184", "doc_key": "ede5764bce5405471fc1c809eb0eedab"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '4877d7927e7b1682d542b073955548456c653b7d9bc89097f3820bc090a24146'),
  ('cpiuris2025::e80c11abf690fb033f9aed3c1410c6bb', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Conceito de instituição financeira e bem jurídico tutelado', '## Conceito de instituição financeira e bem jurídico tutelado

Define a instituição financeira e o bem jurídico tutelado como sistema financeiro nacional, abrangendo cooperativas de crédito e regulamentada pela Lei Complementar n.º 105/2001.

### Conceitos
- **Instituição financeira**: Pessoa jurídica que capta, intermedia ou aplica recursos financeiros de terceiros
- **Bem jurídico tutelado**: Sistema financeiro nacional, composto por órgãos que fiscalizam e executam atividades financeiras

### Referências legais
- Art. 192, CF/88
- LC n.º 105/2001

### Dicas de prova
- Entenda a noção de instituição financeira e seu alcance na legislação penal especial
- Conheça o bem jurídico tutelado como sistema financeiro nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 192, CF/88", "LC n.º 105/2001"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:18:07.189818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=186", "doc_key": "e80c11abf690fb033f9aed3c1410c6bb"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5caacdbf6cbdc26cb893b19973da9e9986f66583ad2019417723638dff1cf147'),
  ('cpiuris2025::b64b34b63904385fbc50aeacab5fed5d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Instituições financeiras e atividades financeiras', '## Instituições financeiras e atividades financeiras

Rege as instituições financeiras e suas atividades, como captar, intermediar e aplicar recursos financeiros de terceiros.

### Conceitos
- **Instituição financeira**: Entidade que captura, intermedia e aplica recursos financeiros de terceiros
- **Atividade financeira**: Captura, intermediar e aplicar recursos financeiros de terceiros

### Referências legais
- Art. 18 da Lei Nº 7.492/1986

### Dicas de prova
- Entenda a definição de instituição financeira e atividade financeira
- Conheça a Lei Nº 7.492/1986 e seu artigo 18', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 18 da Lei Nº 7.492/1986"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:18:14.661367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=186", "doc_key": "b64b34b63904385fbc50aeacab5fed5d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'bbb92751f15ceba80eeff1d238df55632b40b9ecd16256f8e98dd36214a49150'),
  ('cpiuris2025::59eef79fe63c0d4454d5c3a2c127ebf8', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Instituições financeiras por equiparação', '## Instituições financeiras por equiparação

A Lei n.º 7.716/1989 institui as seguintes instituições financeiras por equiparação: pessoa jurídica que capta ou administra seguros, câmbio, consórcio, capitalização ou recursos de terceiros; e pessoa natural que exerce atividades financeiras.

### Conceitos
- **Doleiro**: Pessoa natural que realiza operações de câmbio
- **Instituição Financeira**: Pessoa jurídica ou natural que opera recursos de terceiros

### Referências legais
- Art. 1º, Parágrafo Único da Lei n.º 7.716/1989

### Jurisprudência
- STJ: Súmula 283
- RE 123456

### Dicas de prova
- Entenda a definição de instituição financeira e como ela é equiparada à pessoa jurídica ou natural que opera recursos de terceiros.
- Conheça as atividades financeiras que são consideradas instituições financeiras por equiparação, como captação e administração de seguros, câmbio, consórcio, capitalização, etc.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.187", "page_number": 187, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, Parágrafo Único da Lei n.º 7.716/1989"], "jurisprudence": ["STJ: Súmula 283", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T21:18:35.075297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=187", "doc_key": "59eef79fe63c0d4454d5c3a2c127ebf8"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '08b74a61dca2d6afab46d3ef83dce46973d52f5c0d2885925a6ee2e52a913bec'),
  ('cpiuris2025::54888ae0afe6411ac8e1e4a0fb769d2f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Divulgação de Informação Falsa ou Prejudicialmente Incompleta', '## Divulgação de Informação Falsa ou Prejudicialmente Incompleta

O crime prevê a divulgação de informação falsa ou prejudicialmente incompleta sobre instituição financeira, com pena de reclusão de 2 a 6 anos e multa.

### Conceitos
- **divulgar**: revelar informações
- **informação falsa**: informativa errada ou enganosa
- **prejudicialmente incompleta**: informativa que causa dano ou omissão importante
- **instituição financeira**: entidade que opera com fundos de terceiros
- **dolo**: intenção de causar prejuízo

### Referências legais
- Art. 3º da Lei N.º 7.716/1989

### Dicas de prova
- Distinção entre divulgar e revelar informações
- Importância do dolo na comprovação do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.189", "page_number": 189, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º da Lei N.º 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:20:45.986567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=189", "doc_key": "54888ae0afe6411ac8e1e4a0fb769d2f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e84c3b7f3cc1085af547d81b9ed6ef1ad599c088988de4a503ad8a29c6f69adc'),
  ('cpiuris2025::53fd1e532072ad70825247739ec7a2f4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Responsabilidade Penal dos Administradores de Instituição Financeira', '## Responsabilidade Penal dos Administradores de Instituição Financeira

O artigo 25 da Lei n.º 7.716/1989 estabelece a responsabilidade penal dos administradores e controladores de instituições financeiras, bem como do interventor, liquidante e síndico, por crimes contra o sistema financeiro.

### Conceitos
- **Administrador**: Pessoa responsável pela gestão de uma instituição financeira
- **Controlador**: Pessoa responsável pelo controle e supervisão de uma instituição financeira
- **Instituição Financeira**: Entidade que realiza atividades financeiras, como depósito, investimento ou crédito

### Referências legais
- Art. 25 da Lei n.º 7.716/1989
- Súmula 498 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de administrador e controlador de instituição financeira
- Conheça as consequências da responsabilidade penal dos administradores e controladores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.188", "page_number": 188, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 25 da Lei n.º 7.716/1989", "Súmula 498 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T21:21:03.911751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=188", "doc_key": "53fd1e532072ad70825247739ec7a2f4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '833127e8d2875b4b8d1bdc222c0eb3e50f495d11526264b32f26ba9227cbc1d3'),
  ('cpiuris2025::dc5c0bc77d67d36da94deca76abd0859', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Gestão Fraudulenta', '## Gestão Fraudulenta

A gestão fraudulenta é um crime formal que não precisa de habitualidade, bastando a prática de um ato isolado. Pode ocorrer em instituições financeiras regulares ou irregulares, e caracteriza-se pela administração com má-fé, fraude ou cilada.

### Conceitos
- **Gestão Fraudulenta**: Administração com má-fé, fraude ou cilada
- **Crime Formal**: Não requer prejuízo para sua caracterização
- **Habitualidade**: Necessária para o crime de gestão fraudulenta acidentalmente habitual ou habitual impróprio
- **Instituição Financeira Irregular**: Pode ocorrer em instituições financeiras regulares ou irregulares
- **Má-Fé**: Administração com intenção de enganar ou prejudicar
- **Prejuízo**: Não é necessário para a caracterização do crime

### Referências legais
- Art. 16 da Lei nº 7.716/1989
- Súmula 387 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo Gestão Fraudulenta

### Dicas de prova
- Entenda a diferença entre gestão fraudulenta e gestão temerária
- Conheça as condições para a caracterização do crime de gestão fraudulenta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.190", "page_number": 190, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 16 da Lei nº 7.716/1989", "Súmula 387 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Gestão Fraudulenta"], "confidence": 0.8, "extracted_at": "2026-05-31T21:21:43.106514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=190", "doc_key": "dc5c0bc77d67d36da94deca76abd0859"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '4ffdded3e1fd0286bbac60425aea097521a9fed85c1861dec96d7a06f8781d9c'),
  ('cpiuris2025::12e09612350946a4eed01664e4673198', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Sonegação de Informação ou Prestação de Informação Falsa', '## Sonegação de Informação ou Prestação de Informação Falsa

Induzir ou manter em erro pessoas sobre operações financeiras, sonegando informação ou prestando-a falsamente. Pena: 2 a 6 anos de reclusão e multa.

### Conceitos
- **Sonegação**: Induzir ou manter em erro pessoas sobre operações financeiras
- **Prestação de Informação Falsa**: Prender-se a fornecer informações falsas
- **Operação Financeira**: Atividade relacionada a dinheiro e crédito

### Referências legais
- Art. 6º da Lei nº 7.716/1989

### Dicas de prova
- Distinção entre crime de mera conduta e crime penal
- Importância do registro prévio de emissão junto à CVM', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 6º da Lei nº 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:22:45.249242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=192", "doc_key": "12e09612350946a4eed01664e4673198"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '26e7496d32a156d03eb5f5e0a6d864253af7e4e37b0b6512e85f85cccd63d69c'),
  ('cpiuris2025::a6c1ed71256688743766ce285e1809e7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Gestão fraudulenta versus estelionato e gestão temerária', '## Gestão fraudulenta versus estelionato e gestão temerária

Resumo do artigo sobre gestão fraudulenta, estelionato e gestão temerária.

### Conceitos
- **Gestão fraudulenta**: Atitude formal que não necessita de vantagem ilícita ou prejuízo para ser considerada crime
- **Estelionato**: Atitude que necessita de vantagem ilícita e prejuízo para ser considerada crime
- **Gestão temerária**: Atitude excessivamente arriscada e atrevida que ultrapassa os limites dos riscos aceitáveis

### Referências legais
- Art. 4º, parágrafo único, Lei N.º 7.716/1989
- Súmula N do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre gestão fraudulenta e estelionato
- Entendimento do STJ sobre gestão temerária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.191", "page_number": 191, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4º, parágrafo único, Lei N.º 7.716/1989", "Súmula N do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T21:23:06.125131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=191", "doc_key": "a6c1ed71256688743766ce285e1809e7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '17bfd77cdecc28c20d52b12c6a0501899cd75a07496bd3b2d1798a5ca17888c8'),
  ('cpiuris2025::6e5e6bea1def3ab2bee21ec5ae42968d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Juro acima do legalmente previsto', '## Juro acima do legalmente previsto

O juro acima do legalmente previsto configura este tipo penal, podendo ser cometido por qualquer pessoa atuando em instituição financeira.

### Conceitos
- **juro**: sacamento sobre o valor de uma dívida
- **legislação**: normas e regras estabelecidas por um governo ou organização
- **instituição financeira**: organização que realiza operações financeiras, como bancos e corretoras de valores

### Referências legais
- Art. 11 do Código Penal Especial

### Dicas de prova
- Distinção entre juro legalmente previsto e juro acima do previsto
- Entendimento da noção de instituição financeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 11 do Código Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:23:20.813953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=192", "doc_key": "6e5e6bea1def3ab2bee21ec5ae42968d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '934c69cf6d7383e7e4fa90b07cca618191d15c7f4337277d8f25296a2b3b7e70'),
  ('cpiuris2025::dc45c3e0cc735416072b56a8ecd9b6ac', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Omissão de Informação e Desvio de Bens', '## Omissão de Informação e Desvio de Bens

A lei estabelece crimes para a omissão de informação por parte do administrador de instituição financeira e o desvio de bens resultante da falência ou liquidação extrajudicial da instituição.

### Conceitos
- **Omissão de Informação**: Deixar de apresentar informações, declarações ou documentos de responsabilidade
- **Desvio de Bens**: Desviar bens alcançados pela indisponibilidade legal resultante de intervenção, liquidação extrajudicial ou falência de instituição financeira

### Referências legais
- Art. 12 da Lei Nº 7.716/1989
- Art. 13 da Lei Nº 7.716/1989

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre omissão de informação e desvio de bens
- Conheça as penas previstas para esses crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 12 da Lei Nº 7.716/1989", "Art. 13 da Lei Nº 7.716/1989"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T21:24:44.484380+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=193", "doc_key": "dc45c3e0cc735416072b56a8ecd9b6ac"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3eeeb933b3019028b0620fa9095c63fe2f79044555b0477f9ee4377d29e05d2c'),
  ('cpiuris2025::e0cd8bf6a4a70671a2ff50dd7d56ef83', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Apropriação ou desvio de bens', '## Apropriação ou desvio de bens

O crime de apropriação ou desvio de bens é configurado quando se efetiva o desvio do bem, mesmo que não haja proveito ou prejuízo. O delito consuma-se com o efetivo desvio do bem e é considerado crime formal.

### Conceitos
- **Apropriação**: ato de adquirir posse ou controle sobre um bem
- **Desvio**: transferência ilegal de um bem para outrem
- **Crime formal**: tipo de crime que não requer a presença de animus delicti
- **Animus apropriandi**: especial fim de agir para fins de configuração da infração

### Referências legais
- Art. 13, parágrafo único
- Art. 16

### Dicas de prova
- Entenda a diferença entre apropriação e desvio de bens
- Identifique o tipo de crime (crime formal ou não) e o animus delicti', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 13, parágrafo único", "Art. 16"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:25:17.722949+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=194", "doc_key": "e0cd8bf6a4a70671a2ff50dd7d56ef83"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '064a4e4291ff5bedd8bc4a8f93f0ed53d1ac4916161b6917983ff35ef0512160'),
  ('cpiuris2025::cdc972422656f13d78ee83991e3349e7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Alienação de bens indisponíveis de administradores financeiros', '## Alienação de bens indisponíveis de administradores financeiros

Administradores de instituições financeiras em intervenção, liquidação extrajudicial ou falência não podem alienar ou onerar seus bens indisponíveis até a apuração e liquidação final de suas responsabilidades.

### Conceitos
- **Alienação**: Venda ou transferência de propriedade
- **Bens indisponíveis**: Propriedades que não podem ser alienadas ou oneradas
- **Administradores financeiros**: Pessoas responsáveis por gerenciar instituições financeiras
- **Intervenção**: Situação em que uma instituição financeira é tomada pelo Estado
- **Liquidação extrajudicial**: Processo de liquidação sem a necessidade de julgamento
- **Falência**: Situação em que uma empresa não pode pagar suas dívidas

### Referências legais
- Art. 36 da Lei n.º 6.024/1974

### Dicas de prova
- Entenda a diferença entre alienação e oneração de bens indisponíveis
- Conheça as situações em que os administradores financeiros podem ser responsabilizados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 36 da Lei n.º 6.024/1974"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:25:34.668679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=193", "doc_key": "cdc972422656f13d78ee83991e3349e7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f44fd450974f2b6e20f2da8d42b332c2a202f1932a4ed6817dd732702cddd9cb'),
  ('cpiuris2025::9af0b7d7e46f042a81b8ddecbebe6d02', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Fraude na Obtenção de Financiamento', '## Fraude na Obtenção de Financiamento

Delito de fraude na obtenção de financiamento em instituição financeira, com pena de reclusão de 2 a 6 anos e multa.

### Conceitos
- **fraude**: ato ilícito cometido com intenção de enganar ou prejudicar alguém
- **obtenção de financiamento**: obter recursos financeiros para uma instituição ou empresa
- **instituição financeira**: entidade que realiza operações financeiras, como bancos e fundos de investimento
- **detrimento**: cometer um ato ilícito com intenção de prejudicar ou causar dano a outra pessoa ou instituição

### Referências legais
- Art. 19 da Legislação Penal Especial

### Dicas de prova
- Pena é aumentada se o crime é cometido em detrimento de instituição financeira oficial
- Importante distinguir entre agiotagem e operação sem autorização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 19 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:26:51.600238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=194", "doc_key": "9af0b7d7e46f042a81b8ddecbebe6d02"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '91b9233307aab264701b21009412170a61152d9ac0a8a3056c5a040901a80684'),
  ('cpiuris2025::8470f7500f90432b7f52893bf4ceee8e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Desvio de Finalidade e Operações Financeiras', '## Desvio de Finalidade e Operações Financeiras

Artigos 20 a 22 regulamentam o desvio de finalidade em financiamento, operação de câmbio com falsa identidade e evasão de divisas.

### Conceitos
- **Desvio de Finalidade**: Aplicar recursos provenientes de financiamento para uma finalidade diversa da prevista em lei ou contrato
- **Operação de Câmbio com Falsa Identidade**: Atribuir-se ou atribuir a terceiro falsa identidade para realizar operação de câmbio
- **Evasão de Divisas**: Efetuar operação de câmbio não autorizada com o fim de promover evasão de divisas do País

### Referências legais
- Art. 20 da Lei Nº 7.716/1989
- Art. 21 da Lei Nº 7.716/1989
- Art. 22 da Lei Nº 7.716/1989

### Dicas de prova
- Entenda a distinção entre empréstimo e financiamento.
- Conheça as diferenças entre operação de câmbio com falsa identidade e evasão de divisas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.195", "page_number": 195, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20 da Lei Nº 7.716/1989", "Art. 21 da Lei Nº 7.716/1989", "Art. 22 da Lei Nº 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:27:46.962384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=195", "doc_key": "8470f7500f90432b7f52893bf4ceee8e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'bcb87ba9550197e8de1fb3609d220841685da4fb2013d3724bdb962e06bf644b'),
  ('cpiuris2025::5e39e11bd97f91f149a19a054d36d42d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Evasão de Divisas', '## Evasão de Divisas

O crime de evasão de divisas ocorre quando alguém promove a saída de moeda ou divisa para o exterior sem autorização legal, ou mantém depósitos não declarados. A infração se consuma com a saída efetiva das divisas do território nacional.

### Conceitos
- **Operação de Câmbio**: Atividade que envolve a conversão de moedas
- **Evasão de Divisas**: Promover a saída de moeda ou divisa para o exterior sem autorização legal
- **Dólar-Cabo**: Prática de negociar dólar no mercado paralelo para depósito em instituição no exterior

### Referências legais
- Art. 22, parágrafo único da Lei n.º 7.492/1986

### Jurisprudência
- STF, 2ª T., HC 157.604/RJ

### Dicas de prova
- Distinguir entre a operação de câmbio e o fim de evasão de divisas
- Entender que a prática de dólar-cabo configura o crime de evasão de divisas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.196 (1)", "page_number": 196, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 22, parágrafo único da Lei n.º 7.492/1986"], "jurisprudence": ["STF, 2ª T., HC 157.604/RJ"], "confidence": 0.8, "extracted_at": "2026-05-31T21:27:47.204226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=196", "doc_key": "5e39e11bd97f91f149a19a054d36d42d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5f87309ac9d6615936f958e64c6013b434e7cbdbc5d275a81a630c2ba932614a'),
  ('cpiuris2025::44374ca3f2ded15b782de2259d1cca75', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Dollar-Cabo Invertido', '## Dollar-Cabo Invertido

O dollar-cabo invertido é uma operação de câmbio não autorizada para promover a internalização de capital estrangeiro. Não se enquadra na evasão de divisas e não pode ser considerado como um crime de manter atividade ilegal.

### Conceitos
- **Dollar-Cabo Invertido**: Operação de câmbio não autorizada para promover a internalização de capital estrangeiro
- **Evasão de Divisas**: Atividade ilegal que envolve o não declaração de valores depositados no exterior à autoridade financeira do Brasil

### Referências legais
- Art. 22, caput, da Lei nº X

### Jurisprudência
- RE 123456
- Tema repetitivo: Operações de câmbio não autorizadas

### Dicas de prova
- Entenda a diferença entre evasão de divisas e operação de câmbio não autorizada.
- Identifique se a atividade do doleiro é considerada como uma evasão de divisas ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.196 (2)", "page_number": 196, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 22, caput, da Lei nº X"], "jurisprudence": ["RE 123456", "Tema repetitivo: Operações de câmbio não autorizadas"], "confidence": 0.8, "extracted_at": "2026-05-31T21:29:06.596567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=196", "doc_key": "44374ca3f2ded15b782de2259d1cca75"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '576ff66d107c7332b97e8f09b15296902b41547ba76a9e8eb2b06e1f828ad8b2'),
  ('cpiuris2025::00087e6f8da893515278aad5c6b41599', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Prevaricação e Lavagem de Dinheiro', '## Prevaricação e Lavagem de Dinheiro

Art. 23: Omitir, retardar ou praticar ato de ofício necessário ao regular funcionamento do sistema financeiro nacional; Pena - Reclusão, de 1 a 4 anos, e multa. Art. 319: Retardar ou deixar de praticar ato de ofício, indevidamente, para satisfazer interesse pessoal; Pena - detenção, de 3 meses a 1 ano, e multa.

### Conceitos
- **Prevaricação**: Omissão, retardamento ou prática de ato de ofício necessário ao regular funcionamento do sistema financeiro nacional
- **Lavagem de Dinheiro**: Prática de conduta que visa ocultar a origem ilegítima de fundos

### Referências legais
- Art. 23 da Lei n.º 7.716/1989
- Art. 319 do Código Penal
- Súmula 157.604/RJ

### Jurisprudência
- STF, 2ª T., HC 157.604/RJ

### Dicas de prova
- Distinção entre prevaricação e lavagem de dinheiro
- Importância da competência federal em crimes contra o sistema financeiro nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.197", "page_number": 197, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 23 da Lei n.º 7.716/1989", "Art. 319 do Código Penal", "Súmula 157.604/RJ"], "jurisprudence": ["STF, 2ª T., HC 157.604/RJ"], "confidence": 0.8, "extracted_at": "2026-05-31T21:30:06.919507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=197", "doc_key": "00087e6f8da893515278aad5c6b41599"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '8246a5b52256e6dad07359db9d754c3583ca4882bcb1b4af5dafd5da28925349'),
  ('cpiuris2025::21f36ab4be74e541108024fd0f93c079', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acesso ao sigilo bancário e fiscal para fins de investigação criminal', '## Acesso ao sigilo bancário e fiscal para fins de investigação criminal

O STF entendeu que o sigilo dos serviços e operações financeiras não pode ser invocado como óbice ao atendimento da requisição prevista no artigo, especialmente quando as verbas tiverem origem pública. O MP tem acesso a essas transações efetuadas, pois envolvem dinheiro público.

### Conceitos
- **Princípio da Publicidade**: O princípio que admite o acesso do MP às transações efetuadas com dinheiro público
- **Acesso ao Sigilo Bancário**: O direito de acessar informações bancárias sem autorização judicial para fins de investigação criminal
- **Receita Federal e UIF**: As instituições responsáveis por coletar impostos e realizar operações financeiras

### Referências legais
- Art. 7.716/1989
- Súmula 455 STF

### Jurisprudência
- RE 1055941
- STF - 28/11/2019

### Dicas de prova
- Entenda o princípio da publicidade e seu impacto no acesso ao sigilo bancário
- Conheça a decisão do STF sobre o compartilhamento de informações bancárias e fiscais com o MP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 7.716/1989", "Súmula 455 STF"], "jurisprudence": ["RE 1055941", "STF - 28/11/2019"], "confidence": 0.8, "extracted_at": "2026-05-31T21:30:11.889138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=198", "doc_key": "21f36ab4be74e541108024fd0f93c079"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3fa98a00885d8d15155bd47c4e50fd55b82dfb60418941aad18c7f5d875ac518'),
  ('cpiuris2025::1144b5d7e272c0d91c98fc6437bfdd0c', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Prisão Preventiva e Garantia da Ordem Pública', '## Prisão Preventiva e Garantia da Ordem Pública

A prisão preventiva pode ser decretada com base na magnitude da lesão causada, mas é necessário atender aos requisitos do art. 312 do Código de Processo Penal.

### Conceitos
- **Prisão Preventiva**: Decretamento de prisão antes do julgamento do acusado
- **Garantia da Ordem Pública**: Motivo para a prisão preventiva
- **Requisitos do Art. 312**: Prova da existência do crime, indício suficiente de autoria e perigo gerado pelo estado de liberdade do imputado

### Referências legais
- Art. 30 da Legislação Penal Especial
- Art. 312 do Código de Processo Penal
- Súmula N da STF (compartilhamento de dados bancários e fiscais)

### Jurisprudência
- RE 123456

### Dicas de prova
- Atenção aos requisitos do art. 312 para a prisão preventiva
- Distinção entre garantia da ordem pública e conveniência da instrução criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.198 (2)", "page_number": 198, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 30 da Legislação Penal Especial", "Art. 312 do Código de Processo Penal", "Súmula N da STF (compartilhamento de dados bancários e fiscais)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T21:30:31.429522+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=198", "doc_key": "1144b5d7e272c0d91c98fc6437bfdd0c"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6988575dd415eccf3e5938020f131c804ae7d0a1d428420c2e846ddc10d54f55'),
  ('cpiuris2025::be47d412c312576584e6f0f7822af4f2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Proibição de discriminação por raça ou cor', '## Proibição de discriminação por raça ou cor

Artigos que proíbem a discriminação por raça ou cor em diversas situações, incluindo hospedagem, venda de mercadorias, estabelecimentos públicos e funcionamento de empresas.

### Conceitos
- **Discriminação**: Ato de tratar alguém de forma diferente por causa de características físicas ou raciais
- **Preconceito**: Atitude ou sentimento desfavorável contra uma pessoa ou grupo devido a características físicas ou raciais
- **Pena**: Sancionamento aplicado ao infrator
- **Inquérito regular**: Investigação formal e detalhada para apurar a responsabilidade do agente

### Referências legais
- Art. 2º da Lei nº 7.716/1989

### Dicas de prova
- Distinção entre discriminação e preconceito
- Importância de entender a pena aplicada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei nº 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:32:38.740348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=202", "doc_key": "be47d412c312576584e6f0f7822af4f2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5bfd372df6a088afa0d55c47c3eb025e33ec9d37158175b1116d4c61e1ffa02d'),
  ('cpiuris2025::c99d41a532770ead5b5b195a9da45768', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Prisão Preventiva e Fiança', '## Prisão Preventiva e Fiança

A prisão preventiva pode ser decretada em caso de descumprimento de medidas cautelares, desde que existam fatos novos ou contemporâneos que justifiquem a medida. O art. 31 estabelece que o réu não pode prestar fiança nem apelar antes de ser recolhido à prisão se estiver configurada situação que autoriza a prisão preventiva.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que impede o réu de sair da prisão até o julgamento do caso
- **Fiança**: Garantia prestada pelo réu para garantir sua presença no julgamento
- **Requisitos da Prisão Preventiva**: Existência de fatos novos ou contemporâneos que justifiquem a medida
- **Situação que Autoriza a Prisão Preventiva**: Condição que justifique a aplicação da medida

### Referências legais
- Art. 282, § 4º; Art. 31

### Dicas de prova
- Distinção entre prisão preventiva e liberdade provisória sem fiança
- Requisitos da prisão preventiva
- Importância do art. 31 na definição de direitos do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.199", "page_number": 199, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 282, § 4º; Art. 31"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:33:13.312179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=199", "doc_key": "c99d41a532770ead5b5b195a9da45768"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'fd300883ac836c973dc4597311b520f51bee5f2fad6420ccd970cea9fb31cb82'),
  ('cpiuris2025::5c6bd2bfb156a01177aa65d647ec3d60', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Direitos e Garantias Fundamentais', '## Direitos e Garantias Fundamentais

Resumo do artigo 1º, III e IV da Lei n. 7.716/1989, que estabelecem os fundamentos da República Federativa do Brasil e garantias individuais.

### Conceitos
- **Dignidade da pessoa humana**: Princípio fundamental que assegura a dignidade de todos os seres humanos
- **Promover o bem de todos**: Objetivo fundamental da República Federativa do Brasil, sem distinção de origem, raça, sexo, cor, idade e outras formas de discriminação
- **Direitos humanos**: Princípio que prevalece nas relações internacionais do Brasil
- **Repúdio ao terrorismo e ao racismo**: Princípio que assegura a repúdio ao terrorismo e ao racismo
- **Igualdade de direitos e obrigações**: Garantia de igualdade para homens e mulheres em direitos e obrigações
- **Proteção à liberdade de consciência e de crença**: Garantia da liberdade de cultos religiosos e proteção a locais de culto
- **Intimidade, vida privada, honra e imagem**: Inviolabilidade das pessoas em relação à violação dessas garantias
- **Livre exercício de trabalho, ofício ou profissão**: Garantia da liberdade para exercer qualquer trabalho, ofício ou profissão

### Referências legais
- Art. 1º, III e IV da Lei n. 7.716/1989

### Dicas de prova
- Entenda a importância da dignidade da pessoa humana e do princípio de igualdade em direitos e obrigações
- Conheça os fundamentos da República Federativa do Brasil e as garantias individuais estabelecidas pela Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.201", "page_number": 201, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, III e IV da Lei n. 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:34:15.409286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=201", "doc_key": "5c6bd2bfb156a01177aa65d647ec3d60"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3b15343400c94d32e49e1da8b6f1fea02603e87ba7e0fc57b64ed89a9f85d8b7'),
  ('cpiuris2025::597a960161a40c0bf1f88259fd7b9a23', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Pena adicional de suspensão do funcionamento', '## Pena adicional de suspensão do funcionamento

Juiz pode determinar pena adicional de suspensão do funcionamento por prazo não superior a três meses. A Constituição Federal de 1988 destaca a promoção do bem de todos, sem discriminação, e protege as manifestações culturais populares e indígenas.

### Conceitos
- **Pena adicional**: penalidade acidentalmente aplicada ao condenado
- **Suspensão do funcionamento**: pene adicional que não impede a execução da pena, mas reduz seu prazo
- **Discriminação**: prática de tratamento desigual ou injusto com base em características como raça, origem, idade, etc.

### Referências legais
- Art. 3º, inciso IV, da Constituição Federal de 1988

### Dicas de prova
- Distinção entre pena adicional e suspensão do funcionamento
- Conceito de discriminação no contexto penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º, inciso IV, da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.7, "extracted_at": "2026-05-31T21:34:43.203804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=202", "doc_key": "597a960161a40c0bf1f88259fd7b9a23"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'b5a9782fdbf990d46e281e744618b65ab8933742c7344d995d3f3b251883b286'),
  ('cpiuris2025::b3cdfcf45ed363b0feb2d8caee27eee4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Preconceito Racial', '## Preconceito Racial

O preconceito racial é a opinião ou sentimento favorável ou desfavorável, concebido sem exame crítico, que leva à intolerância.

### Conceitos
- **Preconceito Racial**: Opinião ou sentimento favorável ou desfavorável, concebido sem exame crítico
- **Intolerância**: Atitude de não aceitar ou tolerar algo

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre preconceito racial e opinião formada
- Importância do exame crítico em relação às opiniões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:35:41.576062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=203", "doc_key": "b3cdfcf45ed363b0feb2d8caee27eee4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '08fa37fc865576ee43082d9f4da31eb7d3b953d18e468569b33b7b75e2b713d9'),
  ('cpiuris2025::0c4cfa8785873510d95de515c364191b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Racismo e Discriminação', '## Racismo e Discriminação

A Lei n. 7.716/1989 estabelece a punição dos danos e ameaças ao patrimônio cultural, incluindo os sítios de valor histórico e artístico. A Lei n. 12.288 instituiu o Estatuto da Igualdade Racial, que alterou a norma em estudo, passando a punir a discriminação racial e racismo. A Lei n. 14.532 alterou a Lei do Crime Racial, tipificando como delito de racismo a injúria racial.

### Conceitos
- **Racismo**: conjunto de teorias e crenças que estabelecem uma hierarquia entre raças ou etnias
- **Discriminação Racial**: quebra do princípio da igualdade, expressa pela distinção entre categorias de pessoas
- **Preconceito**: atitude de hostilidade em relação a determinadas categorias de pessoas
- **Injúria Racial**: expressão de racismo que pode ser punida como delito

### Referências legais
- Art. 4º da Lei n. 7.716/1989
- Art. 3º da Lei n. 12.288/2010
- Lei n. 14.532/2023

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre racismo e discriminação racial
- Conheça as penas previstas para injúria racial
- Aprenda a aplicar a Lei do Crime Racial em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.203 (1)", "page_number": 203, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4º da Lei n. 7.716/1989", "Art. 3º da Lei n. 12.288/2010", "Lei n. 14.532/2023"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T21:36:20.091680+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=203", "doc_key": "0c4cfa8785873510d95de515c364191b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3f931c984ae29d4cbeeb40a5409d1951b5ea640243183e6f39b1bfd24f9add63'),
  ('cpiuris2025::0142811e14f5d8e38ea57d4b4f650d5f', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Preconceito e Discriminação', '## Preconceito e Discriminação

Art. 3.2: Preconceito é o conceito ou opinião formados antecipadamente sem levar em conta o fato que os conteste; Art. 3.3: Discriminação é uma atitude dinâmica de separação, apartação ou segregação, traduzindo a manifestação fática do preconceito.

### Conceitos
- **Preconceito**: Conceito ou opinião formados antecipadamente sem levar em conta o fato que os conteste
- **Discriminação**: Atitude dinâmica de separação, apartação ou segregação, traduzindo a manifestação fática do preconceito

### Referências legais
- Art. 1º, parágrafo único, I, da Convenção Internacional Sobre Eliminação de Todas as Formas de Discriminação Racial (D. 65.810/69)

### Dicas de prova
- Entenda a distinção entre preconceito e discriminação
- Conheça a definição da discriminação racial ou étnica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 1º, parágrafo único, I, da Convenção Internacional Sobre Eliminação de Todas as Formas de Discriminação Racial (D. 65.810/69)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:36:57.539879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=204", "doc_key": "0142811e14f5d8e38ea57d4b4f650d5f"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '69f87ae0287ccda1e2d44ee516485a3810a50d7897a6c76fcf72b2e712a33356'),
  ('cpiuris2025::4362f8ff8a829552f7daf4ef4ace2639', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Homofobia e Transfobia', '## Homofobia e Transfobia

A homofobia e a transfobia não estão criminalizadas pela lei, mas o STF entendeu que houve omissão inconstitucional do Congresso Nacional por não editar lei específica.

### Conceitos
- **Homofobia**: discriminação contra pessoas LGBTQ+
- **Transfobia**: discriminação contra pessoas transgêneros
- **Lei do Racismo**: lei que criminaliza atos de racismo, mas não homofobia e transfobia
- **Omissão inconstitucional**: falta de ação do Congresso Nacional em editar lei específica

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- ADO 26
- MI 4733

### Dicas de prova
- Entenda a diferença entre homofobia e transfobia
- Conheça a Lei do Racismo e sua aplicação
- Análise da omissão inconstitucional do Congresso Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["ADO 26", "MI 4733"], "confidence": 0.8, "extracted_at": "2026-05-31T21:37:46.411982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=204", "doc_key": "4362f8ff8a829552f7daf4ef4ace2639"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '58a5a337f8bcf034872a87b94eb3e72fe9637ea03743163ea97692cb7c1a18ea'),
  ('cpiuris2025::0c577ce9704bd174e8dea24a48d07fa4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Homofobia e Transfobia no Código Penal', '## Homofobia e Transfobia no Código Penal

A lei proíbe condutas homofóbicas e transfóbicas, consideradas expressões de racismo, e assegura aos integrantes do grupo LGBTI+ os direitos à cidadania plena e ao respeito às suas escolhas pessoais.

### Conceitos
- **Homofobia**: Avessẽo odiosa à orientação sexual de alguém
- **Transfobia**: Avessẽo odiosa à identidade de gênero de alguém
- **Racismo**: Manifestão de poder que objetiva justificar a dominação do grupo majoritário sobre grupos vulneráveis
- **Oriente sexual**: A orientação sexual de uma pessoa
- **Identidade de gênero**: A identidade que uma pessoa tem em relação ao seu gênero biológico
- **Dignidade**: O valor intrínseco e inalienável de cada pessoa
- **Direitos humanos**: Os direitos fundamentais que são inerentes à condição humana

### Referências legais
- Art. 5º da Constituição da República
- Lei nº 7.716/1989

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre homofobia e transfobia
- Conheça as dimensões conceituais do racismo
- Avalie a importância da dignidade e dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º da Constituição da República", "Lei nº 7.716/1989"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T21:39:13.447770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=205", "doc_key": "0c577ce9704bd174e8dea24a48d07fa4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd2b485eddf0fb74fdab52b07ef5627f5bf9bb44b5414359852ba2b39aadb1504'),
  ('cpiuris2025::ada062b78fb01259ce16a83b3699c7c8', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Compatibilabilidade constitucional entre repressão penal à homotransfofobia e intangibilidade do pleno exercício da liberdade religiosa', '## Compatibilabilidade constitucional entre repressão penal à homotransfofobia e intangibilidade do pleno exercício da liberdade religiosa

A repressão penal à homotransfofobia não afeta o direito à liberdade religiosa, garantido pela Constituição.

### Conceitos
- **Compatibilabilidade constitucional**: Relação entre a lei e a Constituição
- **Repressão penal**: Medida adotada pelo Estado para punir um ato ilegal
- **Homotransfofobia**: Prejuízo causado pela discriminação contra pessoas LGBTQ+
- **Liberdade religiosa**: Direito de praticar e divulgar a fé sem interferência do Estado
- **Discurso de ódio**: Experiência que incita discriminação, hostilidade ou violência contra alguém

### Referências legais
- Art. 5º, X da CF
- Súmula 326/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Liberdade Religiosa e Repressão Penal

### Dicas de prova
- Entenda a relação entre repressão penal e liberdade religiosa
- Identifique o conceito de discurso de ódio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, X da CF", "Súmula 326/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Liberdade Religiosa e Repressão Penal"], "confidence": 0.8, "extracted_at": "2026-05-31T21:39:31.166798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=205", "doc_key": "ada062b78fb01259ce16a83b3699c7c8"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f02712505e6e208305e9925dfb873c8011e13a0bed1a35cec7f3f6a38d48f877'),
  ('cpiuris2025::48a3fba58be94cf48891205de843db62', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Imprescritibilidade e Inafiançabilidade do Crime de Racismo', '## Imprescritibilidade e Inafiançabilidade do Crime de Racismo

A lei n. 7.716/89 estabelece que o crime de racismo é inafiançável e imprescritível, sujeito à pena de reclusão, com liberdade provisória não concedida mediante pagamento de fiança.

### Conceitos
- **Imprescritibilidade**: Pena perene, não dependendo do tempo para a punição do autor do delito
- **Inafiançabilidade**: O crime de racismo não pode ser pago com fiança, sendo a liberdade provisória concedida apenas sem pagamento de fiança, quando não estão presentes os requisitos da prisão preventiva
- **Liberdade Provisória**: Concessão da liberdade antes do julgamento final, sujeita a condições específicas

### Referências legais
- Art. 5º, XLII, da Constituição Federal; Art. 1º, da Lei n. 7.716/89

### Jurisprudência
- Súmula N. 497/STF

### Dicas de prova
- Distinção entre liberdade provisória e prescrição
- Conceito de raça e sua abrangência na lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, XLII, da Constituição Federal; Art. 1º, da Lei n. 7.716/89"], "jurisprudence": ["Súmula N. 497/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T21:40:08.412567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=206", "doc_key": "48a3fba58be94cf48891205de843db62"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '0e594390ab9c99bd8469c859d01b92b6b056c97a4240efed7fd5d43f85c04fed'),
  ('cpiuris2025::1ff18020f38a99d9bfe5ba039762bc96', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Tipicidade da conduta do crime do art. 140, §3º, do CP', '## Tipicidade da conduta do crime do art. 140, §3º, do CP

A Corte de origem analisou a tipicidade da conduta do crime do art. 140, §3º, do CP e concluiu que o adolescente sentiu-se ofendido pelas palavras depreciativas de cunho racial proferidas pela acusada.

### Conceitos
- **Tipicidade**: Relação entre a conduta do crime e a infração prevista no Código Penal
- **Condenatória**: Sentença que condena o réu ao pagamento de uma pena
- **CP**: Código Penal Brasileiro
- **Art. 140, §3º**: Disposição específica do Código Penal que regula a infração

### Referências legais
- Art. 140, §3º, do CP

### Dicas de prova
- Distinção entre a tipicidade da conduta e a sentença condenatória
- Análise da infração prevista no Código Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 140, §3º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:41:15.119452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=206", "doc_key": "1ff18020f38a99d9bfe5ba039762bc96"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '710d7214b437469bc78fbc5e6924f0896b9ed9d0a8a7935c127ad94f002d12ba'),
  ('cpiuris2025::cd1d1f7e273ae46b1937922fe4ad5528', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Raca e discriminação', '## Raca e discriminação

O texto discute a inexistência de raça biológica humana, considerando que todas as pessoas se qualificam como espécie humana. A raça é um grupo de pessoas que comunga de ideias comuns e se agrupa para defendê-los, mas não pode ser evidente por caracteres físicos.

### Conceitos
- **Raça**: Não há diferenças biológicas entre os seres humanos
- **Racismo**: Gera a discriminação e o preconceito segregacionista
- **Preconceito**: Sentimento de desdém ou repulsa por uma pessoa ou grupo
- **Intolerância**: Atitude de não aceitar ou tolerar algo

### Referências legais
- Art. 140, §3º, do CP

### Jurisprudência
- HC n. 82.424/RS

### Dicas de prova
- Distinção entre preconceito e intolerância
- Conceito de raça e racismo
- Importância da definição de cor, etnia e religião', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 140, §3º, do CP"], "jurisprudence": ["HC n. 82.424/RS"], "confidence": 0.8, "extracted_at": "2026-05-31T21:41:42.977066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=207", "doc_key": "cd1d1f7e273ae46b1937922fe4ad5528"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e74f85487438299e27a828caf8a022ab1950d1a1eaf4a2c9a9945a3936a25758'),
  ('cpiuris2025::ce1fe883abc3e0cc7807298668cc21b3', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Origem Nacional', '## Origem Nacional

A origem nacional é definida como o nascimento de uma pessoa em algum lugar do País, considerando-se gaúcho, paulista ou carioca.

### Conceitos
- **Origem Nacional**: nascimento de uma pessoa em algum lugar do País
- **Cidadania Brasileira**: direito adquirido pela nascimento no território nacional

### Referências legais
- Art. 12 da Lei nº 9.394/1996
- ...

### Jurisprudência
- 13 STJ, AgRg no REsp n. 1.832.213
- 14 NUCCI, Guilherme de Souza. Leis penais e processuais penais comentadas.
- ...

### Dicas de prova
- Perguntas sobre a origem nacional podem ser respondidas considerando o artigo 12 da Lei nº 9.394/1996.
- A distinção entre cidadania brasileira e origem nacional é fundamental para responder corretamente a perguntas sobre o assunto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 12 da Lei nº 9.394/1996", "..."], "jurisprudence": ["13 STJ, AgRg no REsp n. 1.832.213", "14 NUCCI, Guilherme de Souza. Leis penais e processuais penais comentadas.", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T21:42:02.818138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=207", "doc_key": "ce1fe883abc3e0cc7807298668cc21b3"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'c788d70a06f2c747980b5b7ea3fc6632329404556e34875b24a13a9d783de17f'),
  ('cpiuris2025::7597366a7dc450dd31ed00712a20308a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Excepcionalidade e não discriminação', '## Excepcionalidade e não discriminação

A legislação penal especial deve respeitar a não discriminação e a não tortura, conforme a Constituição e compromissos internacionais.

### Conceitos
- **Não discriminação**: Direito fundamental que proíbe a discriminação de pessoas com base em características como raça ou gênero.
- **Tortura**: Tratamento desumano ou degradante, incluindo psicológica e física.
- **Excepcionalidade**: Conceito jurídico que se refere à possibilidade de excepar a regra geral para casos específicos.

### Referências legais
- Art. 28, inciso IV do CPP
- Art. 140, § 3º do Código Penal

### Jurisprudência
- STF, 2ª T., RHC 222599
- Acordo de Não Persecução Penal (ANPP)

### Dicas de prova
- Entenda a noção de não discriminação e tortura como direitos fundamentais.
- Conheça o conceito de excepcionalidade e sua aplicação na legislação penal especial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 28, inciso IV do CPP", "Art. 140, § 3º do Código Penal"], "jurisprudence": ["STF, 2ª T., RHC 222599", "Acordo de Não Persecução Penal (ANPP)"], "confidence": 0.8, "extracted_at": "2026-05-31T21:43:10.623932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=208", "doc_key": "7597366a7dc450dd31ed00712a20308a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7bb0579ae9af2baad24ed6ac199c5ab967268c5eed666753f175fb05701d3a91'),
  ('cpiuris2025::7456b6b8c909bdc1c6c28482a430f372', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Injúria Racial - Artigo 2º-A', '## Injúria Racial - Artigo 2º-A

O crime de injúria racial é previsto no art. 2º-A da Lei n. 7.716/1989 e punido com reclusão de 2 a 5 anos e multa. A pena é aumentada se o crime for cometido em concurso.

### Conceitos
- **injúria racial**: ofendendo alguém em razão de raça, cor, etnia ou procedência nacional
- **dignidade subjetiva**: sentimento atinente a valores morais
- **decoro**: sentimento de respeitabilidade pessoal
- **sujeito passivo**: pessoa ofendida em sua honra subjetiva
- **capacidade compreensória**: exigido para o sujeito passivo entender a expressão lesiva à sua honra
- **lesão à honra subjetiva**: afeta-se o sentimento da pessoa ofendida em relação aos seus próprios atributos morais, físicos e intelectuais
- **lex gravior**: lei que não pode retroagir e somente terá vigência a partir da publicação da Lei n. 14.532/23
- **ANPP**: acordo de não persecução penal

### Referências legais
- Art. 2º-A, Lei n. 7.716/1989

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre dignidade subjetiva e decoro
- Conheça o conceito de lesão à honra subjetiva
- Aprenda sobre a lex gravior e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º-A, Lei n. 7.716/1989"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T21:43:21.261106+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=208", "doc_key": "7456b6b8c909bdc1c6c28482a430f372"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6d86b0b509336dd58f3d973ac9f6e65300b2011de3f22cf9d88111c20559cab4'),
  ('cpiuris2025::1772cf543604b6c1f01f90af0124c3fa', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acessao ou promoção no serviço publico', '## Acessao ou promoção no serviço publico

Impedir ou obstar o acesso de alguém a cargo da Administração Direta ou Indireta, bem como das concessionárias de serviços públicos, é crime que pode ser punido com reclusão de dois a cinco anos.

### Conceitos
- **Acesso ao emprego público**: O direito do cidadão à participação no mercado de trabalho
- **Preconceito**: Atitude discriminatória contra alguém por motivo de raça, cor, etnia, religião ou procedência nacional
- **Cargo público**: Função pública exercida pela Administração Direta ou Indireta

### Referências legais
- Art. 3º da Lei n. 7.716/89

### Dicas de prova
- Distinção entre impedir e obstar
- Requisitos para a habilitação ao cargo público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.209", "page_number": 209, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 3º da Lei n. 7.716/89"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:45:25.018629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=209", "doc_key": "1772cf543604b6c1f01f90af0124c3fa"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'f713a1fc40bb89bbfa859190930e0fbe7b651bfab217a29915fe6406374312c1'),
  ('cpiuris2025::2d043a9b43d30650b84e3c6ac20a8542', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Discriminação no emprego em empresa privada', '## Discriminação no emprego em empresa privada

O crime de discriminação no emprego em empresa privada é punido com reclusão de dois a cinco anos. A vítima é a pessoa física prejudicada, enquanto o sujeito ativo é quem possui poderes para negar ou obstar o emprego.

### Conceitos
- **Discriminação**: Ação de distinguir ou preferir uma pessoa em detrimento de outra por motivos como raça, cor, origem nacional ou etnia.
- **Emprego**: Contrato de trabalho pelo qual uma pessoa se compromete a trabalhar por um período determinado em troca de remuneração.
- **Pena de reclusão**: Prisão perpétua ou por tempo determinado, dependendo da legislação penal aplicada.

### Referências legais
- Art. 4º, § 1º, Lei n.º 7.716/1989

### Dicas de prova
- Distinção entre a discriminação no emprego e a discriminação em outros contextos.
- Reconhecimento da vítima como pessoa física prejudicada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.210", "page_number": 210, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 4º, § 1º, Lei n.º 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:45:58.032730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=210", "doc_key": "2d043a9b43d30650b84e3c6ac20a8542"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '795a8d2967ec779f67ce26f91e7fb353c3ffb3346febc3af5096a2c22fcc533f'),
  ('cpiuris2025::2ae8bc46d8ef4d39cd15f140def7abe9', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acesso ao Estabelecimento Comercial', '## Acesso ao Estabelecimento Comercial

O crime prevê o recusar ou impedir acesso a estabelecimento comercial, negando-se a servir, atender ou receber cliente ou comprador, com pena de reclusão de um a três anos.

### Conceitos
- **Acesso ao Estabelecimento Comercial**: Proteger o tratamento igualitário nos estabelecimentos comerciais
- **Preconceito**: Conduita resultante de preconceito
- **Recusar**: Negativa em servir, atender ou receber cliente ou comprador
- **Impedir**: Obar ou proibir acesso ao estabelecimento comercial
- **Negar**: Repudiar a prestação de serviço

### Referências legais
- Art. 5º, § 2º da Lei nº 7.716/1989
- Súmula 395 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo de preconceito no trabalho

### Dicas de prova
- Distinção entre recusar e impedir
- Conhecimento da definição de preconceito
- Pena para o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.211", "page_number": 211, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5º, § 2º da Lei nº 7.716/1989", "Súmula 395 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo de preconceito no trabalho"], "confidence": 0.8, "extracted_at": "2026-05-31T21:46:15.157650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=211", "doc_key": "2ae8bc46d8ef4d39cd15f140def7abe9"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'e59819d6a1df545009ca1b7ecf22171876c4e82f43c27add13bf6a4fac3cbc24'),
  ('cpiuris2025::a73e0de994507e372e6aa372ed08db7d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Discriminação em Estabelecimento de Ensino', '## Crime de Discriminação em Estabelecimento de Ensino

O crime de discriminação em estabelecimento de ensino é definido como o ato de recusar, negar ou impedir a inscrição ou ingresso de um aluno, tutelando o direito à igualdade e ao acesso universal à educação.

### Conceitos
- **Bem jurídico**: direito à igualdade da pessoa ofendida
- **Sujeitos**: o crime é próprio e pode ser praticado por quem possui poderes específicos de recusar, negar ou impedir a inscrição ou ingresso de aluno em estabelecimento de ensino
- **Elementos do tipo**: verbos nucleares: recusar, negar e impedir; crime doloso, não há previsão de forma culposa
- **Consumação**: crime formal, consumando-se com a recusa, negação ou impedimento independente da obtenção do resultado

### Referências legais
- Art. 205 da Constituição Federal
- Parágrafo único do artigo 7º

### Dicas de prova
- Distinção entre o crime de discriminação em estabelecimento de ensino e outros crimes contra a igualdade
- Importância da preservação da igualdade dos seres humanos perante a lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.212", "page_number": 212, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 205 da Constituição Federal", "Parágrafo único do artigo 7º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:48:09.202584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=212", "doc_key": "a73e0de994507e372e6aa372ed08db7d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '16888de20ecd7809ce0042a139dc0580dc442ea42ba7f16166c25156be7805ce'),
  ('cpiuris2025::dc06a88f42cf8d07c6136f1ff41de403', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Discriminação em estabelecimentos esportivos e de lazer', '## Discriminação em estabelecimentos esportivos e de lazer

A lei proíbe a discriminação de pessoas em estabelecimentos esportivos, casas de diversão e clubes sociais, bem como em salões de cabeleireiros, barbearias, termas e casas de massagem.

### Conceitos
- **Discriminação**: Ação de distinguir ou separar pessoas com base em características pessoais, como raça, gênero, orientação sexual, etc.
- **Estabelecimento esportivo**: Local onde são realizadas atividades esportivas
- **Bem jurídico**: Direito ou interesse que é protegido pela lei
- **Sujeito passivo mediato**: O Estado, em seu papel de proteger os direitos e interesses das pessoas

### Referências legais
- Art. 7.716/1989

### Dicas de prova
- Reconheça a discriminação como o ''bem jurídico'' protegido pela lei
- Entenda que o crime é próprio e somente pode ser praticado por certas pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.214", "page_number": 214, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:48:33.375862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=214", "doc_key": "dc06a88f42cf8d07c6136f1ff41de403"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'd74bd4f08d633976664460e61db46fc1b92cbf118e547c68d0358ec4e49a584d'),
  ('cpiuris2025::493460aec87c0123aca53b7e0a4f4bd4', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acessibilidade em estabelecimentos comerciais', '## Acessibilidade em estabelecimentos comerciais

O crime de impedir o acesso ou recusar atendimento em restaurantes, bares, confeitarias e locais semelhantes abertos ao público é previsto no artigo 8º da Lei n.º 7.716/1989. O crime é doloso e não há previsão de forma culposa. A pena é reclusão de um a três anos.

### Conceitos
- **discriminação**: Ação de negar direitos ou benefícios a alguém com base em características pessoais
- **preconceito**: Atitude ou sentimento de desconfiança ou aversão injusta contra alguém por causa de características pessoais
- **crime doloso**: Crime cometido com intenção de causar dano a outrem
- **crime formal**: Crime que se consuma independentemente de qualquer outro resultado
- **sujeito passivo mediato**: O Estado, que é o sujeito que sofre o efeito do crime

### Referências legais
- Art. 8º da Lei n.º 7.716/1989

### Dicas de prova
- Pergunte se a discriminação é baseada em preconceito ou não
- Verifique se o crime é doloso ou culposo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.213", "page_number": 213, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 8º da Lei n.º 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:48:33.630428+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=213", "doc_key": "493460aec87c0123aca53b7e0a4f4bd4"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '6706a4e55f9a6d07b6ed81b18907b7864b35c3af5035c2f904fb8ee49cf05cc5'),
  ('cpiuris2025::5e563c26d9563a1465438d47d9aba64b', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Acesso à entrada ou elevador social', '## Acesso à entrada ou elevador social

Impedir o acesso às entradas sociais em edifícios públicos ou residenciais e elevadores ou escada de acesso, com pena de reclusão de um a três anos.

### Conceitos
- **doloso**: O crime é doloso, não havendo previsão de forma culposa.
- **consumação**: O crime é formal, consumando-se com a prática de um dos verbos descritos no tipo.
- **poderes**: Somente pode ser praticado por quem possui poderes de conferir acesso às entradas sociais.
- **discriminação**: Impedir o acesso por motivos discriminatórios, como raça, cor, etnia, religião ou procedência nacional.
- **sujeito passivo mediato**: O Estado é sujeito passivo mediato.
- **vítima**: A pessoa discriminada.
- **bem jurídico**: A preservação da igualdade dos seres humanos perante a lei.

### Referências legais
- Art. 11 da Lei nº 7.716/1989

### Dicas de prova
- Distinção entre impedir e obstar o acesso às entradas sociais.
- Importância de identificar os poderes conferidos ao sujeito que pratica o crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.215", "page_number": 215, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 11 da Lei nº 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:50:47.721399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=215", "doc_key": "5e563c26d9563a1465438d47d9aba64b"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'da38661cf44737c3925757fde82e54ae38c174defc67d69905e18b5463a69f87'),
  ('cpiuris2025::a85c93dcaac9fca6b1bf5674ce5d41b3', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Discriminação por raça, cor, etnia, religião ou procedência nacional', '## Discriminação por raça, cor, etnia, religião ou procedência nacional

O crime de discriminação ocorre com o impedimento ou a colocação de um obstáculo à vítima, independentemente do acesso ao serviço nas Forças Armadas.

### Conceitos
- **Consumação**: ocorre com o impedimento ou a colocação de um obstáculo à vítima
- **Dolo**: o crime é doloso, não há previsão de forma culposa
- **Sujeito passivo**: a pessoa discriminada
- **Bem jurídico**: a preservação da igualdade dos seres humanos perante a lei

### Referências legais
- Art. 14 da Lei nº 7.716/1989
- Súmula 343 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pense no caso do pai que impede o casamento da filha com outra pessoa pelo fato de esta ser negra
- A discriminação pode ocorrer em qualquer meio ou forma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.217", "page_number": 217, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 14 da Lei nº 7.716/1989", "Súmula 343 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T21:50:47.724376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=217", "doc_key": "a85c93dcaac9fca6b1bf5674ce5d41b3"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'ddf5201ab8520a9471359b80d0c875f5641826558b520ff99ab501fa46a05b89'),
  ('cpiuris2025::3ef6323fb2548657109e286b90061093', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Impedir ou obstar o acesso de alguém ao serviço em qualquer ramo das Forças Armadas', '## Impedir ou obstar o acesso de alguém ao serviço em qualquer ramo das Forças Armadas

Crime que impede ou obsta o acesso de alguém a um serviço militar, com pena de reclusão de dois a quatro anos.

### Conceitos
- **discriminação negativa**: direito à igualdade da pessoa ofendida em seu viés proibitório
- **crime doloso**: comportamento intencional e consciente que resulta em dano a alguém
- **impedir o acesso**: bloquear ou obstar a entrada de alguém em um serviço
- **uso de poder**: exercer autoridade para controlar o acesso a um serviço
- **vítima mediata**: o Estado, que é afetado pela ação criminosa
- **crime formal**: comportamento que resulta em dano e é caracterizado por uma intenção clara
- **reclusão**: pena de prisão perpétua ou de longo prazo
- **bem jurídico**: direito à igualdade da pessoa ofendida em seu viés proibitório

### Referências legais
- Art. 13 da Lei nº 7.716/1989

### Dicas de prova
- Perguntas sobre a definição de crime doloso e forma culposa
- Distinção entre impedir o acesso e obstar o uso de um serviço militar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.216", "page_number": 216, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 13 da Lei nº 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:51:27.702259+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=216", "doc_key": "3ef6323fb2548657109e286b90061093"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '20b56620b9fbe8969d939cb9fa1a369073548ae826836035d82cc2dabf056728'),
  ('cpiuris2025::2ddb67ed91919db24be9ad1b366e946d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Perda de Bens e Valores', '## Perda de Bens e Valores

Rege-se a perda de bens e valores equivalentes ao produto ou proveito do crime, quando não forem encontrados ou se localizarem no exterior. A perda pode ser requerida pelo Ministério Público, com indicação da diferença apurada.

### Conceitos
- **Patrimônio**: Todos os bens do condenado, incluindo aqueles de sua titularidade ou em relação aos quais ele tem domínio e benefício direto ou indireto.
- **Diferença Apurada**: A diferença entre o valor do patrimônio do condenado e aquele que é compatível com seu rendimento lícito.

### Referências legais
- Art. 91, § 1º, da Lei n.º 7.716/1989

### Dicas de prova
- Entenda a noção de patrimônio e diferença apurada para responder à pergunta.
- Reconheça a importância do Ministério Público na requerimento da perda de bens e valores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.218 (1)", "page_number": 218, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 91, § 1º, da Lei n.º 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:53:01.115697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=218", "doc_key": "2ddb67ed91919db24be9ad1b366e946d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '204e41ef805d91cca38a2ab90efd5be000cf51501e180cdce8bfbddb9da1517d'),
  ('cpiuris2025::046fffe34328f3c05becedbdb46b6117', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Discriminação genérica e propaganda nazista', '## Discriminação genérica e propaganda nazista

Artigo 20 estabelece pena para discriminação de raça, cor, etnia, religião ou procedência nacional, além de proibição de símbolos nazistas.

### Conceitos
- **Discriminação**: Ação de distinguir ou separar alguém ou algo com base em características
- **Preconceito**: Atitude de desconfiança ou aversão prévia a alguém ou algo
- **Propaganda**: Mensagem publicitada para influenciar opiniões ou comportamentos
- **Racismo**: Atitude de discriminação ou preconceito contra alguém com base em sua raça ou etnia
- **Nacionalismo**: Atitude de preferência por um país ou grupo nacional sobre outros
- **Símbolos**: Representações visuais usadas para expressar uma ideia ou conceito
- **Multidão**: Grande número de pessoas
- **Veicular**: Transportar algo por meio de um veículo

### Referências legais
- Art. 20 da Lei n. 7.716/89

### Dicas de prova
- Entenda a definição de discriminação e preconceito
- Identifique os tipos de propaganda proibidos
- Conheça as penas para o crime de racismo e nacionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.218 (2)", "page_number": 218, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20 da Lei n. 7.716/89"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:53:36.118962+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=218", "doc_key": "046fffe34328f3c05becedbdb46b6117"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'eb6bb14ac6fcd7bbd73a2c03024eea8b99838ae6600305cac0443e22670456b5'),
  ('cpiuris2025::d6f2890442af581673def818451602a7', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime contra a Sua Majestade', '## Crime contra a Sua Majestade

Regra que estabelece penas para crimes cometidos por meio de meios de comunicação social, publicação em redes sociais, entre outros, com aumento de pena se ocorrerem em contexto de atividades esportivas, religiosas, artísticas ou culturais.

### Conceitos
- **Crime contra a Sua Majestade**: Atitude que ofende a monarquia ou ao Estado
- **Meio de comunicação social**: Redes sociais, televisão, rádio, etc.
- **Publicação em redes sociais**: Compartilhamento de conteúdo em plataformas digitais
- **Atividades esportivas, religiosas, artísticas ou culturais**: Práticas que envolvem esporte, religião, arte ou cultura

### Referências legais
- Art. 2º da Lei nº 7.716/1989

### Dicas de prova
- Distinção entre crimes cometidos por meio de meios de comunicação social e outros
- Aumento de pena em casos de contexto de atividades esportivas, religiosas, artísticas ou culturais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.219 (1)", "page_number": 219, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º da Lei nº 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:53:43.444953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=219", "doc_key": "d6f2890442af581673def818451602a7"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '02fc5d87f6bfb0dcc26e8c61acb5088b4748c2c92742633faacbd0d45df72220'),
  ('cpiuris2025::d546bc340e362968c702a820f1f60b83', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crimes contra o Estado e a Coletividade', '## Crimes contra o Estado e a Coletividade

O crime é um ato que pode ser praticado por qualquer pessoa, com vítima a coletividade, e envolve a divulgação do nazismo.

### Conceitos
- **Crime Vago**: Ato que pode ser praticado por qualquer pessoa
- **Dolo Específico**: Necessidade de intenção para fins de divulgação do nazismo
- **Consumação do Crime**: Prática de quaisquer das condutas previstas no tipo

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de crime vago e dolo específico
- Identifique a forma qualificada do crime prevista no parágrafo 2º', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.220 (2)", "page_number": 220, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:55:14.583465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=220", "doc_key": "d546bc340e362968c702a820f1f60b83"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '09212e9f9060a5cd589ff19a0a1f0fa1afe8c494f6ea8d6a6a9b81545b56e7d8'),
  ('cpiuris2025::dbecfeaf94fc793770d1b2f668882d7d', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Racismo e Preconceito', '## Crime de Racismo e Preconceito

O crime previsto no artigo 20 visa proteger o tratamento igualitário, garantido como direito subjetivo a todos os cidadãos, independentemente da raça, cor, etnia, religião ou procedência nacional.

### Conceitos
- **Crime de Racismo**: Ato que visa discriminar ou preconceitar alguém com base na raça, cor, etnia, religião ou procedência nacional.
- **Tratamento Igualitário**: Direito subjetivo garantido a todos os cidadãos, independente de suas características pessoais.
- **Sujeito Passivo**: Grupo de pessoas que sofreu discriminação ou preconceito.
- **Crimes Dolosos**: Atos cometidos com intenção de causar dano a alguém.
- **Pena de Reclusão**: Média de prisão para atos que não envolvem morte ou lesão grave.

### Referências legais
- Art. 20 da Legislação Penal Especial

### Dicas de prova
- Distinção entre discriminação e preconceito
- Entendimento do termo ''tratamento igualitário'' como direito subjetivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.219 (2)", "page_number": 219, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20 da Legislação Penal Especial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:55:34.300147+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=219", "doc_key": "dbecfeaf94fc793770d1b2f668882d7d"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '3de4e27ad16c946a074342096a0fd3565456af554b69c2676f40ec4a00189a33'),
  ('cpiuris2025::e2b239e25416dc67c70ce847ed30338a', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Proteção das manifestações religiosas e crimes contra a liberdade de expressão', '## Proteção das manifestações religiosas e crimes contra a liberdade de expressão

O artigo 20 da Lei n. 7.716/89 estabelece crime contra a liberdade de expressão, especialmente quando se trata de manifestações religiosas, e prevê penas de reclusão e multa.

### Conceitos
- **Propaganda**: Ação de promover uma ideologia ou doutrina
- **Liberdade de expressão**: Direito à liberdade de pensamento, consciência e comunicação
- **Manifestações religiosas**: Expressões de fé ou crença em um grupo ou indivíduo
- **Crimes contra a liberdade de expressão**: Ações que restringem ou limitam a liberdade de expressão

### Referências legais
- Art. 20 da Lei n. 7.716/89

### Dicas de prova
- Diferenciar entre propaganda e manifestações religiosas
- Entender a importância da liberdade de expressão e seus limites', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.220 (1)", "page_number": 220, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20 da Lei n. 7.716/89"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:55:43.572223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=220", "doc_key": "e2b239e25416dc67c70ce847ed30338a"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '540edb43b34ab8d923f4d6ac101cb32f80da3245e830b755c8280ecbcea8fddc'),
  ('cpiuris2025::0f1e553674038e17c1c2bc905552572e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Crime de Racismo', '## Crime de Racismo

Rege-se o crime de racismo com base na Lei n. 7.716/89, que proíbe atitudes discriminatórias contra minoritários, incluindo a publicação de livros anti-semitas e a exposição indevida de pessoas ou grupos.

### Conceitos
- **Crime de Racismo**: Atitude discriminatória contra minoritários
- **Lei n. 7.716/89**: Rege o crime de racismo e proíbe atitudes discriminatórias
- **Imprescritibilidade**: Característica do crime de racismo, que não pode ser prescrito
- **Inafiançabilidade**: Característica do crime de racismo, que impede a fiança
- **Discriminação**: Atitude ou tratamento dado à pessoa ou grupo minoritário
- **Preconceito**: Atitude negativa em relação a um grupo minoritário
- **Libertade de Expressão**: Direito à liberdade de expressar opiniões e ideias
- **Limites da Libertade de Expressão**: Regras que limitam a liberdade de expressão para evitar danos ou ofensas

### Referências legais
- Art. 20-A, Lei n. 14.532/23
- Art. 20-C, Lei n. 14.532/23
- Art. 20-D, Lei n. 14.532/23

### Jurisprudência
- RE 123456
- Tema repetitivo: Crime de Racismo e Imprescritibilidade

### Dicas de prova
- Entenda a definição do crime de racismo e suas implicações legais
- Conheça as regras que limitam a liberdade de expressão para evitar danos ou ofensas
- Aprenda a distinguir entre discriminação e preconceito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20-A, Lei n. 14.532/23", "Art. 20-C, Lei n. 14.532/23", "Art. 20-D, Lei n. 14.532/23"], "jurisprudence": ["RE 123456", "Tema repetitivo: Crime de Racismo e Imprescritibilidade"], "confidence": 0.8, "extracted_at": "2026-05-31T21:56:36.046434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=221", "doc_key": "0f1e553674038e17c1c2bc905552572e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '52e3c80bcbbe4f5d247a55a62bcdfb4c07a58a96bfeff1b1ee23bb159ffb4b9f'),
  ('cpiuris2025::60f7d9830085cf096a402bda831d8c86', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Imprescritibilidade e Prática de Racismo', '## Imprescritibilidade e Prática de Racismo

A imprescritibilidade dos crimes de racismo é questionada, com a questão se os atos repulsivos do passado devem ser lembrados para garantir a prevalência dos direitos humanos.

### Conceitos
- **Imprescritibilidade**: Tempo jurídico que se escoa sem encontrar termo
- **Prática de Racismo**: Ato discriminatório com base em raciais
- **Direitos Humanos**: Garantias fundamentais da dignidade humana

### Referências legais
- Art. 15, Lei nº 9.455/1997

### Jurisprudência
- RE 123456
- HC 82424/STF

### Dicas de prova
- Entenda a noção de imprescritibilidade e sua aplicação aos crimes de racismo.
- Análise da relação entre a memória histórica e a justiça penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.222 (2)", "page_number": 222, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 15, Lei nº 9.455/1997"], "jurisprudence": ["RE 123456", "HC 82424/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T21:58:44.872720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=222", "doc_key": "60f7d9830085cf096a402bda831d8c86"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', 'eb3f4574f14d7781a7a8515c4f02fbfa56873743eafb3871bd37e60dad29e724'),
  ('cpiuris2025::84dfa8911339d62f633c841f052ad087', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Punições por racismo e discriminação', '## Punições por racismo e discriminação

A lei estabelece punições para delitos que estimulem e propaguem segregação racial, incluindo a incitação ao racismo e a discriminação contra grupos humanos.

### Conceitos
- **Racismo**: Prática de segregação racial
- **Discriminação**: Ato ilícito que visa prejudicar um grupo humano
- **Incitação ao racismo**: Manifestações que buscam resgatar e dar credibilidade à concepção racial definida pelo regime nazista
- **Liberdade de expressão**: Garantia constitucional que não é absoluta e deve ser exercida com limites morais e jurídicos

### Referências legais
- Art. 151 da Lei nº 7.716/1989

### Dicas de prova
- Entenda a distinção entre liberdade de expressão e limites morais e jurídicos
- Conheça as punições para delitos que estimulem e propaguem segregação racial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 151 da Lei nº 7.716/1989"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T21:59:08.155478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=222", "doc_key": "84dfa8911339d62f633c841f052ad087"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '7ca87fa41c87c4198b569b367ef3f1a29f7da5102db339cc5e32a9a3303950b5'),
  ('cpiuris2025::14eb0dd8fac1962e9c334fa3a1977aa8', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Racismo e Discriminação', '## Racismo e Discriminação

O texto destaca a gravidade do racismo e discriminação, destacando a necessidade de combater essas práticas com clareza e firmeza, em consonância com os princípios da Constituição Federal de 1988.

### Conceitos
- **Racismo**: Prática que distingue indivíduos por restrições ou preferências oriundas de raça, cor, credo, descendência ou origem nacional ou étnica
- **Discriminação**: Ação de tratar pessoas de maneira diferente com base em características como raça, cor, religião, sexo, idade etc.
- **Imprescritibilidade**: Cláusula constitucional que impede a prescrição dos crimes raciais e discriminatórios
- **Abjeção**: Condenação pública à solidão e isolamento, devido a atos considerados criminosos
- **Xenofobia**: Prejuízo ou aversão contra pessoas estrangeiras
- **Negrofobia**: Prejuízo ou aversão contra pessoas negras
- **Islamofobia**: Prejuízo ou aversão contra muçulmanos
- **Anti-semitismo**: Prejuízo ou aversão contra judeus

### Referências legais
- Art. 5 da Constituição Federal de 1988

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição jurídica do racismo e sua abrangência
- Conheça as cláusulas constitucionais que combatem a discriminação e o racismo
- Identifique os exemplos de xenofobia, negrofobia, islamofobia e anti-semitismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 5 da Constituição Federal de 1988"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:00:07.902719+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=221", "doc_key": "14eb0dd8fac1962e9c334fa3a1977aa8"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '709365289cc0e24bd108ef6829c6e5a95f2bc0c6aeb4c889dc7c08b26b18cb87'),
  ('cpiuris2025::d0ff8f4ba0605be7ef8596dc5de0b68e', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Incitação ao Preconceito Racial', '## Incitação ao Preconceito Racial

A decisão do Julgador não há ilegalidade na condenação do paciente por racismo, pois a incitação ao preconceito racial é crime formal e não se exige a realização do resultado material para sua configuração.

### Conceitos
- **Incitação**: Ação que provoca ou estimula a discriminação ou preconceito racial
- **Dolo**: Conhecimento pelo agente de que suas ações podem causar um resultado prejudicial
- **Crime Formal**: Ato que caracteriza crime sem a necessidade da realização do resultado material
- **Tipicidade Direta**: Configuração do delito com base na conduta do agente

### Referências legais
- Art. 20 da Lei nº 7.716/89

### Jurisprudência
- Súmula 07/STJ

### Dicas de prova
- Distinção entre incitação e induzimento
- Importância do dolo na configuração do delito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 20 da Lei nº 7.716/89"], "jurisprudence": ["Súmula 07/STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T22:00:55.417615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=223", "doc_key": "d0ff8f4ba0605be7ef8596dc5de0b68e"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '9bab8bd5f66bac7fb57dd24bf2b1a1b5c662aacf2227b840f15d871762efe848'),
  ('cpiuris2025::95cbded35dd8235cae9ecd05b3e68aa9', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Conflito Negativo de Competência', '## Conflito Negativo de Competência

O juiz nega seguimento a pedido e arquiva os autos, considerando que o caso é de competência da Justiça Federal, devido à natureza do crime previsto na Lei nº 7.716/89.

### Conceitos
- **Conflito Negativo de Competência**: Ocorre quando um juiz não tem competência para julgar uma ação ou processo, devido à natureza do crime ou da causa.
- **Competência Federal**: A competência da Justiça Federal é determinada pela Constituição e se refere a crimes previstos em tratados ou convenções internacionais.
- **Art. 105, inciso I, alínea d da Constituição Federal**: Determina que os juízes federais têm competência para julgar os crimes previstos em tratados ou convenções internacionais.
- **Art. 109, V, da Constituição Federal**: Estabelece que a Justiça Federal tem competência para processar e julgar crimes previstos em tratados ou convenções internacionais.

### Referências legais
- Art. 20, § 2º, DA LEI 7.716/89
- Art. 105, inciso I, alínea d da Constituição Federal
- Art. 109, V, da Constituição Federal

### Jurisprudência
- 19 STJ, HC 15.155
- 20 STJ, REsp 157.805
- 21 STF, Pet 8776

### Dicas de prova
- Distinção entre conflito negativo e positivo de competência
- Importância da natureza do crime previsto na Lei nº 7.716/89
