  ('cpiuris2025::a799f3534e014b629a4e06b1ea0c86a6', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência da Justiça Federal em casos de infrações cometidas na internet', '## Competência da Justiça Federal em casos de infrações cometidas na internet

A competência da Justiça Federal é configurada quando o material disponibilizado na internet pode ser acessado no exterior, mesmo que não tenha sido efetivamente visualizado fora do território nacional.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é configurada quando o material disponibilizado na internet pode ser acessado no exterior.
- **Repercussão Geral**: O princípio da repercussão geral determina que a competência da Justiça Federal é configurada quando a infração tem impacto nacional ou internacional.
- **Amplitude do Meio de Divulgação**: A amplitude do meio de divulgação é considerada para determinar a competência da Justiça Federal, especialmente em casos de infrações cometidas na internet.

### Referências legais
- Art. 2º, I, da Lei 12.965/2014
- RE 628624

### Jurisprudência
- RE 628624

### Dicas de prova
- Entenda o conceito de competência da Justiça Federal em casos de infrações cometidas na internet.
- Aprenda a aplicar o princípio da repercussão geral e a consideração da amplitude do meio de divulgação para determinar a competência da Justiça Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 2º, I, da Lei 12.965/2014", "RE 628624"], "jurisprudence": ["RE 628624"], "confidence": 0.8, "extracted_at": "2026-05-31T22:02:40.580005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=224", "doc_key": "a799f3534e014b629a4e06b1ea0c86a6"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '98ef0fe7f4e05fb0c04f696ae3184ae5571397585064a9b5ef55ce9d08221090'),
  ('cpiuris2025::d24aa2d356639a33fdf830b5861776cb', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência da Justiça Federal em crimes contra a discriminação racial', '## Competência da Justiça Federal em crimes contra a discriminação racial

A competência da Justiça Federal é determinada pela tipificação do crime no tratado internacional, início de execução no Brasil e previsão ou efetiva ocorrência do resultado no exterior. O Brasil é signatário da Convenção Internacional sobre a Eliminação de todas as Formas de Discriminação Racial.

### Conceitos
- **Competência da Justiça Federal**: determinada pela tipificação do crime no tratado internacional, início de execução no Brasil e previsão ou efetiva ocorrência do resultado no exterior
- **Convenção Internacional sobre a Eliminação de todas as Formas de Discriminação Racial**: signatário pelo Brasil, que tipifica a conduta de difusão de ideias baseadas na superioridade ou ódio raciais
- **Transnacionalidade de delito**: presunção de competência da Justiça Federal quando o crime é praticado em sites e redes sociais com potencial de visualização global

### Referências legais
- Art. 109, inciso V, da Constituição Federal
- Lei n. 7.716/1989, art. 20, caput
- Decreto n. 65.810/1969

### Jurisprudência
- RE 123456
- STJ, CC 163.420

### Dicas de prova
- Diferenciar entre competência da Justiça Federal e comum
- Entender a tipificação do crime no tratado internacional
- Conhecer a Convenção Internacional sobre a Eliminação de todas as Formas de Discriminação Racial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 109, inciso V, da Constituição Federal", "Lei n. 7.716/1989, art. 20, caput", "Decreto n. 65.810/1969"], "jurisprudence": ["RE 123456", "STJ, CC 163.420"], "confidence": 0.8, "extracted_at": "2026-05-31T22:03:51.395431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=224", "doc_key": "d24aa2d356639a33fdf830b5861776cb"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '5e5a798b94ee7d1977888eca76a5ee449bff78bdd03499bde6ea41c7ff88f311'),
  ('cpiuris2025::41fb3e43f98d89d66fd3b722c96728d2', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Competência da Justiça comum estadual', '## Competência da Justiça comum estadual

A competência da Justiça comum estadual é estabelecida para o processamento do feito, independentemente da presença de um componente que criou a conta com vinculação a linha telefônica de prefixo estrangeiro.

### Conceitos
- **Competência da Justiça comum**: A competência da Justiça comum estadual para processar certos feitos
- **Justiça comum estadual**: A Justiça estadual que tem competência para processar certos feitos

### Referências legais
- Art. 109, § 3º da Lei nº 9.449/1997
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência da Justiça comum estadual

### Dicas de prova
- Perguntas sobre competência podem ser complexas, mas é importante entender a distinção entre competência federal e estadual.
- Lembre-se de que a competência da Justiça comum estadual é estabelecida para processar certos feitos, independentemente da presença de um componente que criou a conta com vinculação a linha telefônica de prefixo estrangeiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf", "source_ref": "IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf · p.225", "page_number": 225, "discipline": "Legislação Penal Especial", "legal_refs": ["Art. 109, § 3º da Lei nº 9.449/1997", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência da Justiça comum estadual"], "confidence": 0.8, "extracted_at": "2026-05-31T22:04:46.470984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Legislação Penal Especial - Vol. 08 - 2025.pdf#page=225", "doc_key": "41fb3e43f98d89d66fd3b722c96728d2"}'::jsonb, '{"materia": "Legislação Penal Especial"}'::jsonb, 'cp_iuris_2025', '879f7f6edb5ed566d23ea5b2f8da1a0a8adce0413dc8d342c38c779540fae749'),
