  ('cpiuris2025::73c4609f20277478c4dd8d289117b9fc', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Definição do Processo Coletivo e Litigio Estrutural', '## Definição do Processo Coletivo e Litigio Estrutural

O Processo Coletivo e Litigio Estrutural é um conceito jurídico que se refere a uma forma de procedimento processual em que as partes envolvidas não estão necessariamente presentes na audiência, mas sim representadas por advogados ou procuradores.

### Conceitos
- **Processo Coletivo**: procedimento processual em que as partes não estão presentes na audiência
- **Litigio Estrutural**: formas de procedimento processual em que as partes não estão necessariamente presentes na audiência

### Referências legais
- Art. X da Lei Y

