  ('cpiuris2025::350d198a4f57a26cc3ddea0a843ad624', 'doutrina', 'cp_iuris', 'Legislação Penal Especial — Portaria n.º 130/MF e Recursos Ordinários Conconstitucionais', '## Portaria n.º 130/MF e Recursos Ordinários Conconstitucionais

Resumo de Portaria n.º 130/MF e lista de recursos ordinários constitucionais apresentados à STJ, STF e outros tribunais.

### Conceitos
- **Portaria n.º 130/MF**: Ordem ministerial que regula os recursos ordinários constitucionais
- **RECURSO ORDINÁRIO CONSTITUCIONAL**: Recursos apresentados à STJ, STF e outros tribunais para revisão de decisões constitucionais
- **RECURSOS ESPECIAIS**: Recursos apresentados por parte das partes em um processo específico
- **RECURSOS EXTRAORDINÁRIOS**: Recursos apresentados para revisão de decisões do tribunal
- **RESOLUÇÕES**: Decisões tomadas pelo tribunal após a análise dos recursos
- **SÚMULAS**: Opiniões emitidas pela STJ e STF sobre questões jurídicas

