- **Professora de Direito Processual Civil/Processo Coletivo**: Pessoa que ensina Direito Processual Civil e Processo Coletivo
- **Especialista em Direito Processual Civil e em Ciências Criminais**: Pessoa com conhecimento especializado em Direito Processual Civil e Ciências Criminais
- **Membro da Associação Brasileira Elas no Processo (ABEP)**: Pessoa que faz parte de uma organização que promove a igualdade de gênero no direito
- **Idealizadora da Plataforma Treine Subjetivas**: Pessoa que criou uma plataforma para treinamento em Direito Processual Civil

