  ('cpiuris2025::6781c071cd762fdb778edee5f0851e1a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência', '## Competência

Discute a competência para propositura de ações, abordando as regras que regem o cabimento das demandas.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar uma causa
- **Legitimidade**: O direito de alguém para propor uma ação
- **Litisconsórcio**: A relação entre as partes que se apresentam como litigantes em um mesmo processo
- **Intervenção de terceiros**: A participação de terceiros no processo, com ou sem autorização do juiz

### Referências legais
- Art. 109 da Código de Processo Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
