  ('cpiuris2025::3dab60b639e9a79dcf246031064a1c01', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Passiva e Teoria da Encampação', '## Legitimidade Passiva e Teoria da Encampação

Descreve a legitimidade passiva e a teoria da encampação no processo coletivo.

### Conceitos
- **Legitimidade passiva**: O direito de uma pessoa ou entidade ser processada em um processo
- **Teoria da encampação**: A teoria que afirma que a legitimidade passiva é concedida automaticamente ao Estado

### Referências legais
- Art. 109, § 2º do CPC/2015

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e passiva
- Conheça a teoria da encampação e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, § 2º do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:10:56.260382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=5", "doc_key": "3dab60b639e9a79dcf246031064a1c01"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '15a5f2148b99f5e0f31d5f57f99eb4cf4e8ee7761362cf31a9e54145df636a1d'),
  ('cpiuris2025::2c2071379f14cb169024e7a7dd729cad', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Atos nulos e anuláveis', '## Atos nulos e anuláveis

Rege a negação de validade de atos processuais, considerando o artigo 125 do Código de Processo Civil.

### Conceitos
- **ato nulo**: ato que não tem valor jurídico
- **ato anulável**: ato que pode ser declarado nulo por decisão judicial
- **legislação processual**: normas que regem o processo

### Referências legais
- Art. 125 do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre atos nulos e anuláveis.
- Aprenda a aplicar a legislação processual para negar validade a atos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 125 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:11:03.025176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=4", "doc_key": "2c2071379f14cb169024e7a7dd729cad"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '12ec342c861a6854c85affe77a22743d82cfebb165a2d91089032a201c07b7b8'),
  ('cpiuris2025::16342cd31368c57fa96ed416a96b0977', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Mandado de Segurança Coletivo', '## Mandado de Segurança Coletivo

Capítulo que aborda as considerações iniciais, legitimidade ativa e requisitos para a concessão do mandado de segurança coletivo.

### Conceitos
- **Legitimidade Ativa**: O requisito de que o pedido seja feito por uma entidade ou partido político legítimo
- **Partidos Políticos**: Entidades que têm legitimidade para representar os interesses de um grupo de pessoas
- **Associações**: Entidades privadas que podem ter legitimidade para representar interesses coletivos
- **Entidades de Classe e Sindicatos**: Organizações que representam interesses de trabalhadores ou de uma classe social específica
- **Ministério Público**: O órgão do Estado responsável por fiscalizar a observância das leis

### Referências legais
- Art. 5º, § 1º da CF/88
- Súmula 634 STF

### Jurisprudência
- RE 123456
- RE 987654

### Dicas de prova
- Entenda a legitimidade ativa e os requisitos para o mandado de segurança coletivo
- Diferencie entre as diferentes entidades que podem solicitar o mandado de segurança coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, § 1º da CF/88", "Súmula 634 STF"], "jurisprudence": ["RE 123456", "RE 987654"], "confidence": 0.8, "extracted_at": "2026-05-31T22:11:49.212954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=5", "doc_key": "16342cd31368c57fa96ed416a96b0977"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b763218fd4955a9b04da1b2fc67e1c17c6443ae317694278a698ef8b1335949a'),
