  ('cpiuris2025::836fbcfba078cefa686f8ede9a836cb4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência', '## Competência

Discute a competência nos processos, destacando as teorias não concretista e concretista.

### Conceitos
- **Teoria não concretista**: Teoria que afirma que a competência é relativa ao objeto do processo
- **Teoria concretista**: Teoria que afirma que a competência é relativa à pessoa do litigante
- **Competência**: Condição necessária para que um juiz possa proferir uma sentença

### Referências legais
- Art. 109 da Código de Processo Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência nos processos

### Dicas de prova
- Entenda a diferença entre as teorias não concretista e concretista de competência
- Conheça os requisitos para que um juiz possa proferir uma sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109 da Código de Processo Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência nos processos"], "confidence": 0.8, "extracted_at": "2026-05-31T22:12:45.147532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=5", "doc_key": "836fbcfba078cefa686f8ede9a836cb4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '0f7d37e7afde65cbfbb80a4c0b5fdc4e74f67ffc2bd5c33d0d7554fb1d6569e9'),
