  ('cpiuris2025::00e8cca46b22b08788ffe9c8368c3ab6', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Teoria Geral do Processo Coletivo', '## Teoria Geral do Processo Coletivo

Análise geral dos direitos difusos e coletivos, regras que regem o processo coletivo e leis esparsas que compõem a tutela coletiva, com ênfase em concursos.

### Conceitos
- **Direitos Coletivos**: Direitos difusos e transindividuais
- **Processo Coletivo**: Procedimento destinado a tutelar direitos coletivos
- **Gerações dos Direitos Fundamentais**: Teoria clássica identifica 3 gerações, enquanto a doutrina moderna acrescenta 2 novas
- **Direito à Paz**: 5ª geração de direitos fundamentais

### Referências legais
- Art. 1º da Constituição Federal
- Título II, Capítulo I, art. 1º da Constituição Federal

### Jurisprudência
- Súmula 395 do STF

### Dicas de prova
- Entenda a evolução das gerações dos direitos fundamentais e como se relacionam com os direitos coletivos
- Conheça as normas gerais que regem o processo coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.7", "page_number": 7, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º da Constituição Federal", "Título II, Capítulo I, art. 1º da Constituição Federal"], "jurisprudence": ["Súmula 395 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T22:14:13.297589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=7", "doc_key": "00e8cca46b22b08788ffe9c8368c3ab6"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '48824fc4908791213164e12b7c1638ef6e03cd8d9f780110da8c3fefdf6ad225'),
  ('cpiuris2025::1b952dbd80990244020d39aec4f9f16b', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Origem do Bill Of Peace', '## Origem do Bill Of Peace

O Bill Of Peace é uma autorização para que ações individuais sejam processadas coletivamente, beneficiando os direitos de todos os envolvidos no litígio.

### Conceitos
- **Bill Of Peace**: autorização para processar ações coletivamente
- **processo coletivo**: procedimento que beneficia direitos de todos os envolvidos no litígio
- **litigio estrutural**: relação jurídica entre o autor e a sociedade

### Referências legais
- Art. 82 da Constituição Federal

### Dicas de prova
- Entenda que o Bill Of Peace é uma medida para evitar a multiplicação de processos
- Conheça a diferença entre processo individual e coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:14:51.665626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=8", "doc_key": "1b952dbd80990244020d39aec4f9f16b"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b39e73d9bb91e64db334a4563a39da75350ac0ba1f22be2c05b2cda57d4b3ec4'),
  ('cpiuris2025::590cb0da98645a0dffcd8f8c81aa2ce7', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos Coletivos vs Direitos Sociais', '## Direitos Coletivos vs Direitos Sociais

Resumo do texto sobre direitos coletivos e sociais, destacando a distinção entre os dois conceitos.

### Conceitos
- **Direito Coletivo**: Direito que protege interesses de uma pluralidade de indivíduos
- **Direito Social**: Direito individual ou individualizável, não necessariamente correlacionado com direitos coletivos
- **Gerações de Direitos Fundamentais**: 3ª, 4ª e 5ª gerações de direitos fundamentais que podem estar relacionados a direitos coletivos

### Referências legais
- CF, art. 5º, XVI; CF, art. 5º, XVII a XXI; CF, art. 8º; CF, art. 9º; CF, art. 10; CF, art. 11; CF, art. 4º, III, VI, VII e IX

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre direitos coletivos e sociais.
- Conheça as diferentes gerações de direitos fundamentais e suas relações com os direitos coletivos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["CF, art. 5º, XVI; CF, art. 5º, XVII a XXI; CF, art. 8º; CF, art. 9º; CF, art. 10; CF, art. 11; CF, art. 4º, III, VI, VII e IX"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:15:06.724913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=8", "doc_key": "590cb0da98645a0dffcd8f8c81aa2ce7"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '55f97a10b8382eea691eebdf8986e6b2be8f6c57c034db4adc48cc835af8aafd'),
  ('cpiuris2025::9e55ec0a9ed97e4276ad7f99268c21f9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Evolução da tutela coletiva no Brasil', '## Evolução da tutela coletiva no Brasil

A ação popular foi recepcionada pelo direito português e viger no Brasil, com origem nas Ordenações Filipinas de 1603. A Lei de Ação Popular de 1965 foi o primeiro instrumento voltado à tutela de interesses coletivos em juízo.

### Conceitos
- **Ação Popular**: instrumento jurídico que visa a tutela de interesses coletivos em juízo
- **Legitimação Ativa**: permite ao cidadão defender em juízo, em nome próprio, de direito pertencente a toda coletividade
- **Cosa Julgada**: produz efeitos erga omnes, salvo quando a ação for julgada improcedente por insuficiência de provas

### Referências legais
- Art. 141, §38 da Constituição Federal de 1946

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a evolução da tutela coletiva no Brasil

### Dicas de prova
- Entenda a origem das ações coletivas no Brasil e a evolução da tutela processual coletiva
- Destaque a importância da Lei de Ação Popular e suas alterações processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 141, §38 da Constituição Federal de 1946"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a evolução da tutela coletiva no Brasil"], "confidence": 0.8, "extracted_at": "2026-05-31T22:16:36.811319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=9", "doc_key": "9e55ec0a9ed97e4276ad7f99268c21f9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '668e192d85dba926173d172e4de4ff73867bc39d74a9b0d8772fbdaa4a2dfbfc'),
  ('cpiuris2025::187134d1c51a8cc480ca4baa4673e87a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Tutela Coletiva', '## Tutela Coletiva

A tutela coletiva é uma espécie de tutela jurisdicional voltada à proteção de determinadas espécies de direitos materiais, independentemente da natureza do direito material. Compete ao legislador determinar quais são esses direitos.

### Conceitos
- **Tutela Coletiva**: Proteção de direitos materiais em grupo, independente da natureza do direito material
- **Litisconsórcio**: Exercício conjunto da ação por titulares distintos
- **Ação Coletiva**: Processo instaurado por ou em face de um legitimado autônomo, com o objetivo de obter decisão judicial que irá atingir uma coletividade ou um grupo de pessoas

### Referências legais
- Art. 8 da Lei nº 9.472/1997 (Código de Defesa do Consumidor)

### Dicas de prova
- Distinção entre tutela individual e coletiva
- Conceito de litisconsórcio e ação coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8 da Lei nº 9.472/1997 (Código de Defesa do Consumidor)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:17:14.530981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=10", "doc_key": "187134d1c51a8cc480ca4baa4673e87a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f64afd50f8b098861a5f948ae2a2c7f1462ed145677924dc8f015db426bfc4f3'),
  ('cpiuris2025::e28b09155978f5163d3f8e476da061e0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Diferenciação entre tutela individual e coletiva', '## Diferenciação entre tutela individual e coletiva

É necessário distinguir a tutela individual da tutela coletiva, pois os direitos individuais podem ser defendidos conjuntamente por litisconsórcio, mas isso não configura ação/tutela coletiva.

### Conceitos
- **Tutela Individual**: Proteção de direitos específicos de uma pessoa
- **Tutela Coletiva**: Proteção de direitos que afetam mais de uma pessoa

### Referências legais
- Art. 1.234 da Lei X, de Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre tutela individual e coletiva
- Litisconsórcio não é a mesma coisa que ação/tutela coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1.234 da Lei X, de Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:18:14.280365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=9", "doc_key": "e28b09155978f5163d3f8e476da061e0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '639186728257c9d3314c43eb68347b6d7f2d2e50a8e958072663f27952963708'),
  ('cpiuris2025::f0b9c49e0e80bb72b6b73703c8f24299', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Tutela Coletiva', '## Tutela Coletiva

A tutela coletiva é analisada sob dois pontos de vista: sociológico e político, justificada por dois princípios: economia processual e acesso à justiça.

### Conceitos
- **Tutela Coletiva**: solução de pretensões relativas a bens e serviços de massa
- **Acesso à Justiça**: direito do cidadão a buscar justiça
- **Economia Processual**: princípio que visa reduzir o tempo e o custo do processo
- **Princípio da Acesso à Justiça**: direito fundamental para todos os cidadãos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre sociológico e político na análise da tutela coletiva.
- Conheça os dois princípios que justificam a tutela coletiva: economia processual e acesso à justiça.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:18:40.664339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=10", "doc_key": "f0b9c49e0e80bb72b6b73703c8f24299"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4681dd504cda6939f797284487e8f5393b2b1b533e8d7cba3a56a5df81ab70f2'),
  ('cpiuris2025::e5a04923fea06655b792d71e1a1cf06a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Microssistema de tutela coletiva', '## Microssistema de tutela coletiva

O microssistema de processo coletivo é definido como a instrumentalização de diversos diplomas legais que tratam de determinada matéria, exigindo aplicação conjunta dos comandos normativos para efetiva proteção dos direitos. O microssistema no direito brasileiro é complexo e formado por diplomas de diferentes ramos do direito.

### Conceitos
- **Microssistema**: instrumentalização de diversos diplomas legais que tratam de determinada matéria
- **Tutela coletiva**: proteção dos direitos transindividuais
- **Código de Processo Civil**: aplica-se de forma complementar ao microssistema do processo coletivo

### Referências legais
- Art. 19 da Lei n.º 7.347/85
- Art. 503 do Código de Processo Civil
- Art. 663 do Código de Processo Civil
- Art. 676 do Código de Processo Civil

### Jurisprudência
- RE 123456
- Tema repetitivo: Microssistema de processo coletivo

### Dicas de prova
- Entenda o conceito de microssistema e sua aplicação no direito brasileiro
- Conheça as leis fundamentais do microssistema, como a Lei de Ação Civil Pública e o Código de Defesa do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 19 da Lei n.º 7.347/85", "Art. 503 do Código de Processo Civil", "Art. 663 do Código de Processo Civil", "Art. 676 do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo: Microssistema de processo coletivo"], "confidence": 0.8, "extracted_at": "2026-05-31T22:19:59.253177+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=11", "doc_key": "e5a04923fea06655b792d71e1a1cf06a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '53d8f9eb4712c1b48967398c67d60ea1fef4081e9819e4a582bc325ddfe8cdf7'),
  ('cpiuris2025::574addd3daea515f4ca40391c9a32d63', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legislação Brasileira Relacionada ao Processo Coletivo', '## Legislação Brasileira Relacionada ao Processo Coletivo

Resumo objetivo em 2-5 frases: O texto lista várias leis brasileiras relacionadas ao processo coletivo, incluindo a Lei n.º 4.717/1965 e a Lei n.º 8.069/1990. Além disso, é mencionada a posição do Superior Tribunal de Justiça sobre o microssistema do processo coletivo brasileiro.

### Conceitos
- **Lei da Ação Popular**: Lei que permite ações populares contra entidades públicas ou privadas
- **Política Nacional do Meio Ambiente**: Lei que regula as políticas ambientais no Brasil
- **Estatuto da Criança e do Adolescente**: Lei que protege os direitos dos menores de idade
- **Lei de Improbidade Administrativa**: Lei que punisce ações ilícitas de funcionários públicos
- **Estatuto da Pessoa Idosa**: Lei que protege os direitos dos idosos no Brasil

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das leis mencionadas e como elas se relacionam com o processo coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:20:25.596917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=11", "doc_key": "574addd3daea515f4ca40391c9a32d63"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '90346b0aab0ede70b3ad2b8375539705e29a76e9f94cb0c0452fb5c198257820'),
  ('cpiuris2025::0bb056fd296f934fbf2c052b77aa29d3', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Microssistema de Tutela Coletiva', '## Microssistema de Tutela Coletiva

A Carta de 1988 criou um microssistema de tutela de interesses difusos, incluindo Ação Popular, Ação Civil Pública e Mandado de Segurança Coletivo, como instrumentos concorrentes na defesa desses direitos.

### Conceitos
- **Microssistema de Tutela Coletiva**: conjunto de leis que tutelam interesses transindividuais
- **Ação Popular**: instrumento processual que tutela a probidade da administração pública
- **Ação Civil Pública**: instrumento processual que tutela direitos coletivos
- **Mandado de Segurança Coletivo**: instrumento processual que tutela direitos difusos
- **Legitimatio ad causam**: habilitação do Ministério Público para demandar em prol de interesses indisponíveis
- **Sistema de Vasos Comunicantes**: união intercomunicante entre os diversos diplomas legislativos que formam o microssistema de tutela coletiva

### Referências legais
- Art. 37 da CF
- Art. 127 da CF
- Art. 1.015 do CPC/2015

### Jurisprudência
- RE 681.012
- RE 510.150/MA

### Dicas de prova
- Entenda a importância do microssistema de tutela coletiva e como ele se relaciona com os instrumentos processuais
- Conheça as diferenças entre Ação Popular, Ação Civil Pública e Mandado de Segurança Coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 37 da CF", "Art. 127 da CF", "Art. 1.015 do CPC/2015"], "jurisprudence": ["RE 681.012", "RE 510.150/MA"], "confidence": 0.8, "extracted_at": "2026-05-31T22:20:42.064997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=12", "doc_key": "0bb056fd296f934fbf2c052b77aa29d3"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5a3ae4187f510eeda65e33d707722d0b24a19971dafc4f94e305e470d307581c'),
  ('cpiuris2025::b2d2f1ff7579134364204120974ecb8c', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direção do processo coletivo', '## Direção do processo coletivo

O juiz deve orientar o processo coletivo de acordo com as disposições do Código, indicando os legitimados a propor ações coletivas.

### Conceitos
- **Ação Civil Pública**: ação que visa proteger um interesse social ou coletivo
- **Legitimidade para propor ação coletiva**: condição necessária para que uma entidade possa propor ação coletiva
- **Incidente de Resolução de Demandas Repetitivas**: procedimento utilizado para resolver demandas repetitivas em processos individuais ou coletivos

### Referências legais
- Art. 5º da Lei nº 7.347, de 24 de julho de 1985
- Art. 82 da Lei nº 8.078, de 11 de setembro de 1990
- Art. 986

### Dicas de prova
- Entenda a noção de ação civil pública e legitimidade para propor ação coletiva.
- Conheça o procedimento do incidente de resolução de demandas repetitivas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º da Lei nº 7.347, de 24 de julho de 1985", "Art. 82 da Lei nº 8.078, de 11 de setembro de 1990", "Art. 986"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:22:59.598419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=13", "doc_key": "b2d2f1ff7579134364204120974ecb8c"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6c2601ad180abf6ce206a3c2c69f8ffede67ae48f2563f0774655b0880aee786'),
  ('cpiuris2025::b36546e07068babd7381d74af6034b63', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Vasos Comunicantes no Processo Coletivo', '## Vasos Comunicantes no Processo Coletivo

A teoria dos vasos comunicantes é utilizada para relacionar ações coletiva e individual, especialmente em direitos transindividuais homogêneos.

### Conceitos
- **Vasos Comunicantes**: Relação entre ações coletiva e individual
- **Processo Coletivo Complexo**: Modelo de processo formado por dezenas de diplomas
- **Grau de Dependência**: Relação entre ação coletiva e individual em termos de dependência
- **Vinculação Individual**: Relação entre titular individual e ação coletiva
- **Efeitos da Sentença**: Impacto da sentença da ação coletiva na ação individual

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 631.111/GO (07.08.2014)

### Dicas de prova
- Entenda a teoria dos vasos comunicantes e sua aplicação no processo coletivo
- Identifique os aspectos importantes da relação entre ação coletiva e individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 631.111/GO (07.08.2014)"], "confidence": 0.8, "extracted_at": "2026-05-31T22:23:15.859659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=12", "doc_key": "b36546e07068babd7381d74af6034b63"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '97273c4c732e3c106766cabecdb348b7756cb0d29c83b4714341561045375ebe'),
  ('cpiuris2025::fa2e7cfe43546538b2185a300850bc96', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Tentativas de codificação do processo coletivo no Brasil', '## Tentativas de codificação do processo coletivo no Brasil

Discute-se a possibilidade de codificar o processo coletivo no Brasil, com críticas a tentativas anteriores. No entanto, existem projetos em andamento para aperfeiçoar o regramento das ações coletivas.

### Conceitos
- **Codificação do processo coletivo**: Procedimento de normalização e padronização do direito processual coletivo
- **Tentativas anteriores**: Projetos de códigos brasileiros de processo coletivo que foram criticados por engessamento, burocratização e adoção de modelos estrangeiros
- **Aperfeiçoamento do regramento das ações coletivas**: Projetos em andamento para melhorar o regramento das ações coletivas, como o Projeto de Lei n.º 4.778/20

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do processo coletivo no Brasil

### Dicas de prova
- Entenda a crítica às tentativas anteriores de codificação e os projetos em andamento para aperfeiçoar o regramento das ações coletivas
- Destaque a importância da tutela coletiva no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do processo coletivo no Brasil"], "confidence": 0.8, "extracted_at": "2026-05-31T22:23:38.243249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=13", "doc_key": "fa2e7cfe43546538b2185a300850bc96"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '619a82c6a9bdf220eba5e3d4905d221e35572179ba88e42e03f06fe8c32e8c7f'),
  ('cpiuris2025::fac25c9a5ef560f9f91ae8aaad9394ee', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípios da Participação no Processo e pelo Processo', '## Princípios da Participação no Processo e pelo Processo

O processo coletivo tem como objetivo ampliar o acesso à justiça para mais pessoas, com a universalização da jurisdição. A participação no processo é garantida pelo direito ao contraditório, enquanto a participação pelo processo é utilizada para influenciar o destino do Estado.

### Conceitos
- **Participação no Processo**: Direito ao contraditório e informação sobre práticas de atos processuais
- **Participação pelo Processo**: Uso do processo como influência política para moldar o destino do Estado
- **Legitimidade Extraordinária**: Permissão para pessoas ou entes atuarem em juízo, defendendo direito ou interesse alheio

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre participação no processo e participação pelo processo
- Entender a legitimidade extraordinária como mecanismo para defender direitos alheios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.15", "page_number": 15, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:25:25.797742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=15", "doc_key": "fac25c9a5ef560f9f91ae8aaad9394ee"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '24155681bbe27302a88b1f91da6fc1c40bfae10720032e82805dd1c72e898d99'),
  ('cpiuris2025::3677a01dfe9ef431e0464b7d1aacb36d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Teoria Geral do Processo Coletivo', '## Teoria Geral do Processo Coletivo

A doutrina sugere seguir um caminho para aplicar as leis no processo coletivo, buscando soluções nos diplomas específicos, núcleos do microssistema e demais diplomas relevantes.

### Conceitos
- **Direito Processual Coletivo Comum**: Objeto material: direitos coletivos lato sensu (difusos, coletivos em sentido estrito ou individuais homogêneos)
- **Direito Processual Coletivo Especial**: Objeto material: controle abstrato de constitucionalidade
- **Princípio do acesso à justiça**: Regra específica para o processo coletivo, que não se aplica às ações individuais
- **Legitimação ativa nas ações coletivas**: Diferença em relação às ações individuais, onde a legitimidade é ordinária ou especial

### Referências legais
- Art. 4.717/1965
- CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de Direito Processual Coletivo Comum e Especial
- Identifique os princípios do processo coletivo, especialmente o Princípio do acesso à justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.14", "page_number": 14, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 4.717/1965", "CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:25:38.706178+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=14", "doc_key": "3677a01dfe9ef431e0464b7d1aacb36d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '0dea39f60f9452ab3d105eb7c693d4905ee9558b6f41ec405891e3180f28d5dd'),
  ('cpiuris2025::eb883ca2b0a127e17f05ce3a2742f298', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio da Economia Processual no Processo Coletivo', '## Princípio da Economia Processual no Processo Coletivo

O processo coletivo potencializa o princípio da economia processual, permitindo que questões homogêneas sejam decididas em um único processo, evitando a criação de infinidade de ações individuais.

### Conceitos
- **Economia Processual**: Princípio que visa minimizar o número de processos e procedimentos
- **Processo Coletivo**: Procedimento jurídico que envolve a reunião de processos e decisões conjuntas
- **Litispendência**: Condição em que dois ou mais processos têm o mesmo objeto e são apresentados à justiça simultaneamente
- **Coisão Julgada**: Condição em que a decisão de um processo é considerada como parte integrante da decisão de outro processo com o mesmo objeto

### Referências legais
- Art. 4º do CPC/15
- Art. 6º do CPC/15

### Jurisprudência
- STJ. 2ª Seção. REsp 1110549/RS, Rel. Min. Sidnei Beneti, julgado em 28/10/2009
- STJ. 2ª Seção. REsp 1.525.327-PR, Rel. Min. Luis Felipe Salomão, julgado em 12/12/2018

### Dicas de prova
- Destacar a importância do princípio da economia processual no processo coletivo
- Entender a relação entre o processo coletivo e a litispendência
- Conhecer os dispositivos do CPC/15 que consagram o princípio da primazia da decisão de mérito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 4º do CPC/15", "Art. 6º do CPC/15"], "jurisprudence": ["STJ. 2ª Seção. REsp 1110549/RS, Rel. Min. Sidnei Beneti, julgado em 28/10/2009", "STJ. 2ª Seção. REsp 1.525.327-PR, Rel. Min. Luis Felipe Salomão, julgado em 12/12/2018"], "confidence": 0.8, "extracted_at": "2026-05-31T22:26:49.218149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=16", "doc_key": "eb883ca2b0a127e17f05ce3a2742f298"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '280bd1ee97622f1591a09f5737bd44f52e127d556bfad96d2f5d5885e76aa914'),
  ('cpiuris2025::af5c45ab90d8ae88e8d511c1ad7a5ffd', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Determinação de Vícios Processuais', '## Determinação de Vícios Processuais

O juiz deve determinar o suprimento de pressupostos processuais e o saneamento de outros vícios processuais, além de decidir sobre a anulação dos atos que não podem ser aproveitados.

### Conceitos
- **suprimento de pressupostos processuais**: ações necessárias para completar os requisitos legais do processo
- **saneamento de vícios processuais**: correção ou eliminação dos erros ou irregularidades no processo
- **anulação dos atos**: declaração de invalidade de uma ação ou decisão do juiz

### Referências legais
- Art. 139, IX
- Art. 283
- Art. 932, Parágrafo Único

### Dicas de prova
- Entenda a distinção entre anulação e saneamento de vícios processuais.
- Conheça o prazo de 5 dias concedido ao recorrente para sanar vício ou complementar a documentação exigível.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 139, IX", "Art. 283", "Art. 932, Parágrafo Único"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:27:31.402465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=16", "doc_key": "af5c45ab90d8ae88e8d511c1ad7a5ffd"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b569ea1820579230ae42016043c1372ba186cfacb2a1f733a2c5964116856148'),
  ('cpiuris2025::e5f2749ba1093fbd2c66522ed45d8faa', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Importância da Tutela Coletiva', '## Importância da Tutela Coletiva

A tutela coletiva evita a proliferação de ações individuais e decisões conflitantes, priorizando o interesse social.

### Conceitos
- **Tutela Coletiva**: proteção dos direitos de uma categoria de pessoas
- **Cosa Julgada Coletiva**: efeito da decisão coletiva que se aplica a todos os interessados
- **Interesse Social**: preocupação com o bem-estar da sociedade em geral

### Referências legais
- Art. 8º do Código de Processo Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da tutela coletiva para evitar decisões conflitantes
- Conheça a coisa julgada coletiva e seu impacto nos direitos individuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8º do Código de Processo Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:28:29.212353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=17", "doc_key": "e5f2749ba1093fbd2c66522ed45d8faa"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '651d41bffc75e0fed9873dd6770f98e5f45a4fddac717e887feb6625b472ad9d'),
  ('cpiuris2025::a883fa7db986d11334d8a21fb852f03f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Benefício de Interessados Individuais em Processos Coletivos', '## Benefício de Interessados Individuais em Processos Coletivos

O transporte da coisa julgada beneficia os interessados individuais em processos coletivos, especialmente quando há ação coletiva. A seleção do caso representativo da controvérsia é crucial para uma cognição de qualidade.

### Conceitos
- **Transporte da Cidade Julgada**: Benefício concedido aos interessados individuais em processos coletivos
- **Ação Coletiva**: Processo que envolve várias pessoas ou entidades com interesse comum
- **Caso Representativo da Controvérsia**: O caso escolhido para representar a controvérsia em processos coletivos

### Referências legais
- Art. 104 do CDC
- Art. 1.036, §6º do CPC
- Art. 9917 do CDC

### Jurisprudência
- RE 123456
- Enunciado n.º 237 da III Jornada de Direito Processual Civil

### Dicas de prova
- Entenda o transporte da coisa julgada e sua importância nos processos coletivos
- Conheça a seleção do caso representativo da controvérsia e sua relevância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 104 do CDC", "Art. 1.036, §6º do CPC", "Art. 9917 do CDC"], "jurisprudence": ["RE 123456", "Enunciado n.º 237 da III Jornada de Direito Processual Civil"], "confidence": 0.8, "extracted_at": "2026-05-31T22:29:47.437102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=18", "doc_key": "a883fa7db986d11334d8a21fb852f03f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '143272c89fb80ca4c76e0d371c218b4a22fb2cfe06e1cdf9679d7ff3bd353afa'),
  ('cpiuris2025::a52932147c6d32fb659ddd7dbb8b9fb0', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio da disponibilidade motivada da ação coletiva', '## Princípio da disponibilidade motivada da ação coletiva

A desistência do processo coletivo exige motivação adequada, devido ao princípio da indisponibilidade do interesse público.

### Conceitos
- **Desistência**: Abandono ou renúncia à ação coletiva
- **Princípio da disponibilidade**: Requisito de motivação adequada para desistência do processo coletivo
- **Indisponibilidade do interesse público**: Princípio que protege o interesse público em face da ação coletiva

### Referências legais
- Art. 5º § 3º da Lei n.º 7.347/85
- Art. 9º da Lei n.º 4.717/65

### Dicas de prova
- Entenda a diferença entre desistência e abandono na ação coletiva.
- Conheça o princípio da indisponibilidade do interesse público e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º § 3º da Lei n.º 7.347/85", "Art. 9º da Lei n.º 4.717/65"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:30:27.036017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=18", "doc_key": "a52932147c6d32fb659ddd7dbb8b9fb0"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '11ae41178c3928525ea1201f1218bb5293a36923e08b7ea885e8b1170ddbc682'),
  ('cpiuris2025::fa788b662b5c7db9b223dd5e4180a2c8', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Indisponibilidade da Execução Coletiva', '## Indisponibilidade da Execução Coletiva

A indisponibilidade da execução coletiva é um princípio que obriga o Ministério Público a executar a sentença condenatória em ações coletivas, especialmente após determinados prazos. O MP é obrigado a promover a execução, sob pena de sanção.

### Conceitos
- **Indisponibilidade da Execução Coletiva**: Princípio que obriga o Ministério Público a executar a sentença condenatória em ações coletivas
- **Execução Provisória**: Execução da sentença antes do trânsito em julgado
- **Execução Definitiva**: Execução da sentença após o trânsito em julgado

### Referências legais
- Art. 7º, inciso II do Código de Processo Civil
- Art. 15 da Lei n.º 7.347/1985
- Lei n.º 4.717/65, Art. 16

### Jurisprudência
- RE 123456
- Tema repetitivo: Indisponibilidade da Execução Coletiva

### Dicas de prova
- Entenda a diferença entre execução provisória e definitiva
- Conheça as sanções para o Ministério Público que não promove a execução
- Identifique a Lei de Ação Civil Pública e da Ação Popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.19", "page_number": 19, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 7º, inciso II do Código de Processo Civil", "Art. 15 da Lei n.º 7.347/1985", "Lei n.º 4.717/65, Art. 16"], "jurisprudence": ["RE 123456", "Tema repetitivo: Indisponibilidade da Execução Coletiva"], "confidence": 0.8, "extracted_at": "2026-05-31T22:32:32.049023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=19", "doc_key": "fa788b662b5c7db9b223dd5e4180a2c8"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'efd8f167f7959a3d7444a6c87b0f10c0bd49b81fde1fb5bcdf815f32a9bda8fb'),
  ('cpiuris2025::fabe4c77f12f2d24ca771e9078efc5f3', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio da não taxatividade da ação coletiva', '## Princípio da não taxatividade da ação coletiva

O princípio da não taxatividade da ação coletiva permite que todos os direitos difusos e coletivos sejam tutelados por meio de ações civis públicas, mesmo sem previsão expressa em lei.

### Conceitos
- **Ação Civil Pública**: ação pública que visa tutelar direitos difusos e coletivos
- **Lei n.º 7.347/85**: Lei que instituiu o Código de Defesa do Consumidor
- **CDC**: Código de Defesa do Consumidor
- **Art. 90 do CDC**: aplicação das normas do Código de Processo Civil e da Lei nº 7.347, inclusive no que respeita ao inquérito civil
- **Art. 21 da LACP**: aplicação dos dispositivos do Título III da lei que instituiu o Código de Defesa do Consumidor
- **Direitos coletivos**: direitos que podem ser tutelados por meio de ações civis públicas

### Referências legais
- Art. 1º, IV da Lei n.º 7.347/85
- Art. 90 do CDC
- Art. 21 da LACP
- Art. 5º, inciso LXX da CF

### Jurisprudência
- RE 123456
- Tema repetitivo: ação civil pública e direitos coletivos

### Dicas de prova
- Entenda o princípio da não taxatividade da ação coletiva e como ela se aplica aos direitos difusos e coletivos.
- Conheça as normas do Código de Defesa do Consumidor e sua aplicação às ações civis públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º, IV da Lei n.º 7.347/85", "Art. 90 do CDC", "Art. 21 da LACP", "Art. 5º, inciso LXX da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo: ação civil pública e direitos coletivos"], "confidence": 0.8, "extracted_at": "2026-05-31T22:33:43.003555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=20", "doc_key": "fabe4c77f12f2d24ca771e9078efc5f3"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f400c797446d27aa570c2fbb94f47f8230b85d6de985a63f6e762b52b0667759'),
  ('cpiuris2025::2a93f05741a2badea050bc4be2637855', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio do máximo benefício da tutela jurisdicional coletiva comum', '## Princípio do máximo benefício da tutela jurisdicional coletiva comum

O princípio do máximo benefício da tutela jurisdicional coletiva comum protege os indivíduos no processo coletivo, permitindo que eles ajuízem ações individuais posteriormente se a decisão coletiva não atender às suas necessidades.

### Conceitos
- **Legitimação extraordinária**: O direito de pleitear em nome próprio um direito alheio
- **Ação popular**: Procedimento que permite ajuizamento de ações por parte de terceiros sem necessidade de autorização dos titulares dos direitos coletivos

### Referências legais
- Art. 1º da Lei nº 8.078/1990
- Súmula 646 do Supremo Tribunal Federal

### Dicas de prova
- Entenda a diferença entre legitimidade ordinária e extraordinária
- Conheça o conceito de ação popular e sua importância no processo coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º da Lei nº 8.078/1990", "Súmula 646 do Supremo Tribunal Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:34:35.481088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=20", "doc_key": "2a93f05741a2badea050bc4be2637855"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '9b03ca8b86647a133b7e77a15c33c8665739e09911c8d04f94b712129d3249c7'),
  ('cpiuris2025::68272a64bb1545cfe5149b4b09405305', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ações Capazes em Código de Defesa do Consumidor (CDC) e Lei n° 7.347/85', '## Ações Capazes em Código de Defesa do Consumidor (CDC) e Lei n° 7.347/85

Resumo objetivo: Discute as ações capazes no CDC e na Lei n° 7.347/85, aplicando-se normas do Código de Processo Civil e da Lei n° 7.347/85.

### Conceitos
- **Ação Capaz**: Ação que pode ser proposta perante o juiz para buscar a tutela jurídica
- **Código de Defesa do Consumidor (CDC)**: Lei que protege os direitos e interesses dos consumidores
- **Lei n° 7.347/85**: Lei que regula o inquérito civil
- **Código de Processo Civil**: Lei que regula o processo judicial

### Referências legais
- Art. 5º, XXXV da CF
- Art. 83 do CDC
- Art. 90 do CDC
- Art. 12 do LACP
- Art. 21 do LACP

### Dicas de prova
- Entenda a diferença entre ações capazes e não capazes no contexto do CDC e da Lei n° 7.347/85.
- Conheça as normas aplicáveis às ações previstas neste título.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, XXXV da CF", "Art. 83 do CDC", "Art. 90 do CDC", "Art. 12 do LACP", "Art. 21 do LACP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:35:40.011261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=21", "doc_key": "68272a64bb1545cfe5149b4b09405305"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3f1e8dc0affc46f2e460c2e63b32c3e1c6b65cdad249615c1ffd49d40026f452'),
  ('cpiuris2025::8b4e42556a3bc39eab5e36eabb5543c8', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio da máxima amplitude do processo coletivo', '## Princípio da máxima amplitude do processo coletivo

O princípio garantiza que a tutela dos interesses coletivos pode ser obtida mediante todas as espécies de ações, procedimentos, provimentos e tutelas provisórias.

### Conceitos
- **Máxima amplitude do processo coletivo**: Princípio que permite a obtenção da tutela dos interesses coletivos mediante todas as espécies de ações, procedimentos, provimentos e tutelas provisórias.
- **Instrumentalidade absoluta da tutela coletiva**: Conceito que afirma que a tutela dos interesses coletivos pode ser obtida mediante todas as espécies de ações, procedimentos, provimentos e tutelas provisórias.
- **Princípio da inafastabilidade da jurisdição**: Princípio que estabelece que a Justiça é inafastável e deve ser exercida em todos os casos, independentemente do valor ou natureza da causa.
- **Tutela coletiva**: Forma de tutelar os interesses coletivos, que pode ser obtida mediante ações, procedimentos, provimentos e tutelas provisórias.

### Referências legais
- Art. 103 do CDC

### Dicas de prova
- Entenda o conceito de máxima amplitude do processo coletivo e como ele se relaciona com a inafastabilidade da jurisdição.
- Análise conjunta dos princípios da máxima amplitude e da inafastabilidade da jurisdição para extrair o conceito correto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 103 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:35:47.023887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=21", "doc_key": "8b4e42556a3bc39eab5e36eabb5543c8"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '01ad80055fd8532cf79dabba17d5fcc6dec3e6f271c88233136890a8761375a1'),
  ('cpiuris2025::b7a887bd9137f441304260d98a29c17e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Alcance do Edital de Propositura da Ação Coletiva', '## Alcance do Edital de Propositura da Ação Coletiva

O edital tem baixa efetividade em relação a outros meios de publicidade, contrastando com a intenção da norma de permitir intervenção dos interessados no processo.

### Conceitos
- **Máxima efetividade da tutela coletiva**: Princípio que busca garantir a eficácia da proteção dos direitos coletivos
- **Contrapropaganda**: Instrumento de publicidade utilizado para contrariar a publicação de informações falsas ou enganosas
- **Acessibilidade**: Direito à participação e ao envolvimento dos grupos vulneráveis em processos judiciais

### Referências legais
- Art. 94 da Lei nº 7.853/89
- Código de Processo Civil (CPC)
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre edital e contrapropaganda
- Conheça o princípio da máxima efetividade da tutela coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 94 da Lei nº 7.853/89", "Código de Processo Civil (CPC)", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:37:59.047651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=22", "doc_key": "b7a887bd9137f441304260d98a29c17e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '9925b82bd6df40d5f9b510ed9547098830da65235396598ec873329a86ceeed9'),
  ('cpiuris2025::49df681354ded3612562d9019c6aac57', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio da ampla divulgação da demanda', '## Princípio da ampla divulgação da demanda

O princípio da ampla divulgação da demanda visa informar todos os interessados sobre a ação coletiva. De acordo com o CDC, a ação deve ser publicada em edital e divulgada por meio de comunicação social.

### Conceitos
- **Princípio da ampla divulgação da demanda**: avisar à gama de possíveis interessados sobre o ajuizamento da ação coletiva
- **Fair Notice**: direito norte-americano que exige a notificação prévia dos interessados sobre uma ação ou decisão
- **Litisconsortes**: partes que se unem à ação coletiva sem prejuízo de ampla divulgação

### Referências legais
- Art. 94 do Código de Defesa do Consumidor (CDC)

### Jurisprudência
- REsp 625.249/PR
- Enunciado nº 620 do FPPC
- Enunciado n.º 223 da III Jornada de Direito Processual Civil

### Dicas de prova
- Entenda o conceito de fair notice e sua aplicação no direito brasileiro
- Conheça a importância da divulgação em ações coletivas
- Aprenda a distinguir entre litisconsortes e outras formas de participação nos processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 94 do Código de Defesa do Consumidor (CDC)"], "jurisprudence": ["REsp 625.249/PR", "Enunciado nº 620 do FPPC", "Enunciado n.º 223 da III Jornada de Direito Processual Civil"], "confidence": 0.8, "extracted_at": "2026-05-31T22:38:39.934933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=22", "doc_key": "49df681354ded3612562d9019c6aac57"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '12073e5d31bc0e9457ecce652ec625e2bc8a9d58781c7045ef5acc3bb3bfe735'),
  ('cpiuris2025::271041017ca6254384c3ae6647398c69', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio da informação aos órgãos legitimados', '## Princípio da informação aos órgãos legitimados

O princípio da informação aos órgãos legitimados busca estimular a propositura da ação coletiva. É um objetivo do princípio da ampla divulgação da demanda, mas com uma abordagem diferente.

### Conceitos
- **Princípio da informação aos órgãos legitimados**: Busca estimular a propositura da ação coletiva
- **Ampla divulgação da demanda**: Objetivo do princípio, que busca evitar a proliferação de ações individuais

### Referências legais
- Art. 6º da LACP
- Art. 7º da LACP
- Art. 139, X do CPC

### Jurisprudência
- Enunciado n.º 119 do FPPC

### Dicas de prova
- Distinção entre a ampla divulgação da demanda e o princípio da informação aos órgãos legitimados
- Importância de identificar os órgãos legitimados para a propositura da ação coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 6º da LACP", "Art. 7º da LACP", "Art. 139, X do CPC"], "jurisprudence": ["Enunciado n.º 119 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-31T22:40:15.331976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=23", "doc_key": "271041017ca6254384c3ae6647398c69"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dbc1fb6d733d74d47e7a03d1c7c04c8ca141d60a7bf0f4ae3c406c479406d89a'),
  ('cpiuris2025::cbc38cfd3748f609bad30e2f061ecde3', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Princípio da maior coincidência entre o direito e sua realização', '## Princípio da maior coincidência entre o direito e sua realização

O princípio da maior coincidência entre o direito e sua realização prevalece na ação coletiva, priorizando a tutela específica da obrigação em detrimento de outras formas de realização do direito lesado.

### Conceitos
- **Princípio da maior coincidência**: Prevalência da tutela específica da obrigação em detrimento de outras formas de realização do direito lesado
- **Ação coletiva**: Procedimento jurídico que visa a tutelar os direitos de vítimas de uma situação comum

### Referências legais
- Art. 84 do CDC

### Dicas de prova
- Entenda o conceito de Princípio da maior coincidência e sua aplicação na ação coletiva
- Análise das limitações do procedimento de liquidação de sentença em sede de ação coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 84 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:40:40.012135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=23", "doc_key": "cbc38cfd3748f609bad30e2f061ecde3"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3c664bfd6f257ceae4d04a03163a9315ca01bd5aab014ace070cd0b50587711f'),
  ('cpiuris2025::3d3667894a8d084ee8e7e791369a3490', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Tutela específica em processos coletivos', '## Tutela específica em processos coletivos

O juiz concede tutela específica ou determina providências para garantir resultado prático equivalente ao adimplemento da obrigação. A conversão em perdas e danos é admissível apenas se o autor optar ou se impossível a tutela específica.

### Conceitos
- **Tutela específica**: medida que garante resultado prático equivalente ao adimplemento da obrigação
- **Conversão em perdas e danos**: substituição da tutela específica por indenização
- **Reparação integral do dano**: compensação completa do dano suportado pelos autores

### Referências legais
- Art. 1º, § 1º, do CPC/73
- Art. 537, do CPC/2015
- Art. 287, do CPC/2015

### Dicas de prova
- Entenda a diferença entre tutela específica e conversão em perdas e danos.
- Conheça o princípio da reparação integral do dano em processos coletivos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º, § 1º, do CPC/73", "Art. 537, do CPC/2015", "Art. 287, do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:41:07.789362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=24", "doc_key": "3d3667894a8d084ee8e7e791369a3490"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4aa665955b89475677367ab16e3b71e2796c678604c2a7b04018337f2ef64974'),
  ('cpiuris2025::dddf233535051d5d09ad4f7e85848a8a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Condenação em Ação Popular', '## Condenação em Ação Popular

O princípio da condenação pode ser extraído de dispositivos legais, como a Lei de Ação Popular, onde se prevê a condena de responsáveis por danos e beneficiários, ressalvada a ação regressiva contra funcionários causadores de dano.

### Conceitos
- **Ação Popular**: ação direta contra o Estado ou entidade pública
- **Condenação**: decisão judicial que impõe uma obrigação ao responsável por um dano
- **Responsáveis**: parties que sejam responsáveis por um dano
- **Beneficiários**: parties que se beneficiam de uma condenação
- **Ação Regressiva**: ação direta contra um funcionário que causou um dano
- **Lei de Ação Popular**: leis que regulamentam ações diretas contra o Estado ou entidade pública
- **CDC (Código Civil)**: leis que regulamentam as relações civis

### Referências legais
- Art. 11 da Lei de Ação Popular
- Art. 100 do Código Civil

### Dicas de prova
- Entenda a diferença entre pedido explícito e implícito em ações populares
- Conheça o conceito de responsabilidade e beneficiários na Ação Popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 11 da Lei de Ação Popular", "Art. 100 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:42:57.867315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=24", "doc_key": "dddf233535051d5d09ad4f7e85848a8a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1c444cb18edf2cf5b5d4fa24535ce7d338c5a3d7285f57fd39183cb8629c801d'),
  ('cpiuris2025::b20a84fdd98a46c02f72d43e212fda85', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Objeto do processo coletivo', '## Objeto do processo coletivo

O objeto do processo coletivo inclui direitos transindividuais, como direitos difusos, coletivos em sentido amplo e individuais homogêneos. A definição desses direitos é feita pelo Código de Defesa do Consumidor.

### Conceitos
- **direitos transindividuais**: Direitos que não se referem a indivíduos específicos, mas sim a uma categoria ou grupo de pessoas
- **direitos difusos**: Direitos que são comuns a um grupo de pessoas e não podem ser identificados individualmente
- **direitos coletivos em sentido amplo**: Gênero que inclui direitos difusos, coletivos em sentido estrito e individuais homogêneos
- **direitos coletivos em sentido estrito**: Espécie de direitos transindividuais que se referem a um grupo específico de pessoas
- **direitos individuais homogêneos**: Direitos que são semelhantes e decorrentes de origem comum

### Referências legais
- Art. 81 do Código de Defesa do Consumidor

### Dicas de prova
- Entenda a distinção entre direitos difusos, coletivos em sentido amplo e individuais homogêneos
- Conheça os critérios utilizados para diferenciar essas espécies de direitos transindividuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.25", "page_number": 25, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 81 do Código de Defesa do Consumidor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:43:31.863603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=25", "doc_key": "b20a84fdd98a46c02f72d43e212fda85"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '049121b072af21941dc8f175f1d974ee0bc520ff0989cf5fae95d9f571d4a298'),
  ('cpiuris2025::d950013547e9eda64ebeac98a4ec8942', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos difusos e coletivos', '## Direitos difusos e coletivos

Resumo do conceito de direitos difusos e coletivos, destacando suas características e exemplos.

### Conceitos
- **Indivisibilidade do objeto**: Característica dos direitos difusos e coletivos, que significa que o objeto do direito é indivisível e pertence a todos os titulares.
- **Situación de fato em comum**: Característica dos direitos difusos, que significa que os titulares estão ligados por circunstâncias de fato.
- **Indeterminabilidade dos titulares**: Característica dos direitos difusos, que significa que os titulares são pessoas indeterminadas e indetermináveis.
- **Relação jurídica base**: Característica dos direitos coletivos, que significa que há uma relação jurídica em comum entre os titulares e a parte contrária.
- **Determinabilidade dos titulares**: Característica dos direitos coletivos, que significa que os titulares são indeterminados, mas determináveis com base no grupo, categoria ou classe.

### Referências legais
- Art. 2.6 do CDC

### Dicas de prova
- Pergunte sobre a diferença entre direitos difusos e coletivos.
- Destaque a importância da relação jurídica base nos direitos coletivos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.26", "page_number": 26, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2.6 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:43:53.713558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=26", "doc_key": "d950013547e9eda64ebeac98a4ec8942"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5161aaf8d54f140e7d6f69aa42d5188c4a1bc667e911631861bb5cfa17b76230'),
  ('cpiuris2025::3eaf8db1ac56eb31e8601aabdddf67f4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos Individuais Homogêneos', '## Direitos Individuais Homogêneos

São direitos que se aplicam a todos os titulares, de forma indivisível, com características como divisibilidade do objeto, origem comum, determinabilidade dos titulares e recomendabilidade de tratamento conjunto.

### Conceitos
- **Divisibilidade do objeto**: O direito pode ser dividido em partes igualmente prejudiciais
- **Origem comum**: Todos os titulares têm uma situação fática ou jurídica em comum
- **Determinabilidade dos titulares**: É possível identificar todos os titulares do direito
- **Recomendabilidade de tratamento conjunto**: O tratamento é recomendável para todos os titulares

### Referências legais
- Art. 8 da Lei nº 7.347/1985
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de direitos individuais homogêneos e como diferenciá-los de direitos coletivos ou difusos
- Análise da situação hipotética para aplicar as características dos direitos homogêneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8 da Lei nº 7.347/1985", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:45:17.568861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=27", "doc_key": "3eaf8db1ac56eb31e8601aabdddf67f4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c14491905ca104ba70c3cf6161ed1328861b6b836fdbdacc7a6d37c187f8295d'),
  ('cpiuris2025::33dfd46abb8fce308688af46f6293893', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Dano-Moral e Prejuízo Material em Processo Coletivo', '## Dano-Moral e Prejuízo Material em Processo Coletivo

O direito ao meio ambiente ecologicamente equilibrado é um direito difuso. Em caso de poluição, os lesados podem buscar reparação individualmente, com base no dano sofrido.

### Conceitos
- **Dano-Moral**: Prejuízo moral sofrido por uma pessoa em decorrência de um evento ou situação
- **Prejuízo Material**: Perda ou danos físicos ou econômicos causados a uma pessoa ou coisa jurídica
- **Reparação Integral**: Conjunção de prejuízos materiais e morais para compensar o dano sofrido por uma pessoa

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre prejuízo material e dano-moral
- Conhecer a regra de reparação integral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:45:32.041413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=27", "doc_key": "33dfd46abb8fce308688af46f6293893"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '29ceeb5b4d4ce96a51e33889f2d1755d19c124b4da8512632de2e4683f152095'),
  ('cpiuris2025::fd0f9ce8d33fb9f7c1aa752a5ca4d679', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direito Coletivo em Sentido Amplo', '## Direito Coletivo em Sentido Amplo

O direito coletivo em sentido amplo se aplica a situações em que haja lesão a um direito cujo objeto seja indivisível, como o meio ambiente equilibrado. No entanto, quando os titulares do plano de saúde forem afetados de forma individualizada, com direitos homogêneos, o direito coletivo perde sua característica coletiva.

### Conceitos
- **Direito Coletivo em Sentido Amplo**: aplicação do direito coletivo a situações em que haja lesão a um direito cujo objeto seja indivisível
- **Lesões a Direitos Individuais Homogêneos**: situação em que os titulares forem afetados de forma individualizada, com direitos homogêneos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte ao candidato se o direito coletivo está presente em situações de lesão a um direito cujo objeto seja indivisível.
- Verifique se os titulares forem afetados de forma individualizada, com direitos homogêneos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:46:14.687993+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=28", "doc_key": "fd0f9ce8d33fb9f7c1aa752a5ca4d679"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6d7ca9a27c98b42ab0d35f1dc025eb31dfdf59ab5d8a0c5dc05e0eeec159c543'),
  ('cpiuris2025::fe24be1465348d46ab4bcd0bdf934702', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos Coletivos vs Individuais Homogêneos', '## Direitos Coletivos vs Individuais Homogêneos

Análise de direitos coletivos e individuais homogêneos em casos de publicidade enganosa.

### Conceitos
- **Direito Difuso**: direito que se aplica a todos os membros de uma categoria
- **Direitos Coletivos**: direitos que se aplicam a um grupo específico de pessoas
- **Direitos Individuais Homogêneos**: direitos que são iguais para todos os membros de uma categoria
- **Tutela Coletiva**: solução que se aplica a um grupo específico de pessoas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre direitos coletivos e individuais homogêneos.
- Conheça a recomendabilidade de tratamento conjunto em casos concretos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:47:10.090417+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=28", "doc_key": "fe24be1465348d46ab4bcd0bdf934702"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'fd0d4b0055bc37a41ca22e81916d69fd0f8d02ffe711b2a44e0986f14ecc40e9'),
  ('cpiuris2025::15b44217e5b320378bb830afd6a6422d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos Coletivos em Sentido Amplo', '## Direitos Coletivos em Sentido Amplo

A ação coletiva admite tutela de direitos individuais quando há utilidade para a tutela individual, exigindo um número razoável de indivíduos. Os direitos coletivos em sentido amplo têm características específicas, como indivisibilidade do objeto e relação jurídica comum.

### Conceitos
- **Direito Coletivo**: direito que se aplica a um grupo de pessoas
- **Direito Difuso**: direito que se aplica a todos os membros de uma categoria ou classe
- **Direitos Coletivos em Sentido Estrito**: direitos que se aplicam a objetos indivisíveis e pertencem a titulares indeterminados
- **Titular Indeterminado**: pessoa cuja identidade não é conhecida ou não pode ser determinada
- **Transindividualidade Real**: conceito que se refere à existência de uma relação jurídica comum entre os titulares indeterminados

### Referências legais
- Art. 8 da Lei nº 7.853/89

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Entenda a distinção entre direitos coletivos em sentido amplo e estrito
- Conheça as características específicas dos direitos coletivos em sentido amplo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8 da Lei nº 7.853/89"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T22:48:14.893404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=29", "doc_key": "15b44217e5b320378bb830afd6a6422d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '601b38494942aaf2a19b09c5208d1d0a8e45ad78999e8e868a1f49f5d5785af6'),
  ('cpiuris2025::6455d93185b1a8c7bee5da455ae0ad4f', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação coletiva: direito individual homogêneo', '## Ação coletiva: direito individual homogêneo

Resumo objetivo em 2-5 frases: A ação coletiva pode abranger direitos individuais homogêneos, não apenas um único direito. O objetivo é tutelar uma relação jurídica individual, envolvendo vários titulares de interesses individuais.

### Conceitos
- **Ação coletiva**: ação que visa proteger direitos ou interesses comuns
- **Direito individual homogêneo**: direito que é aplicável a todos os titulares de um mesmo interesse
- **Relações jurídicas individuais**: relações que envolvem direitos e obrigações individuais

### Referências legais
- Art. 82 do Código de Processo Civil
- ...

### Jurisprudência
- REsp 823.063/PR
- REsp 1.109.335/SE

### Dicas de prova
- Diferenciar entre direito individual homogêneo e único
- Entender que a ação coletiva pode abranger vários titulares de interesses individuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 do Código de Processo Civil", "..."], "jurisprudence": ["REsp 823.063/PR", "REsp 1.109.335/SE"], "confidence": 0.8, "extracted_at": "2026-05-31T22:48:16.458573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=29", "doc_key": "6455d93185b1a8c7bee5da455ae0ad4f"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '277c3122dd53d767c212e68793ec66b2274d28bacd9495935354b86028d91334'),
  ('cpiuris2025::7d804368ac3553f6d7f6e9d1061343c4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Transindividualidade artificial e ação coletiva', '## Transindividualidade artificial e ação coletiva

A transindividualidade artificial se refere à consideração de interesses acidentalmente coletivos. A jurisprudência afirma que não há cabimento da remessa necessária em ações coletivas que versam sobre direitos individuais homogêneos, pois tais direitos são considerados acidentalmente coletivos.

### Conceitos
- **Transindividualidade artificial**: Consideração de interesses acidentalmente coletivos
- **Ação coletiva**: Procedimento jurídico que visa tutelar direitos individuais homogêneos
- **Remessa necessária**: Instituto processual que permite a remessa de uma decisão anterior para um tribunal superior em caso de dúvida sobre sua legalidade ou interpretação
- **Legitimidade coletiva**: Direito do Ministério Público ou outra entidade a agir em nome de um grupo de pessoas

### Referências legais
- Art. 19 da Lei nº 4.717/65

### Jurisprudência
- STJ, RECURSO ESPECIAL 1.374.232-ES
- Súmula 342 do STJ

### Dicas de prova
- Entenda a distinção entre transindividualidade artificial e ação coletiva
- Conheça o conceito de remessa necessária e sua aplicação às ações coletivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 19 da Lei nº 4.717/65"], "jurisprudence": ["STJ, RECURSO ESPECIAL 1.374.232-ES", "Súmula 342 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T22:48:42.624128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=30", "doc_key": "7d804368ac3553f6d7f6e9d1061343c4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '688031366d39d14f98190645826ec0f66df9e39cb6ef133dea10a22bb28d267b'),
  ('cpiuris2025::1d4031f47ea6e5c0c4dfa72bf7753782', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Caracterização dos direitos difusos e coletivos', '## Caracterização dos direitos difusos e coletivos

Os direitos difusos e coletivos são indivisíveis e seus titulares são indeterminados ou apenas determináveis, enquanto os individuais homogêneos são divisíveis e seus titulares são determinados.

### Conceitos
- **direitos difusos**: direitos que não têm titular identificado ou identificável
- **direitos coletivos**: direitos que têm titular indeterminado ou apenas determinável
- **direitos individuais homogêneos**: direitos que são divisíveis e têm titular determinado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre direitos difusos e coletivos
- Conheça a característica da divisibilidade nos direitos individuais homogêneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:50:28.307694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=31", "doc_key": "1d4031f47ea6e5c0c4dfa72bf7753782"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '68722156c6015ca829265c7545ce55550b2866f7ae4d8ae4522805ba16864c26'),
  ('cpiuris2025::069eebc1a95aefea1a48badb335a3f74', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Sistema de Vasos Comunicantes no Processo Civil Coletivo', '## Sistema de Vasos Comunicantes no Processo Civil Coletivo

O sistema de vasos comunicantes é uma coleta de normas que forma a base do processo civil coletivo, conferindo legitimidade ao Ministério Público para propor ações cíveis para reparação de danos ambientais.

### Conceitos
- **Sistema de Vasos Comunicantes**: coleta de normas que forma a base do processo civil coletivo
- **Processo Civil Coletivo**: processo em que o Ministério Público pode propor ações cíveis para reparação de danos ambientais
- **Legitimidade do Ministério Público**: conferida pela Lei n.º 7.347/1985

### Referências legais
- Art. 8 da Lei n.º 7.347/1985

### Dicas de prova
- Entenda a importância do sistema de vasos comunicantes no processo civil coletivo.
- Conheça a legitimidade do Ministério Público para propor ações cíveis no âmbito ambiental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 8 da Lei n.º 7.347/1985"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:50:54.594543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=30", "doc_key": "069eebc1a95aefea1a48badb335a3f74"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e3a7ae56d044ac735b3b5e2528a72992074f8cc80c5433a7284e41dc504a85b1'),
  ('cpiuris2025::1e886ee1c044aa0e14525867cb5a7c5e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direito Processual Coletivo Especial', '## Direito Processual Coletivo Especial

O direito processual coletivo especial não se presta à tutela de direitos subjetivos, mas sim à resolução de conflitos coletivos. Além disso, é destinado a possibilitar o controle incidental de constitucionalidade da lei ou ato normativo.

### Conceitos
- **Direito Processual Coletivo Especial**: Resposta a conflitos coletivos
- **Disponibilidade Controlada**: Não se aplica em casos de direitos individuais homogêneos
- **Instrumentalidade das Formas**: Princípio que preza pela observação e conhecimento do conteúdo, não apenas da forma

### Referências legais
- Art. 81, III, da Lei nº 8.078/90

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Pegar a definição de direito processual coletivo especial e sua relação com a disponibilidade controlada
- Distinção entre direitos individuais homogêneos e difusos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 81, III, da Lei nº 8.078/90"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:50:58.623383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=31", "doc_key": "1e886ee1c044aa0e14525867cb5a7c5e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c232e5bda71af22ac97ab6f41ef025149c7f982bd26ec7eb1c7436efa191806c'),
  ('cpiuris2025::4ee5e705c976475704db16359dba8fe6', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Homogeneidade dos direitos individuais em Processo Coletivo', '## Homogeneidade dos direitos individuais em Processo Coletivo

A homogeneidade dos direitos individuais pode ser considerada sob aspectos qualitativo e quantitativo, não sendo um fato gerador único.

### Conceitos
- **Qualitativo**: Relacionado à natureza ou características dos direitos individuais
- **Quantitativo**: Relacionado ao número ou quantidade de direitos individuais
- **Fato gerador único**: Não é o caso, pois a homogeneidade se refere a fatos de origem comum

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a natureza dos direitos individuais em Processo Coletivo
- Entenda a diferença entre fatos geradores únicos e de origem comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:52:36.610432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=32", "doc_key": "4ee5e705c976475704db16359dba8fe6"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dd59478767b0667ac05c8d20ab27dbc6485df648697f6ac6dd7c73c96d16d48a'),
  ('cpiuris2025::2b86abc86c348c0ac69e923a9558a103', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Sistema de Vosos Comunicantes', '## Sistema de Vosos Comunicantes

O sistema de vasos comunicantes é o conjunto de normas que compõem o microssistema de tutela coletiva, mantendo-se interligado e em comunicação.

### Conceitos
- **Sistema de Vosos Comunicantes**: conjunto de normas que compõem o microssistema de tutela coletiva
- **Microssistema de Tutela Coletiva**: conjunto de normas que regem as ações e processos coletivos
- **Vasos Comunicantes**: normas que se interligam e comunicam entre si, formando o microssistema de tutela coletiva

### Referências legais
- Art. 322, §2º, do CPC

### Dicas de prova
- Reconheça a teoria dos vasos comunicantes e sua aplicação no processo coletivo
- Entenda a distinção entre o sistema de vasos comunicantes e o princípio da não taxatividade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 322, §2º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:52:46.059306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=32", "doc_key": "2b86abc86c348c0ac69e923a9558a103"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '12f0f97e6fa8da91b9598e30ed2586c3d324efacb57d04c785a463e8fd1a675d'),
  ('cpiuris2025::87094950c05ff6501dbb8982c72538f2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ações coletivas em sentido amplo', '## Ações coletivas em sentido amplo

Resumo sobre a distinção entre ações coletivas e ações civis públicas, bem como as espécies de ações coletivas.

### Conceitos
- **Ações coletivas**: Conjunto de ações que tutelam direitos difusos, coletivos ou individuais homogêneos
- **Ação civil pública**: Ação em sentido estrito, abrangendo a ação de improbidade administrativa
- **Ação popular**: Ação que tutela direitos difusos ou coletivos
- **Mandado de segurança coletivo**: Medida cautelar para proteger direitos difusos ou coletivos
- **Mandado de injunção coletivo**: Medida cautelar para impor ações de natureza coletiva

### Referências legais
- Art. 10 da Lei nº 7.347/85
- Art. 13 da Lei nº 7.347/85

### Dicas de prova
- Entenda a distinção entre ações coletivas e ações civis públicas
- Conheça as espécies de ações coletivas (ação civil pública, ação popular, mandado de segurança coletivo e mandado de injunção coletivo)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.34", "page_number": 34, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 10 da Lei nº 7.347/85", "Art. 13 da Lei nº 7.347/85"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:53:39.855317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=34", "doc_key": "87094950c05ff6501dbb8982c72538f2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1fcce63c8f9a14690ba921eda29bbd2bb459298d5730fc036fa6d1a0da2e6962'),
  ('cpiuris2025::2f4207de1aa170fe5ec94d4545dd1987', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Opt-out em Ações Coletivas', '## Opt-out em Ações Coletivas

O opt-out é o direito do interessado de se excluir dos efeitos da sentença, permitindo a notificação aos outros interessados.

### Conceitos
- **Ação Coletiva**: procedimento que visa tutelar direitos individuais homogêneos
- **Opt-out**: direito do interessado de se excluir dos efeitos da sentença
- **Notificação**: aviso feito aos interessados para informá-los sobre a ação coletiva

### Referências legais
- Art. 82 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre opt-out e opt-in.
- Conheça as implicações da notificação nos outros interessados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:54:24.816658+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=35", "doc_key": "2f4207de1aa170fe5ec94d4545dd1987"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4f88782199b927b88a11c232036adfca40e24943fb63670b5e03d4ee9e4d46ca'),
  ('cpiuris2025::4c973fe4b1de0713fd691a7ca3b229db', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Class Actions (Ações de Grupo) no Direito Norte-Americano', '## Class Actions (Ações de Grupo) no Direito Norte-Americano

As Class Actions são ações coletivas criadas para tutelar integralmente os direitos supraindividuais, diante da ineficácia do modelo clássico de processo individual.

### Conceitos
- **Comunhão de questões de fato ou de direito**: necessária para a instauração da class action
- **Legitimidade ativa de um indivíduo ou grupo**: sujeita a controle da ''representação adequada''
- **Coisão julgada com força vinculante para toda a classe**: necessária para proteger os direitos dos membros do grupo
- **Notificação adequada (fair notice)**: permite aos representados optar por fora ou entrar no processo

### Referências legais
- Art. 102 da Lei nº 7.270/82
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da comunhão de questões de fato ou direito para a instauração da class action.
- Verifique se o autor tem legitimidade ativa e capacidade para defender o interesse do grupo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102 da Lei nº 7.270/82", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:55:02.428711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=35", "doc_key": "4c973fe4b1de0713fd691a7ca3b229db"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '20e8b1cea3fae6d925073855b1f404b7ec8e81fd883058f229b0356776d5ba64'),
  ('cpiuris2025::75568ca822b43ea43492e8706b3449a2', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Institutos do Processo Coletivo e Class Actions', '## Institutos do Processo Coletivo e Class Actions

A ação coletiva pode ser admitida com certificação, notificando os interessados sobre a existência do processo. Eles podem optar por participar ou não, afetando sua vinculação à coisa julgada.

### Conceitos
- **Legitimação passiva**: O direito norte-americano admite legitimidade passiva coletiva, diferente do direito brasileiro.
- **Fluid Recovery**: Instituto que permite a destinação do resíduo da indenização não reclamado pelos membros da classe representados na demanda
- **Opt-in/Opt-out**: O interessado pode optar por participar ou não da relação processual e afetar sua vinculação à coisa julgada.

### Referências legais
- Art. 82 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da notificação nos processos coletivos.
- Conheça as diferenças entre o direito brasileiro e norte-americano em relação à legitimidade passiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:55:56.569171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=36", "doc_key": "75568ca822b43ea43492e8706b3449a2"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c6eafaa4c81f3a75bbfba85311fa06ecb8899f9bb13ea17927a2e94b68a0f81c'),
  ('cpiuris2025::89b777ba396472a91d34387512e4204a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Coisas Julgadas e Class Actions', '## Coisas Julgadas e Class Actions

Resumo sobre a coisa julgada e class actions no Brasil, destacando as diferenças com o sistema americano.

### Conceitos
- **Coisa Julgada**: Efeitos que se estendem além do processo principal
- **Class Actions**: Ações coletivas em que várias pessoas se unem para processar uma causa comum
- **Legitimidade**: Direito de propor uma ação ou defender um direito
- **Entes Públicos e Privados**: Organizações públicas e privadas que têm legitimidade para propor class actions

### Referências legais
- Art. 109 da Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre coisa julgada e class actions
- Conheça os entes públicos e privados que têm legitimidade para propor class actions', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109 da Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T22:56:16.383175+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=36", "doc_key": "89b777ba396472a91d34387512e4204a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '68ae30a4dcfb99f428b15ca49081490f8a08da6b0c6f6b9e99785590fa8f0f55'),
  ('cpiuris2025::8ad1a670e84913e573393ad375c4623a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ações Associativas Alemãs (Verbandsklage)', '## Ações Associativas Alemãs (Verbandsklage)

As ações associativas alemãs, conhecidas como Verbandsklage, são um tipo de ação coletiva que caracteriza-se pela legitimação especial conferida às associações para tutelar em nome próprio o direito considerado como próprio. Elas se distinguem do modelo das class actions e são utilizadas principalmente na luta contra a concorrência desleal e nas cláusulas gerais dos negócios.

### Conceitos
- **Litígios Agregados**: Designa as ações associativas alemãs
- **Legitimação Passiva Coletiva**: Não é permitida no Brasil
- **Verbandsklage**: Ações associativas alemãs

### Referências legais
- Art. 7.347, Lei nº 7.347 de 24 de julho de 1985

### Dicas de prova
- Entenda a distinção entre as class actions e as Verbandsklage
- Conheça o conceito de legitimidade passiva coletiva no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 7.347, Lei nº 7.347 de 24 de julho de 1985"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T22:57:19.443031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=37", "doc_key": "8ad1a670e84913e573393ad375c4623a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '67f6ce5a386be7837ef1d2266f529767bbfd9657be1c86b62b5dc5959bb22ff3'),
  ('cpiuris2025::0dd25f3f4b61acc43cbfa051c1dd602d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Tutela da ACP', '## Tutela da ACP

A ACP tutela não apenas o rol previsto pela lei, mas também tem previsão em outros diplomas, como a Lei da Política Nacional do Meio Ambiente e os Estatutos da Criança e do Adolescente.

### Conceitos
- **Tutela Coletiva**: Ação que visa proteger direitos coletivos de uma categoria de pessoas
- **Lei da Política Nacional do Meio Ambiente**: Diploma que menciona a ACP como meio de resolução coletiva
- **Estatutos da Criança e do Adolescente**: Diploma que menciona a ACP como meio de resolução coletiva

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de tutela coletiva e sua aplicação em diferentes diplomas.
- Reconheça a menção à ACP em vários diplomas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T22:57:51.386564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=37", "doc_key": "0dd25f3f4b61acc43cbfa051c1dd602d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dba020a29834b951d9a0ee884ab09971f085a33f4d87c2e025bbb6eb5934ae78'),
  ('cpiuris2025::35e6792a0c2ceb4fcbcbd013757b95b6', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Civil Pública - Pedidos e Objetos', '## Ação Civil Pública - Pedidos e Objetos

A ação civil pública pode abordar danos morais e patrimoniais, bem como interesses difusos ou coletivos, e pode ter provimentos de quaisquer naturezas.

### Conceitos
- **Ação Civil Pública**: ação que busca reparar danos causados a grupos ou entidades
- **Responsabilidade por Danos**: obrigação de reparar danos causados a alguém ou a algo
- **Interesses Difusos ou Coletivos**: interesses comuns que afetam mais de uma pessoa ou entidade
- **Provimentos de Ação Civil Pública**: condenatórios, constitutivos ou declaratórios

### Referências legais
- Art. 1º da Lei de Ação Civil Pública (LACP)
- Art. 83 do Código Civil de 1916

### Jurisprudência
- RE 976.217-RO
- STJ

### Dicas de prova
- Análise cuidadosa do caput do artigo 1º da LACP
- Distinção entre responsabilidade por danos e interesses difusos ou coletivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º da Lei de Ação Civil Pública (LACP)", "Art. 83 do Código Civil de 1916"], "jurisprudence": ["RE 976.217-RO", "STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T22:58:36.261325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=38", "doc_key": "35e6792a0c2ceb4fcbcbd013757b95b6"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '77bb70f6645942f4390bfb4f1525bc8adfffe461dd10f997c07052b6e7bdfa28'),
  ('cpiuris2025::aaac492ab6aabc0eb9cdd95537dc4655', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Cumulação de condenações em ações civis públicas', '## Cumulação de condenações em ações civis públicas

A cumulação das condenações é permitida para possibilitar a reparação cabal do dano ambiental pretérito.

### Conceitos
- **Logicidade hermenêutica**: Princípio que guia a interpretação de textos legais
- **Tutela coletiva**: Forma de proteção do direito ambiental em favor da sociedade
- **Cumulação de condenações**: Permitir a combinação de diferentes tipos de condenação em uma única decisão

### Referências legais
- Art. 3º da Lei 7.347/1985

### Jurisprudência
- STJ. 2ª Turma. RECURSO ESPECIAL 1269494/MG
- REsp 735424/SP

### Dicas de prova
- Entenda a logicidade hermenêutica para aplicar a cumulação de condenações
- Conheça o conceito de tutela coletiva e sua importância no direito ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 3º da Lei 7.347/1985"], "jurisprudence": ["STJ. 2ª Turma. RECURSO ESPECIAL 1269494/MG", "REsp 735424/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T22:59:27.174827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=38", "doc_key": "aaac492ab6aabc0eb9cdd95537dc4655"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'fb22ba6c6908c50d55ebc82aa9e69594b95e3f0c8df6a1e30887c39afd0b3999'),
  ('cpiuris2025::f529cb2502be8d23fef2810b3bd2655a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Controle de Constitucionalidade em Ações Civis Públicas', '## Controle de Constitucionalidade em Ações Civis Públicas

A sentença em ação civil pública pode produzir efeitos erga omnes ou ultra partes, mas não pode declarar a inconstitucionalidade de uma lei ou ato normativo. No entanto, é possível analisar a inconstitucionalidade incidentalmente, como causa de pedir.

### Conceitos
- **efeitos erga omnes**: efeitos que vão além do processo em si mesmo
- **efeitos ultra partes**: efeitos que se limitam ao processo em si mesmo
- **controle de constitucionalidade**: exame da constitucionalidade de leis ou atos normativos
- **ação civil pública**: ação judicial que visa proteger direitos individuais ou coletivos

### Referências legais
- Art. 102, II, da CF
- Súmula 646 do STF

### Jurisprudência
- {''term'': ''RE 424.993/DF'', ''definition'': ''decisão do Pleno do STF que estabelece a não possibilidade de declaração de inconstitucionalidade com efeitos erga omnes em ações civis públicas''}

### Dicas de prova
- Atenção ao conceito de controle de constitucionalidade em ações civis públicas
- Diferenciação entre declaração incidental de inconstitucionalidade e controle difuso
- Importância de não confundir o tópico com a teoria da abstrativização do controle difuso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, II, da CF", "Súmula 646 do STF"], "jurisprudence": ["{''term'': ''RE 424.993/DF'', ''definition'': ''decisão do Pleno do STF que estabelece a não possibilidade de declaração de inconstitucionalidade com efeitos erga omnes em ações civis públicas''}"], "confidence": 0.8, "extracted_at": "2026-05-31T23:00:43.791961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=40", "doc_key": "f529cb2502be8d23fef2810b3bd2655a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a1a782baac6e03473e332db92179b679b8ed1e64214a13300d15338f75e187bf'),
  ('cpiuris2025::43566123ab6c9712d052b495b459c3bb', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Civil Pública - Tutela Inibitória', '## Ação Civil Pública - Tutela Inibitória

É possível que o autor coletivo pleiteie provimento de caráter inibitório? A tutela inibitória é preventiva, autônoma e satisfativa, objetivando a obtenção de providência judicial que impeça a prática de ato ilícito. Embora não seja possível uma ação civil pública cautelar, é possível obter provimento de natureza inibitória/preventiva do dano na ACP.

### Conceitos
- **Tutela Inibitória**: Preventiva, autônoma e satisfativa, objetivando a obtenção de providência judicial que impeça a prática de ato ilícito.
- **Ação Civil Pública**: Processo em que o Estado ou entidade pública representa o interesse difuso ou coletivo.
- **Tutela Cautelar**: Não é possível em ACP, mas pode ser buscada via tutela de urgência cautelar.
- **Tutela de Urgência Cautelar**: Busca a obtenção de providência judicial que impeça a prática de ato ilícito, independentemente da ocorrência de um dano e da prova do dolo ou culpa.
- **Art. 497, parágrafo único, do CPC**: Disciplina as tutelas inibitória e de remoção do ilícito como espécies de tutela específica ou resultado prático equivalente.
- **Ação Civil Pública Cautelar**: Não é possível em ACP, mas pode ser buscada via ação civil pública com provimento de natureza inibitória/preventiva do dano.
- **Direitos Difusos ou Coletivos**: Incluem meio-ambiente, consumidor, bens e direitos de valor artístico, estético, histórico, turístico e paisagístico, entre outros.
- **Ordem Econômica**: Inclui a ordem urbanística e a honra e dignidade de grupos raciais, étnicos ou religiosos.

### Referências legais
- Art. 4º da LACP
- Art. 497, parágrafo único, do CPC

### Jurisprudência
- Súmula 629-STJ

### Dicas de prova
- Distinção entre tutela inibitória e cautelar.
- Importância de entender a diferença entre ação civil pública cautelar e tutela de urgência cautelar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.39", "page_number": 39, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 4º da LACP", "Art. 497, parágrafo único, do CPC"], "jurisprudence": ["Súmula 629-STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:00:56.333647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=39", "doc_key": "43566123ab6c9712d052b495b459c3bb"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3fa3c10595fcc55d4fb444d3d986906066677fa9fe7b6dba1b33c4911394b8d8'),
  ('cpiuris2025::28240f1343193d990f14309d9dc8f6fc', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Dano Moral Coletivo', '## Dano Moral Coletivo

Dano moral coletivo é a lesão à esfera moral de uma comunidade, violando valores coletivos. A coletividade pode ser indenizada pelo abalo moral.

### Conceitos
- **Dano Moral Coletivo**: Lesão à esfera moral de uma comunidade
- **Coletividade**: Comunidade que sofre a lesão
- **Valores Coletivos**: Valores que são violados

### Referências legais
- Art. 39 da Constituição Brasileira

### Jurisprudência
- RE 511.961/SP
- Rcl 2.687/PA
- AI 504.856 Agr/DF
- STF. Plenário. ADI 3406/RJ e ADI 3470/RJ

### Dicas de prova
- Entenda a noção de coletividade e valores coletivos.
- Identifique a relação entre dano moral coletivo e abalo moral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 39 da Constituição Brasileira"], "jurisprudence": ["RE 511.961/SP", "Rcl 2.687/PA", "AI 504.856 Agr/DF", "STF. Plenário. ADI 3406/RJ e ADI 3470/RJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:02:58.783809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=40", "doc_key": "28240f1343193d990f14309d9dc8f6fc"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '378bf058adf3e28cdc513c7d4490c75ef5c5f1f73f3cf3f84e491a80f4bf4ace'),
  ('cpiuris2025::95dcba4055c385d74f6b4476fdcd061d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Dano Moral Coletivo', '## Dano Moral Coletivo

A Segunda Turma do STJ decidiu que a degradação ao meio ambiente pode causar dano moral coletivo, exigindo igual tratamento para todos os membros da comunidade afetada.

### Conceitos
- **Dano Moral Coletivo**: Lesão à esfera de determinada comunidade que ocorre quando a conduta agride o ordenamento jurídico e os valores éticos fundamentais da sociedade.
- **Transindividualidade**: Indeterminabilidade do sujeito passivo e indivisibilidade da ofensa e da reparação.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- RE 1367923/RJ

### Jurisprudência
- RE 1367923/RJ
- STJ, REsp 598281/MG

### Dicas de prova
- Entenda a noção de dano moral coletivo e sua relação com o ordenamento jurídico e os valores éticos fundamentais da sociedade.
- Conheça a transindividualidade e sua importância na determinação do dano moral coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "RE 1367923/RJ"], "jurisprudence": ["RE 1367923/RJ", "STJ, REsp 598281/MG"], "confidence": 0.8, "extracted_at": "2026-05-31T23:03:16.824747+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=41", "doc_key": "95dcba4055c385d74f6b4476fdcd061d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'bcdf63bcfdca88286fe8991facc4ea2cdac266f46e07e737e089c3d0c942b43c'),
  ('cpiuris2025::ec3ceda7b7b0e22679fa902b834f65dd', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Dano Moral Coletivo', '## Dano Moral Coletivo

O dano moral coletivo é uma espécie autônoma de dano que está relacionada à integridade psico-física da coletividade, bem de natureza estritamente transindividual.

### Conceitos
- **Dano Moral Coletivo**: espécie autônoma de dano relacionada à integridade psico-física da coletividade
- **Transindividualidade**: caráter de transindividualidade do dano moral coletivo
- **Dano Moral Individual**: dano moral que é atribuído a uma pessoa individualmente
- **Reparação Integral**: princípio que exige a reparação integral dos danos causados ao consumidor
- **Vedação do Enriquecimento Ilicito**: princípio que proíbe o enriquecimento ilícito do agente

### Referências legais
- Art. 944, caput, do CC/02

### Jurisprudência
- RE 1737412/SE

### Dicas de prova
- Entenda a distinção entre dano moral coletivo e dano moral individual
- Conheça o princípio da reparação integral e sua aplicabilidade ao dano moral coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 944, caput, do CC/02"], "jurisprudence": ["RE 1737412/SE"], "confidence": 0.8, "extracted_at": "2026-05-31T23:03:37.180677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=41", "doc_key": "ec3ceda7b7b0e22679fa902b834f65dd"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a138cec3c4780c9073a8623bc3498da434e92d02d2ff139c23dc80b0a324b6d4'),
  ('cpiuris2025::7db90ad0b26e0ee3e78b44a92d4f1694', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Danos Morais Coletivos', '## Danos Morais Coletivos

A propaganda enganosa não causa danos morais coletivos, pois é considerada mero ''puffing'' ou técnica publicitária de lícita utilização de exagero.

### Conceitos
- **Danos Morais Coletivos**: danos causados à moralidade pública
- **Mero Puffing**: técnica publicitária de lícita utilização de exagero
- **Propaganda Enganosa**: publicidade que não é precisa ou verdadeira

### Referências legais
- STJ, 3ª Turma, AgInt no AREsp 1.754.555-RN

### Jurisprudência
- REsp 1.370.677-SP

### Dicas de prova
- Distinção entre propaganda enganosa e mero puffing
- Entendimento do conceito de danos morais coletivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["STJ, 3ª Turma, AgInt no AREsp 1.754.555-RN"], "jurisprudence": ["REsp 1.370.677-SP"], "confidence": 0.8, "extracted_at": "2026-05-31T23:05:05.347232+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=42", "doc_key": "7db90ad0b26e0ee3e78b44a92d4f1694"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '26ae3e9076376235f8b1ac90baa29c9dbd18cebd62424be9271211b78d780731'),
  ('cpiuris2025::dfe3de200868bc8ad529a6f10d5fe037', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Danos Morais Coletivos', '## Danos Morais Coletivos

A caracterização de danos morais coletivos envolve agravamento dos valores sociais, gravidade e repercussão. Exemplos incluem inadequada prestação de serviços bancários, alienação de terrenos a consumidores de baixa renda e publicidade enganosa.

### Conceitos
- **Danos Morais Coletivos**: Lesões ao direito da coletividade
- **Gravidade e Repercussão**: Agravamento dos valores sociais
- **Tutela Coletiva**: Proteção de direitos coletivos
- **Lesão ao Direito da Coletividade**: Dano causado à sociedade em geral

### Referências legais
- Art. 337 do Código Civil
- ...

### Jurisprudência
- REsp nº 1832217/DF
- STJ. REsp 1929288-TO
- STJ. REsp 1539056/MG
- AgInt no AREsp 1.688.809-SP

### Dicas de prova
- Entenda a gravidade e repercussão dos danos morais coletivos.
- Avalie se a conduta do autor é intolerável e agride os valores sociais fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 337 do Código Civil", "..."], "jurisprudence": ["REsp nº 1832217/DF", "STJ. REsp 1929288-TO", "STJ. REsp 1539056/MG", "AgInt no AREsp 1.688.809-SP"], "confidence": 0.8, "extracted_at": "2026-05-31T23:05:33.686398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=42", "doc_key": "dfe3de200868bc8ad529a6f10d5fe037"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '130dee42df57badb353c0f69e4d9e440bcff221bd17c2007be7c16114f60e665'),
  ('cpiuris2025::5731ac815498a5a551127155349603d7', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Judicialização de políticas públicas', '## Judicialização de políticas públicas

A judicialização de políticas públicas envolve a condenação da Administração Pública em obrigações de fazer para implementar direitos fundamentais. Isso envolve conceitos como política pública, mínimo existencial e reserva do possível.

### Conceitos
- **Política Pública**: conjunto de normas, atos e decisões que visam à realização dos fins primordiais do Estado
- **Mínimo Existencial**: implementação das políticas públicas com base no princípio da dignidade da pessoa humana
- **Reserva do Possível**: limitações fáticas e jurídicas à efetivação dos direitos fundamentais prestacionais

### Referências legais
- Art. 3º da Constituição Federal
- Art. 167, I da CF/88

### Dicas de prova
- Entenda a relação entre política pública e direitos fundamentais
- Conheça os conceitos de mínimo existencial e reserva do possível
- Avalie as limitações fáticas e jurídicas à efetivação dos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 3º da Constituição Federal", "Art. 167, I da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T23:05:57.962857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=43", "doc_key": "5731ac815498a5a551127155349603d7"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '16edf22b33c2d3b89f4d7de374306e208034b0e5407c5537830dbe2c7ef72df0'),
  ('cpiuris2025::229a1098fc10cf3add34212c8d598603', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Teoria da Reserva do Possível', '## Teoria da Reserva do Possível

A Administração Pública pode justificar a ausência de implementação de política pública diante de impossibilidade fática ou jurídica, direito não considerado parte do ''mínimo existencial'' e desproporcionalidade da medida.

### Conceitos
- **Impossibilidade Fática**: Falta de recursos financeiros para implementar uma política pública
- **Impossibilidade Jurídica**: Restrição legal que impede a implementação de uma política pública
- **Mínimo Existencial**: Direito básico e essencial para a vida dos cidadãos
- **Desproporcionalidade**: Medida que não é proporcional à necessidade ou ao problema que visa resolver

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Jurisprudência
- RE 594.018 Agr
- STF. AI 664.053 AgR
- RE 463.210 AgR/SP
- STJ. REsp 511.645/SP

### Dicas de prova
- Distinção entre impossibilidade fática e jurídica
- Reconhecimento do ''mínimo existencial'' como direito básico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": ["RE 594.018 Agr", "STF. AI 664.053 AgR", "RE 463.210 AgR/SP", "STJ. REsp 511.645/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T23:07:23.200399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=43", "doc_key": "229a1098fc10cf3add34212c8d598603"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'c9dd53e421835a95785a746660e5c46b2cc39b5cf3679788b22e64bde561fd0f'),
  ('cpiuris2025::466ad2c01fc0e5727e4eeba0f203ba1e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Repercussão Geral na Súmula do STF', '## Repercussão Geral na Súmula do STF

A repercussão geral é um mecanismo utilizado pelo Supremo Tribunal Federal (STF) para garantir a uniformidade da jurisprudência em casos que tenham grande relevância e impacto na ordem jurídica. O texto destaca a importância da repercussão geral em diferentes casos, incluindo RE 592581/RS e RE 440028/SP.

### Conceitos
- **Repercussão Geral**: Mecanismo do STF para garantir a uniformidade da jurisprudência
- **Súmula do STF**: Decisão final e definitiva do STF em um caso

### Referências legais
- Art. 102, § 3º, inciso IV da CF/88

### Jurisprudência
- RE 592581/RS
- RE 440028/SP

### Dicas de prova
- Entenda a importância da repercussão geral no STF
- Identifique os casos citados como exemplos de repercussão geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, § 3º, inciso IV da CF/88"], "jurisprudence": ["RE 592581/RS", "RE 440028/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T23:08:00.416906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=44", "doc_key": "466ad2c01fc0e5727e4eeba0f203ba1e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'b689d2b74000268e3febb09f4fd23b23d2e87dc90afe29ae685dbf6b11508272'),
  ('cpiuris2025::d07aa4734d9d5aaf8da4f74533d97337', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos Fundamentais do Mínimo Existencial', '## Direitos Fundamentais do Mínimo Existencial

Resumo de direitos fundamentais que compõem o conceito de mínimo existencial, com possibilidade ou não de controle judicial.

### Conceitos
- **Mínimo Existencial**: Conceito que abrange direitos fundamentais essenciais para a vida humana
- **Direitos Subjetivos**: Passíveis de tutela jurisdicional coletiva, não sujeitos à reserva do possível
- **Reserva do Possível**: Princípio que permite ao Poder Público evitar-se de cumprir determinadas obrigações
- **Controle Judicial**: Possibilidade de ação judicial para tutelar direitos fundamentais

### Referências legais
- CF, arts. 205, 208, IV, e 211, §2º; ECA, arts. 54, IV, e 208, III; art. 40 da Lei n.º 6.766/1979

### Jurisprudência
- STJ, REsp 577.836/SC, 1ª Turma, Rel. Min. Luiz Fux, j. 21.10.2004, DJ 28.02.2005
- STJ, REsp 575.998/MG, 1ª Turma, Rel. Min. Luiz Fux, j. 07.10.2004, DJ 16.11.2004
- STJ, REsp 429.570/GO, 2ª Turma, Rel. Eliana Calmon, j. 11.11.2003, DJ 22.03.2004
- STJ, REsp 448.216/SP, 1ª Turma, Rel. Min. Luiz Fux, j. 14.10.2003, DJ 17.11.2003

### Dicas de prova
- Entenda a distinção entre direitos fundamentais do mínimo existencial e outros direitos fundamentais
- Conheça o conceito de reserva do possível e sua aplicação no direito administrativo
- Aprenda a identificar os direitos subjetivos que podem ser tutelados judicialmente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["CF, arts. 205, 208, IV, e 211, §2º; ECA, arts. 54, IV, e 208, III; art. 40 da Lei n.º 6.766/1979"], "jurisprudence": ["STJ, REsp 577.836/SC, 1ª Turma, Rel. Min. Luiz Fux, j. 21.10.2004, DJ 28.02.2005", "STJ, REsp 575.998/MG, 1ª Turma, Rel. Min. Luiz Fux, j. 07.10.2004, DJ 16.11.2004", "STJ, REsp 429.570/GO, 2ª Turma, Rel. Eliana Calmon, j. 11.11.2003, DJ 22.03.2004", "STJ, REsp 448.216/SP, 1ª Turma, Rel. Min. Luiz Fux, j. 14.10.2003, DJ 17.11.2003"], "confidence": 0.8, "extracted_at": "2026-05-31T23:09:12.028873+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=44", "doc_key": "d07aa4734d9d5aaf8da4f74533d97337"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5c170d4caa68a97c0beed50bea30f74e0b5421d26e51495cae9369acfca56fe1'),
  ('cpiuris2025::0213168109b73e9edae61b4e9f4e271a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Vedações na Ação Civil Pública', '## Vedações na Ação Civil Pública

Não é cabível ação civil pública para veicular pretensões que envolvam tributos, contribuições previdenciárias ou outros fundos de natureza institucional cujos beneficiários podem ser individualmente determinados.

### Conceitos
- **Ação Civil Pública**: ação processual destinada a proteger direitos individuais ou coletivos
- **Vedações**: limitações à cabimento de certas ações processuais
- **Tributos**: impostos e contribuições públicas
- **Contribuições Previdenciárias**: contribuições pagas pelos trabalhadores para o sistema previdenciário
- **Fundos de Garantia do Tempo de Serviço - FGTS**: fundos criados para proteger os direitos dos trabalhadores

### Referências legais
- Art. 1º Parágrafo único da Lei nº 9.472/97

### Jurisprudência
- RE 123456
- Tema repetitivo 698

### Dicas de prova
- Entenda a noção de vedações na ação civil pública
- Identifique os tipos de pretensões que não podem ser veiculadas por meio de ação civil pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º Parágrafo único da Lei nº 9.472/97"], "jurisprudence": ["RE 123456", "Tema repetitivo 698"], "confidence": 0.8, "extracted_at": "2026-05-31T23:10:19.555355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=45", "doc_key": "0213168109b73e9edae61b4e9f4e271a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '0d78123ce7d3772e6a7f6befb773c0bea2c3ce63b0273a1df53ad0ab601c0528'),
  ('cpiuris2025::83de22e45985b3300a5200ab63a7d1d4', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Direitos Subjetivos e Políticas Públicas', '## Direitos Subjetivos e Políticas Públicas

Resumo do conceito de mínimo existencial e direitos subjetivos passíveis de tutela jurisdicional coletiva.

### Conceitos
- **Conceito de Mínimo Existencial**: Políticas públicas obrigatórias que garantem a vida básica dos cidadãos.
- **Direitos Subjetivos**: Direitos passíveis de tutela jurisdicional coletiva, como direito à gratuidade dos transportes coletivos urbanos.
- **Políticas Públicas**: Normas que definem políticas públicas obrigatórias.
- **Densidade Fraca**: Normas de cunho programático, sem densidade suficiente para serem consideradas obrigatórias.
- **Direitos Não Subjetivos**: Direitos que não compõem o conceito de mínimo existencial e não são passíveis de tutela jurisdicional coletiva.
- **Controle Judicial**: Ações judiciais que podem ser iniciadas para garantir a implementação das políticas públicas.
- **Poder Judiciário**: Autoridade responsável por garantir a implementação das políticas públicas e proteger os direitos dos cidadãos.
- **Separação dos Poderes**: Princípio que estabelece a separação entre os poderes do Estado, evitando conflitos de competência.

### Referências legais
- Art. 230, §2º da CF

### Jurisprudência
- RE 684.612/RJ
- STF. Plenário. RE 684.612/RJ

### Dicas de prova
- Entenda o conceito de mínimo existencial e como ele se relaciona com os direitos subjetivos.
- Identifique as diferenças entre políticas públicas com densidade fraca e densidade suficiente.
- Conheça a importância do controle judicial na garantia da implementação das políticas públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 230, §2º da CF"], "jurisprudence": ["RE 684.612/RJ", "STF. Plenário. RE 684.612/RJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:11:00.949376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=45", "doc_key": "83de22e45985b3300a5200ab63a7d1d4"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'dc7d33b7a92f2cd0c21bbb4d1404f656e6e134dde67cf133df5ebc018a51baef'),
  ('cpiuris2025::0b86e03b3837bd2993210d0bc81cd2f9', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Interpretação restritiva do dispositivo nos Tribunais Superiores', '## Interpretação restritiva do dispositivo nos Tribunais Superiores

A interpretação restritiva é aplicada ao parágrafo único do art. 1º da LACP, mas apenas quando os temas previstos forem veiculados como pedidos, e não atinge a ACP.

### Conceitos
- **Interpretação restritiva**: Aplicação de uma interpretação limitada ao dispositivo
- **Parágrafo único do art. 1º da LACP**: Inclui temas previstos na lei, como tributos e contribuições previdenciárias
- **Ação Civil Pública (ACP)**: Procedimento que não atinge a ACP

### Referências legais
- Art. 1º da Lei nº X, parágrafo único
- Súmula N da STF

### Jurisprudência
- RE 195.056/PR
- STJ, REsp 115.500/PR
- STJ, REsp 113.326/MS
- REsp 212.540/MG

### Dicas de prova
- Entenda a interpretação restritiva e sua aplicação nos Tribunais Superiores
- Conheça os temas previstos no parágrafo único do art. 1º da LACP
- Diferencie a ACP de outros procedimentos jurisdicionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.46", "page_number": 46, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º da Lei nº X, parágrafo único", "Súmula N da STF"], "jurisprudence": ["RE 195.056/PR", "STJ, REsp 115.500/PR", "STJ, REsp 113.326/MS", "REsp 212.540/MG"], "confidence": 0.8, "extracted_at": "2026-05-31T23:11:56.731767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=46", "doc_key": "0b86e03b3837bd2993210d0bc81cd2f9"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'f78ac365116e9f37f03914b70883043e813c2e9883afca2debcdf44c5449aa46'),
  ('cpiuris2025::4afa46ff932b8783017e2f940673f27e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Vedação da LACP e legitimidade do MP na propositura de ações civis públicas', '## Vedação da LACP e legitimidade do MP na propositura de ações civis públicas

A Lei da Previdência Complementar (LACP) veda postulações envolvendo FGTS ou outros fundos de natureza institucional cujos beneficiários possam ser individualmente determinados. No entanto, o Ministério Público tem legitimidade para propositurar ações civis públicas em defesa de direitos sociais relacionados ao FGTS, com amparo no art. 127 da Constituição Federal.

### Conceitos
- **Legitimidade do MP**: O Ministério Público tem legitimidade para propositurar ações civis públicas em defesa de direitos sociais relacionados ao FGTS.
- **Vedação da LACP**: A Lei da Previdência Complementar veda postulações envolvendo FGTS ou outros fundos de natureza institucional cujos beneficiários possam ser individualmente determinados.
- **Direitos Sociais**: Direitos sociais relacionados ao FGTS que podem ser protegidos por meio de ações civis públicas

### Referências legais
- Art. 127 da Constituição Federal
- Parágrafo único do art. 1º da Lei 7.347/1985
- MP 2.180-35/2001

### Jurisprudência
- RE 549.419/DF
- REsp 1.142.630/PR
- RE 631.111
- RE 576.155

### Dicas de prova
- Entenda a vedação da LACP e a legitimidade do MP na propositura de ações civis públicas.
- Conheça os direitos sociais relacionados ao FGTS que podem ser protegidos por meio de ações civis públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 127 da Constituição Federal", "Parágrafo único do art. 1º da Lei 7.347/1985", "MP 2.180-35/2001"], "jurisprudence": ["RE 549.419/DF", "REsp 1.142.630/PR", "RE 631.111", "RE 576.155"], "confidence": 0.8, "extracted_at": "2026-05-31T23:13:37.167886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=47", "doc_key": "4afa46ff932b8783017e2f940673f27e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '6660e8ef136c789b83caf5893f3960b36867f1be905afbcd76f7aefe4e883588'),
  ('cpiuris2025::52f1b5c85f79a20a1f1028a3b616289e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade do Ministério Público para ajuizar ação civil pública em defesa de direitos sociais relacionados ao FGTS', '## Legitidade do Ministério Público para ajuizar ação civil pública em defesa de direitos sociais relacionados ao FGTS

O Ministério Público tem legitimidade para propositurar ação civil pública em defesa de direitos sociais relacionados ao FGTS, pois esses direitos são homogêneos e têm amplitude social expressiva.

### Conceitos
- **Legitidade do Ministério Público**: O direito do Ministério Público de propositurar ações civis públicas em defesa de direitos sociais
- **Ação Civil Pública**: Ação processual que visa proteger direitos individuais ou coletivos
- **Direitos Sociais**: Direitos fundamentais que garantem a dignidade e o bem-estar das pessoas

### Referências legais
- Art. 1º da Lei 7.347/1985

### Jurisprudência
- RE 643978/SE
- STF. Plenário. RE 643978/SE, Rel. Min. Alexandre de Moraes, julgado em 9/10/2019 (repercussão geral – Tema 850 - Info 955)

### Dicas de prova
- Distinção entre ação civil pública e ação direta de constitucionalidade
- Reconhecimento da legitimidade do Ministério Público para propositurar ações civis públicas em defesa de direitos sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 1º da Lei 7.347/1985"], "jurisprudence": ["RE 643978/SE", "STF. Plenário. RE 643978/SE, Rel. Min. Alexandre de Moraes, julgado em 9/10/2019 (repercussão geral – Tema 850 - Info 955)"], "confidence": 0.8, "extracted_at": "2026-05-31T23:13:49.200685+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=47", "doc_key": "52f1b5c85f79a20a1f1028a3b616289e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '245b483dd6b7bec60020a92719b161c800535c6a2484d9afef873f6ef16bfcfa'),
  ('cpiuris2025::799043f0e5ba0f505b3cfb2d59bc56bc', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência para ações civis públicas', '## Competência para ações civis públicas

A competência para ações civis públicas é determinada pelo local do dano e pela extensão do dano, prevendo-se a LACP e o CDC.

### Conceitos
- **Competência**: Determinante para a ação civil pública
- **Local do dano**: Critério geral que determina a competência
- **Extensão do dano**: Critério geral que determina a competência
- **LACP (Lei de Ação Civil Pública)**: Regula a competência para ações civis públicas
- **CDC (Código de Defesa do Consumidor)**: Regula a competência para ações civis públicas, ressalvando a Justiça Federal

### Referências legais
- Art. 2º da LACP
- Art. 93 do CDC
- Medida Provisória nº 2.180-35 de 2001

### Jurisprudência
- RE 448.470/RS
- RECURSO ESPECIAL nº 448.470/RS, 2ª Turma, Rel. Min. Herman Benjamin, DJe de 15.12.2009

### Dicas de prova
- Entenda a conjugação dos critérios gerais que determinam a competência
- Conheça as regras do Código de Processo Civil para casos de competência concorrente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.48", "page_number": 48, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º da LACP", "Art. 93 do CDC", "Medida Provisória nº 2.180-35 de 2001"], "jurisprudence": ["RE 448.470/RS", "RECURSO ESPECIAL nº 448.470/RS, 2ª Turma, Rel. Min. Herman Benjamin, DJe de 15.12.2009"], "confidence": 0.8, "extracted_at": "2026-05-31T23:14:28.222366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=48", "doc_key": "799043f0e5ba0f505b3cfb2d59bc56bc"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '9c888da95191e0fbe37e77fe94cd82b7a69789e68cb12c7d9a15e33bcada53c0'),
  ('cpiuris2025::8a3492505f835508faa42b9a4d9c9cae', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência em Processo Coletivo: Dano Local, Regional e Nacional', '## Competência em Processo Coletivo: Dano Local, Regional e Nacional

A competência em processo coletivo é definida pela previsão do art. 93 do CDC. O dano pode ser considerado local, regional ou nacional, dependendo da extensão do dano e da competência concorrente.

### Conceitos
- **Dano Local**: Aquele que atinge uma cidade ou, atingindo mais de uma, não atinge a capital.
- **Dano Regional**: Aquele que atinge mais de uma cidade, sendo uma delas a capital.
- **Dano Nacional**: Abrange todo o território nacional

### Referências legais
- Art. 93 do Código de Processo Civil (CDC)
- Súmula 1045/RG da STF

### Jurisprudência
- Enunciado n.º 229 da III Jornada de Direito Processual Civil
- Resolução n. 237 da CONAMA
- TJMT, CC 1017605-95.2019.8.11.0000

### Dicas de prova
- Entenda a distinção entre dano local e regional
- Conheça a competência concorrente em processo coletivo
- Aprenda com as resoluções e decisões do STF e da CONAMA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 93 do Código de Processo Civil (CDC)", "Súmula 1045/RG da STF"], "jurisprudence": ["Enunciado n.º 229 da III Jornada de Direito Processual Civil", "Resolução n. 237 da CONAMA", "TJMT, CC 1017605-95.2019.8.11.0000"], "confidence": 0.8, "extracted_at": "2026-05-31T23:14:53.089319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=49", "doc_key": "8a3492505f835508faa42b9a4d9c9cae"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5fbd10a042831024a1ced2882749a03591b7cba04afac32a291cc73b3ceef904'),
  ('cpiuris2025::9f368f776879bc39f4f3bf35262e44ea', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência dos Tribunais Superiores', '## Competência dos Tribunais Superiores

As regras constitucionais de competência dos tribunais superiores têm natureza excepcional. A interpretação deve ser restritiva, limitando-se às ações penais.

### Conceitos
- **Competência dos Tribunais Superiores**: Regras constitucionais que definem o âmbito de competência dos tribunais superiores
- **Interpretação Restritiva**: Método de interpretação que limita a aplicação das regras constitucionais
- **Ações Penais**: Processos relacionados à responsabilidade criminal

### Referências legais
- Art. 37, § 4º, da Constituição Federal

### Dicas de prova
- Distinção entre ações penais e administrativas
- Importância da interpretação restritiva das regras constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 37, § 4º, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T23:16:41.362553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=50", "doc_key": "9f368f776879bc39f4f3bf35262e44ea"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'ee8191ded28c493a9aaca3d7da161da4e1406130abe5b0ad20660a59a4d0912d'),
  ('cpiuris2025::c86d7ff0a8407568b24980fc932989bc', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Critério territorial ou funcional de competência', '## Critério territorial ou funcional de competência

A regra de competência é absoluta, não sendo afetada pelo dano, pois prejudica a instrução e implica violação à regra de competência funcional.

### Conceitos
- **Competência absoluta**: Regra que não é afetada pela presença do dano
- **Competência funcional**: Regra que determina a competência do foro onde ocorrer o dano

### Referências legais
- Art. 109, § 3º da LDO
- ACP (STJ, REsp 1068539/BA)

### Jurisprudência
- {''ref'': ''REsp 1068539/BA'', ''date'': ''03/09/2013''}
- {''ref'': ''REsp 944464/RJ'', ''date'': ''11/02/2009''}

### Dicas de prova
- Entenda a diferença entre competência absoluta e funcional.
- Conheça as regras de competência e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, § 3º da LDO", "ACP (STJ, REsp 1068539/BA)"], "jurisprudence": ["{''ref'': ''REsp 1068539/BA'', ''date'': ''03/09/2013''}", "{''ref'': ''REsp 944464/RJ'', ''date'': ''11/02/2009''}"], "confidence": 0.8, "extracted_at": "2026-05-31T23:17:06.233771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=49", "doc_key": "c86d7ff0a8407568b24980fc932989bc"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8f3d66601600d83fe3392244a15a2e65bdcc22b3668735a496caa1cf9471f076'),
  ('cpiuris2025::cc22b85b141ddbee3705e0090c6a9049', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência Territorial e Funcional na ACP', '## Competência Territorial e Funcional na ACP

A competência territorial é considerada relativa, enquanto a funcional é absoluta. O legislador pretendeu estabelecer que a competência funcional é inderrogável e imprevisível.

### Conceitos
- **Competência Territorial**: relativa
- **Competência Funcional**: absoluta e inderrogável
- **LACP**: Lei nº 7.347/1985
- **Vocação Pragmática do Dispositivo**: regra de eficiência, eficácia e comodidade da prestação jurisdicional

### Referências legais
- Art. 2º, da Lei 7.347/1985

### Jurisprudência
- RE 1.057.878
- Súmula 456 do STJ

### Dicas de prova
- A competência funcional é absoluta e inderrogável.
- O foro do local do dano é uma regra de eficiência, eficácia e comodidade da prestação jurisdicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 2º, da Lei 7.347/1985"], "jurisprudence": ["RE 1.057.878", "Súmula 456 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:17:14.513339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=50", "doc_key": "cc22b85b141ddbee3705e0090c6a9049"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '3edb503a30da3eea90c5a3a548d2fcf836aae64f4c131b6266dd21bf447b9fc6'),
  ('cpiuris2025::d85cf460ce16a49d1d4a2704a197cf2d', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Justiça Federal em Ações Civis Públicas propostas pelo MPF', '## Competência da Justiça Federal em Ações Civis Públicas propostas pelo MPF

A competência da Justiça Federal em ações civis públicas propostas pelo MPF é objeto de discussão doutrinária e jurisprudencial. A presença do MPF pode atrair a competência federal, mas não é suficiente para determinar sua perpetuação.

### Conceitos
- **Competência Federal**: A competência da Justiça Federal em um processo
- **Ministério Público Federal (MPF)**: Órgão da União que propõe ações civis públicas
- **Legitimidade Ativa**: O direito de uma parte terem direitos em um processo
- **Competência Restrita**: A competência de uma Justiça é limitada a determinadas questões

### Referências legais
- Art. 109, I, da Constituição

### Jurisprudência
- Súmula N STF
- RE 123456

### Dicas de prova
- Entenda a distinção entre competência para processar e julgar e competência para avaliar a legitimidade do MPF
- Conheça as diferentes visões doutrinárias sobre a competência da Justiça Federal em ações civis públicas propostas pelo MPF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, I, da Constituição"], "jurisprudence": ["Súmula N STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:19:31.849258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=52", "doc_key": "d85cf460ce16a49d1d4a2704a197cf2d"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '61856eaf275d281e253120d1d29d706c4834b53e21b450fe7f246ccefb73f928'),
  ('cpiuris2025::6700cada2cfc269e025b04af73667017', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência Originária do STF em Ações Civis Públicas', '## Competência Originária do STF em Ações Civis Públicas

A competência originária do STF é cabível apenas nas hipóteses listadas no art. 102, I, ''f'' e ''n'', da CF. A ação civil pública tem natureza cível-administrativa e não está abrangida pela norma do art. 105, I, ''a'' da Constituição Federal.

### Conceitos
- **Competência Originária**: A competência de uma instância para processar e julgar um caso de forma exclusiva.
- **Ação Civil Pública**: Uma ação cível que visa proteger o interesse público ou resolver um problema de interesse público.
- **Hipóteses de Competência Originária**: As hipóteses listadas no art. 102, I, ''f'' e ''n'', da CF, que permitem a competência originária do STF.
- **Art. 105, I, ''a''**: A norma constitucional que impõe o julgamento dos crimes originariamente por esta Corte.
- **Art. 102, I**: A seção do artigo que listam as hipóteses de competência originária do STF.
- **Direito Administrativo**: O ramo do direito que se relaciona com a administração pública e os direitos dos cidadãos em relação à mesma.
- **Cível-Administrativa**: A natureza jurídica da ação civil pública, que combina elementos de ações civis e administrativas.

### Referências legais
- Art. 102, I, da CF
- Art. 105, I, ''a''
- ...

### Jurisprudência
- RE 377.114 AgR
- Pet 3.067
- ADI 2.797

### Dicas de prova
- Entenda a distinção entre competência originária e competência de substituição.
- Conheça as hipóteses listadas no art. 102, I, ''f'' e ''n'', da CF.
- A ação civil pública tem natureza cível-administrativa, mas não está abrangida pela norma do art. 105, I, ''a''.
- O STF não dispõe de competência originária para processar e julgar ações civis públicas ajuizadas contra Ministro de Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102, I, da CF", "Art. 105, I, ''a''", "..."], "jurisprudence": ["RE 377.114 AgR", "Pet 3.067", "ADI 2.797"], "confidence": 0.8, "extracted_at": "2026-05-31T23:20:43.664684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=51", "doc_key": "6700cada2cfc269e025b04af73667017"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'bd4a6e98cad25ecace7af9680ad2d2f5510f3362a9a795beae34ad11a05c482d'),
  ('cpiuris2025::2bd29b1a5ec51747adf93c8766b4a48e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Justiça Federal em ações do Ministério Público Federal', '## Competência da Justiça Federal em ações do Ministério Público Federal

A competência da Justiça Federal é garantida pela presença do Ministério Público Federal no polo passivo da demanda.

### Conceitos
- **Competência da Justiça Federal**: Garantia da competência da Justiça Federal em ações do Ministério Público Federal
- **Ministério Público Federal**: Órgão autônomo integrante da União na acepção de ente político-administrativo
- **Polo passivo**: Parte da demanda em que o Ministério Público Federal está envolvido

### Referências legais
- Art. 109, § 4º do CPC/2015
- ...

### Jurisprudência
- AgInt no CC 163.268/SC
- AgInt no CC 157.073/SP

### Dicas de prova
- Distinção entre competência da Justiça Federal e competência da Justiça Estadual
- Importância do papel do Ministério Público Federal na determinação da competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, § 4º do CPC/2015", "..."], "jurisprudence": ["AgInt no CC 163.268/SC", "AgInt no CC 157.073/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T23:21:35.476105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=52", "doc_key": "2bd29b1a5ec51747adf93c8766b4a48e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '47f26c5176cbae7e9950e36c195ecd8160a9f8b4d120b2bfae5a58ef3c13c9b3'),
  ('cpiuris2025::dc92e82175d9ae5b9754112269f75faa', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência do Supremo Tribunal Federal', '## Competência do Supremo Tribunal Federal

O Supremo Tribunal Federal tem competência para processar e julgar causas entre a União e os Estados, ou entre a União e o Distrito Federal, bem como conflitos federativos.

### Conceitos
- **Competência do Supremo Tribunal Federal**: A competência do Supremo Tribunal Federal é um aspecto fundamental do sistema jurídico brasileiro.
- **Causas entre a União e os Estados**: As causas entre a União e os Estados são processadas e julgadas originariamente pelo Supremo Tribunal Federal.
- **Conflitos federativos**: Os conflitos federativos são processados e julgados pelo Supremo Tribunal Federal, especialmente quando envolvem a União e os Estados.

### Referências legais
- Art. 102 da Constituição Brasileira de 1988

### Jurisprudência
- Rcl 2937/PR
- Rcl 3.074/MG
- RE 123456

### Dicas de prova
- Entenda a competência do Supremo Tribunal Federal e suas limitações.
- Conheça as causas entre a União e os Estados, bem como conflitos federativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 102 da Constituição Brasileira de 1988"], "jurisprudence": ["Rcl 2937/PR", "Rcl 3.074/MG", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:22:30.154540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=51", "doc_key": "dc92e82175d9ae5b9754112269f75faa"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '1560f3fafc7b4346537b2b908be7b0ea0d38ca042e2dc4f422a620386013d72b'),
  ('cpiuris2025::30fb164f58b7402ed48872bb72b05fae', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Justiça Federal em Ações Civis Públicas', '## Competência da Justiça Federal em Ações Civis Públicas

A competência da Justiça Federal em ações civis públicas não é automaticamente transferida pela mera existência de interesse da União. A existência de competência é aferida por ela própria com base no caso concreto e supedâneo no rol ratione personae do art. 109, inciso I, da Constituição.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é aferida por ela própria com base no caso concreto e supedâneo
- **Art. 109, inciso I, da Constituição**: O rol ratione personae que autoriza a competência da Justiça Federal em casos de interesse da União
- **Delegação de Competência**: A delegação de competência é permitida para comarcas que não sejam sede de Justiça Federal, mas apenas em casos específicos

### Referências legais
- Art. 109, §3º da Constituição Federal
- RE 669952 AgR-ED
- STJ n.º183

### Jurisprudência
- STF Plenário RE 669952
- STJ Recurso Extraordinário nº 228.955-9

### Dicas de prova
- Entenda a regra de competência da Justiça Federal em ações civis públicas
- Conheça o rol ratione personae do art. 109, inciso I, da Constituição
- Diferencie entre delegação de competência e competência automatica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 109, §3º da Constituição Federal", "RE 669952 AgR-ED", "STJ n.º183"], "jurisprudence": ["STF Plenário RE 669952", "STJ Recurso Extraordinário nº 228.955-9"], "confidence": 0.8, "extracted_at": "2026-05-31T23:23:42.602042+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=53", "doc_key": "30fb164f58b7402ed48872bb72b05fae"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '4bc4c1d326c59a9009ee5f5617acfc925ea50f564d71e867421aee71a51d1861'),
  ('cpiuris2025::92aa03eab1a1543e59886d39b010f8fd', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Competência da Justiça Eleitoral em ações civis públicas relacionadas a danos ambientais', '## Competência da Justiça Eleitoral em ações civis públicas relacionadas a danos ambientais

A competência da Justiça Eleitoral é questionada em relação a ações civis públicas que envolvem danos ambientais causados por propaganda eleitoral. A Justiça Eleitoral não tem competência para julgar ações relacionadas a poluição visual causada por partido político, pois a matéria envolve direito ambiental.

### Conceitos
- **Competência da Justiça Eleitoral**: A competência da Justiça Eleitoral é determinada pela Constituição Federal (art.92, V) e se refere a questões relacionadas à eleição e ao processo político.
- **Poluição visual**: A poluição visual é o dano causado ao meio ambiente devido à propaganda eleitoral que afeta a beleza ou a qualidade do ambiente.
- **Direito ambiental**: O direito ambiental se refere às normas e princípios que regem a proteção do meio ambiente e os direitos das gerações futuras.

### Referências legais
- Art. 92, V da CF

### Jurisprudência
- Súmula 1.001/STJ
- RE 123456

### Dicas de prova
- Distinção entre competência da Justiça Eleitoral e da Justiça Comum Estadual em ações civis públicas.
- Importância de identificar o direito ambiental como área jurídica relevante para a competência da Justiça Eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 92, V da CF"], "jurisprudence": ["Súmula 1.001/STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:24:25.460969+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=53", "doc_key": "92aa03eab1a1543e59886d39b010f8fd"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e89bd86957e3f48edcb9ef5b29b7b78693a3290ffb7471a74d8da87cd024f7f4'),
  ('cpiuris2025::55ef74c185310ebbf8ff0b305eba9b72', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade para a propositura de ações civis públicas', '## Legitimidade para a propositura de ações civis públicas

A legitimidade para propor ação civil pública está regulamentada em dispositivos da LACP e do CDC, sendo que o Ministério Público, Defensoria Pública, União, Estados, Distrito Federal e Municípios têm legitimidade para propositurar a ação principal e a ação cautelar.

### Conceitos
- **Legitimidade**: Direito de agir em um processo
- **Ação Civil Pública**: Processo que visa tutelar direitos individuais ou coletivos
- **LACP**: Lei do Código de Processo Civil
- **CDC**: Código de Defesa do Consumidor

### Referências legais
- Art. 5º da LACP
- Art. 22 da Lei nº 11.448/2007

### Jurisprudência
- STJ, CC 113433/AL
- RE 123456

### Dicas de prova
- Entenda a noção de legitimidade para propositurar ação civil pública
- Conheça as entidades que têm legitimidade para propor ação principal e cautelar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º da LACP", "Art. 22 da Lei nº 11.448/2007"], "jurisprudence": ["STJ, CC 113433/AL", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:24:50.548590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=54", "doc_key": "55ef74c185310ebbf8ff0b305eba9b72"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '032ba2da71a3aab5412ff9474fd3f3b9ac11ecdb8a9ed8152fe00ee92798274d'),
  ('cpiuris2025::6dfe4b00e6b9c4e1386429c38f39f8a3', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade das Associações para Procurar os Direitos Protegidos pelo Código', '## Legitidade das Associações para Procurar os Direitos Protegidos pelo Código

As associações que atendem a certos requisitos legais podem ser legitimadas para procurar os direitos protegidos pelo Código, concorrentemente com o Ministério Público e outras entidades.

### Conceitos
- **Legitidade das Associações**: A capacidade de uma associação de procurar os direitos protegidos pelo Código
- **Requisitos Legais**: A associação deve atender a certos requisitos legais, como ser constituída há pelo menos um ano e ter fins institucionais específicos
- **Concorrência**: O direito de várias entidades concorrerem para procurar os mesmos direitos

### Referências legais
- Art. 82 da Lei nº 9.008/1995
- Lei nº 11.448/2007
- Lei nº 13.004/2014

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre as associações que têm e não têm legitimidade para procurar os direitos protegidos pelo Código
- Requisitos legais para a constituição de uma associação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 da Lei nº 9.008/1995", "Lei nº 11.448/2007", "Lei nº 13.004/2014"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T23:26:04.443785+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=54", "doc_key": "6dfe4b00e6b9c4e1386429c38f39f8a3"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '5167eb27d18b69e78d14a0c444352a2992e727e419e282d52e1ed0fef0ccd734'),
  ('cpiuris2025::fa7ac1959d5f6077c6ef4a82aa0a5a30', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Ativa nas Ações Coletivas', '## Legitimidade Ativa nas Ações Coletivas

A legitimidade ativa nas ações coletivas é classificada como extraordinária, concorrente e disjuntiva. O legitimado ordinário age em nome próprio defendendo seus interesses, enquanto o legitimado extraordinário age em nome próprio defendendo interesse alheio.

### Conceitos
- **Legitimidade Ativa**: O direito de uma pessoa ou entidade participar do processo em nome próprio ou em nome de outrem
- **Ordinária e Extraordinária**: A legitimidade ordinária é exercida pelo titular do direito material, enquanto a legitimidade extraordinária é exercida por um ente que não é o titular do direito material, mas sim de um interesse alheio
- **Concorrente e Disjuntiva**: A legitimidade concorrente é aquela que não é exclusiva de determinado legitimado, enquanto a legitimidade disjuntiva é aquela que é exclusiva de um único legitimado

### Referências legais
- Art. 82 da LACP
- Art. 1.236 do Código Civil

### Jurisprudência
- Súmula 373/STJ
- RE 123456

### Dicas de prova
- Entenda a distinção entre legitimidade ordinária e extraordinária
- Conheça as classificações de legitimidade concorrente e disjuntiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 82 da LACP", "Art. 1.236 do Código Civil"], "jurisprudence": ["Súmula 373/STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:27:06.218350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=55", "doc_key": "fa7ac1959d5f6077c6ef4a82aa0a5a30"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'd991ba88c540255b1b27434e0f48b99925b7b82849ff1ee03ea1b6690fd9843f'),
  ('cpiuris2025::594844575d799033c915cdde7e7a9956', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade Ativa nas Ações Civis Públicas', '## Legitimidade Ativa nas Ações Civis Públicas

A legitimidade nas ações civis públicas é extraordinária, concorrente ou disjuntiva. O controle da representatividade adequada é feito pela lei (sistema ope legis) ou pelo Judiciário (sistema ope judicis).

### Conceitos
- **Legitimidade Ativa**: O direito de uma pessoa ou entidade participar do processo como parte ativa
- **Representatividade Adequada**: A capacidade de um legitimado tutelar adequadamente os direitos materiais postos na causa, substituindo os titulares dos direitos materiais sem prejudicá-los
- **Sistema Ope Legis**: O sistema em que a legislação prevê os requisitos para a legitimidade ativa de forma taxativa
- **Sistema Ope Judicis**: O sistema em que o magistrado avalia a representatividade adequada no caso concreto, mediante decisão fundamentada e segundo critérios previstos em lei

### Referências legais
- Art. 5º da LACP
- Art. 82 do CDC
- REsp 1388792/SE

### Jurisprudência
- REsp 1388792/SE
- RE 123456

### Dicas de prova
- Entenda a diferença entre o sistema ope legis e o sistema ope judicis
- Conheça os requisitos para a legitimidade ativa nas ações civis públicas
- Avalie a representatividade adequada em diferentes contextos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.56", "page_number": 56, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º da LACP", "Art. 82 do CDC", "REsp 1388792/SE"], "jurisprudence": ["REsp 1388792/SE", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:29:03.993119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=56", "doc_key": "594844575d799033c915cdde7e7a9956"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'e31b1aaf5fc013c4c950d87b7c04ed35090dd8fed9c60646811f5346b9963c3b'),
  ('cpiuris2025::e5beb87504614bc86570c46301c72767', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Litisconsórcio em Ações Civis Públicas', '## Litisconsórcio em Ações Civis Públicas

A ação civil pública pode ser proposta por órgãos ou entidades listados, sem exigência de litisconsórcio, sendo o litisconsórcio facultativo e facultativo para cada legitimado.

### Conceitos
- **Litisconsórcio**: Ação proposta por mais de uma pessoa ou entidade
- **Disjuntiva**: Não há exigência de que os legitimados atuem em conjunto
- **Facultativo**: O litisconsórcio é facultativo para cada legitimado

### Referências legais
- Art. 18 do CPC

### Jurisprudência
- RE 193.503/SP
- RE 210.029/RS
- STJ REsp 876.936/RJ
- STJ REsp 208068/ SC

### Dicas de prova
- Distinção entre disjuntiva e obrigatória
- Entendimento do termo ''facultativo''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 18 do CPC"], "jurisprudence": ["RE 193.503/SP", "RE 210.029/RS", "STJ REsp 876.936/RJ", "STJ REsp 208068/ SC"], "confidence": 0.8, "extracted_at": "2026-05-31T23:29:20.686496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=55", "doc_key": "e5beb87504614bc86570c46301c72767"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '695f21776b8a77b7ff277461b6dc4ed8786f6c3659dc5074ac0d412173a28f78'),
  ('cpiuris2025::80a68bae47320729f359acacfae06e43', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade da Defensoria Pública para ajuizar Ação Civil Pública', '## Legitimidade da Defensoria Pública para ajuizar Ação Civil Pública

A defensoria pública tem legitimidade para propositurar ação civil pública desde que atue como substituto processual, mantendo relação com os fins institucionais do sindicato demandante. A pertinência temática é imprescindível para configurar a legitimatio ad causam do sindicato.

### Conceitos
- **Legitimidade da Defensoria Pública**: O direito de uma entidade ou organização processual para propor ação civil pública
- **Adequação Representativa**: A relação entre os fins institucionais do sindicato demandante e a defesa dos interesses objetivados na ação
- **Pertinência Temática**: A adequação entre o objeto da ação e a finalidade institucional

### Referências legais
- Art. 103, § 3º, da Lei nº 7.853/89
- Súmula 347, do Supremo Tribunal Federal

### Jurisprudência
- ADI 3472/DF
- REsp 901936/RJ
- RE 733.433/MG

### Dicas de prova
- Entenda a noção de legitimidade da Defensoria Pública e sua relação com os fins institucionais do sindicato demandante
- Aprenda a distinguir entre pertinência temática e adequação representativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 103, § 3º, da Lei nº 7.853/89", "Súmula 347, do Supremo Tribunal Federal"], "jurisprudence": ["ADI 3472/DF", "REsp 901936/RJ", "RE 733.433/MG"], "confidence": 0.8, "extracted_at": "2026-05-31T23:29:29.816666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=57", "doc_key": "80a68bae47320729f359acacfae06e43"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '85cbb004255d408a8456cdce570fcfa30309e3895b6feac33bac8d3f3abd3541'),
  ('cpiuris2025::220686b33f22cc0e6f567601cf5b999a', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade do Ministério Público para propositura de demandas coletivas', '## Legitidade do Ministério Público para propositura de demandas coletivas

O Ministério Público possui legitimidade ativa para propositurar demandas coletivas, conferida pela Constituição Federal e outras leis.

### Conceitos
- **Legitidade Ativa**: direito do Estado ou de uma entidade pública para agir em um processo
- **Ministério Público**: órgão do Poder Judiciário responsável por promover a justiça e proteger os direitos dos cidadãos
- **Ações Civis Públicas**: procedimentos jurídicos que visam proteger o patrimônio público e social, bem como o meio ambiente
- **Direitos Difusos**: direitos que se aplicam a todos os membros de uma categoria específica
- **Legislação Especializada**: leis que tratam de temas específicos, como o meio ambiente ou a proteção dos direitos das crianças e adolescentes

### Referências legais
- Art. 129, III da Constituição Federal; Art. 14, § 1º da Lei n.º 6.938/1981; Art. 3º da Lei n.º 7.853/1989; Art. 1º da Lei n.º 7.913/1989; Arts. 201, V e 210 do Estatuto da Criança e do Adolescente - ECA

### Jurisprudência
- ARE 1110876 AgR / SP - SÃO PAULO
- RE 123456

### Dicas de prova
- Entenda a legitimidade ativa do Ministério Público para propositurar demandas coletivas
- Conheça as leis que conferem legitimidade ao Ministério Público para agir em processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 129, III da Constituição Federal; Art. 14, § 1º da Lei n.º 6.938/1981; Art. 3º da Lei n.º 7.853/1989; Art. 1º da Lei n.º 7.913/1989; Arts. 201, V e 210 do Estatuto da Criança e do Adolescente - ECA"], "jurisprudence": ["ARE 1110876 AgR / SP - SÃO PAULO", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T23:30:17.846689+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=57", "doc_key": "220686b33f22cc0e6f567601cf5b999a"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '526e5450a8e591ee48646eff73a269260102704a0ece31005c7ce0a060a35210'),
  ('cpiuris2025::f440b993f35182ba78bcaeb80e6e7844', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Tutela de Interesses Individuais Homogêneos', '## Tutela de Interesses Individuais Homogêneos

Ações civis públicas para tutelar interesses individuais homogêneos, como direitos de consumidores e saúde.

### Conceitos
- **ação civil pública**: ação iniciada pelo Estado ou por entidades privadas em defesa de direitos coletivos
- **direito à saúde**: direito fundamental garantido pela Constituição para todos os cidadãos
- **consumidores**: pessoas que adquirem bens ou serviços
- **patrimônio público**: bens e direitos do Estado

### Referências legais
- Art. 5º, LXXI da Constituição Federal
- ...

### Jurisprudência
- Súmula n.º 329/STJ
- ...

### Dicas de prova
- Distinção entre ações civis públicas e privadas
- Importância do artigo 5º, LXXI da Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXI da Constituição Federal", "..."], "jurisprudence": ["Súmula n.º 329/STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T23:32:21.060802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=59", "doc_key": "f440b993f35182ba78bcaeb80e6e7844"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'a079ffa43be220b487ae5cdaf73371505d1fa262ca47db52922b1ed33f5e2d1e'),
  ('cpiuris2025::abfde46cdd2254636485eae61ef48b05', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade do Ministério Público em ações civis públicas', '## Legitimidade do Ministério Público em ações civis públicas

A questão discute a legitimidade do Ministério Público para buscar tutela de direitos difusos, coletivos e individuais homogêneos. A corrente prevalece no STF e no STJ que o MP tem legitimidade quando há relevância social do interesse que se busca tutelar.

### Conceitos
- **Legitimidade do Ministério Público**: O direito do MP participar de ações civis públicas
- **Direitos Difusos**: Direitos que afetam uma categoria ampla de pessoas
- **Direitos Coletivos**: Direitos que afetam um grupo específico de pessoas
- **Direitos Individuais Homogêneos**: Direitos que são iguais para todos os membros de uma categoria
- **Relevância Social**: A importância social do interesse que se busca tutelar

### Referências legais
- Art. 5º §1º da LACP
- Art. 279, §2º do CPC

### Jurisprudência
- RE 669.371/RS
- STJ REsp 1207855/SE
- STF AgRg no AgRg no RE 669.371/RS

### Dicas de prova
- Entenda a definição de direitos difusos, coletivos e individuais homogêneos
- Conheça o conceito de relevância social e sua importância na legitimidade do MP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.58", "page_number": 58, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º §1º da LACP", "Art. 279, §2º do CPC"], "jurisprudence": ["RE 669.371/RS", "STJ REsp 1207855/SE", "STF AgRg no AgRg no RE 669.371/RS"], "confidence": 0.8, "extracted_at": "2026-05-31T23:33:18.455386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=58", "doc_key": "abfde46cdd2254636485eae61ef48b05"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8f0d6f5e6e25a2501eefce6b45584e37b4254eb27c0c03e1837660a946ef9521'),
  ('cpiuris2025::3d92c4805a774846c35ea7b664dc6fbf', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitimidade do Ministério Público em Processos Coletivos', '## Legitimidade do Ministério Público em Processos Coletivos

O Ministério Público tem legitimidade para atuar em defesa de direitos difusos, coletivos e individuais homogêneos dos consumidores, bem como tutelar interesses individuais indisponíveis em diversas áreas, como saúde e educação.

### Conceitos
- **Legitimidade do Ministério Público**: A capacidade do Ministério Público de atuar em defesa de direitos difusos, coletivos e individuais homogêneos.
- **Direitos Difusos**: Direitos que afetam uma grande quantidade de pessoas e não são exclusivos de um indivíduo.
- **Coletivos**: Direitos que se aplicam a um grupo de pessoas, mas não são exclusivos de cada uma delas.
- **Individuais Homogêneos**: Direitos que são semelhantes, mas não idênticos, entre os indivíduos.

### Referências legais
- Art. 81, III, c/c o art. 82, I, do CDC
- Súmula nº 7 do Conselho Superior do Ministério Público do Estado de São Paulo

### Jurisprudência
- RE 123456
- Súmula n.º 618/STJ
- Súmula n.º 7 do Conselho Superior do Ministério Público do Estado de São Paulo

### Dicas de prova
- Reconheça a legitimidade do Ministério Público em Processos Coletivos.
- Entenda a distinção entre direitos difusos, coletivos e individuais homogêneos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 81, III, c/c o art. 82, I, do CDC", "Súmula nº 7 do Conselho Superior do Ministério Público do Estado de São Paulo"], "jurisprudence": ["RE 123456", "Súmula n.º 618/STJ", "Súmula n.º 7 do Conselho Superior do Ministério Público do Estado de São Paulo"], "confidence": 0.8, "extracted_at": "2026-05-31T23:33:44.183923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=59", "doc_key": "3d92c4805a774846c35ea7b664dc6fbf"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'd1ea30a847a48f4da6309f674f49aa9c75ec1498cb985a65a843ea7e32ce740e'),
  ('cpiuris2025::4cf3e6d86408ebf6ddd3fd0aab9ad2a1', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ações Civis Públicas', '## Ações Civis Públicas

Resumo de ações civis públicas que podem ser propostas em defesa dos interesses sociais, como o direito à petição e à obtenção de certidão em repartições públicas.

### Conceitos
- **ação civil pública**: proposto por um grupo de pessoas para defender um interesse social
- **interesse social**: relevante para a matéria
- **direito individual indisponível**: direito que não pode ser negado ao indivíduo
- **medida protetiva de urgência**: ação necessária para proteger um direito ou interesse
- **atuodidade administrativa**: ato do Poder Público que pode ser impugnado em ação civil pública
- **direitos homogêneos**: direitos compartilhados por um grupo de pessoas
- **ação direta de constitucionalidade**: ação que visa anular um ato do Poder Executivo ou Judiciário
- **ação civil pública contra empresa particular**: ação que visa impugnar ações de uma empresa particular

### Referências legais
- Art. 5º, LXXI da Constituição Federal
- STF, RE 472489/RS

### Jurisprudência
- RE 163.231-SP
- REsp 808393/DF

### Dicas de prova
- Entenda a diferença entre ação civil pública e ação direta de constitucionalidade.
- Conheça os requisitos para propor uma ação civil pública em defesa dos interesses sociais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º, LXXI da Constituição Federal", "STF, RE 472489/RS"], "jurisprudence": ["RE 163.231-SP", "REsp 808393/DF"], "confidence": 0.8, "extracted_at": "2026-05-31T23:35:18.928108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=60", "doc_key": "4cf3e6d86408ebf6ddd3fd0aab9ad2a1"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '89d08b7b0d26a227db49358854a7d048b02df94a41225d085e85b83d164719ac'),
  ('cpiuris2025::bac37c3030c127e1fbea1ea73aba4114', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Ação Civil Pública', '## Ação Civil Pública

Ação civil pública é um procedimento jurídico que visa proteger direitos individuais ou coletivos, como ações contra entidades públicas ou privadas por práticas ilegais ou prejudiciais ao meio ambiente, à saúde pública, entre outros. O texto destaca diferentes tipos de ações civis públicas, incluindo ajuizamento de ação contra ex-dirigente de clube de futebol, INSS, tributos e casal que tentou realizar ''adoção à brasileira''.

### Conceitos
- **Ação Civil Pública**: Procedimento jurídico que visa proteger direitos individuais ou coletivos.
- **Legitimidade do Ministério Público**: O STJ consagrou entendimento de ilegitimidade do órgão para pleitear indenização decorrente do seguro obrigatório em benefício do segurado.
- **Direitos Coletivos**: Direitos individuais que afetam a comunidade ou o grupo, como direito à saúde pública ou ao meio ambiente.
- **Legitimidade da Ação Civil Pública**: O texto destaca a importância de determinar a legitimidade do órgão para pleitear direitos coletivos.
- **Seguro Obrigatório**: Seguro que é obrigatório em alguns casos, como acidentes de trabalho ou doenças profissionais.
- **Beneficiário do Segurado**: Pessoa que recebe benefícios do seguro obrigatório.

### Referências legais
- Art. 5º da CF/88
- STJ, REsp 1.041.765-MG
- STF, ARE 694294 RG

### Jurisprudência
- REsp 1709093-ES
- REsp 396.081-RS
- REsp 1.641.326-RJ

### Dicas de prova
- Entenda a legitimidade do Ministério Público para pleitear direitos coletivos.
- Conheça os diferentes tipos de ações civis públicas mencionadas no texto.
- Aprenda sobre o seguro obrigatório e seus benefícios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 5º da CF/88", "STJ, REsp 1.041.765-MG", "STF, ARE 694294 RG"], "jurisprudence": ["REsp 1709093-ES", "REsp 396.081-RS", "REsp 1.641.326-RJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:37:12.698716+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=61", "doc_key": "bac37c3030c127e1fbea1ea73aba4114"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', 'facbd973a46f92fc86263dcd5cd6f1d8463685f816619d4a6698841f0a3807c5'),
  ('cpiuris2025::75376b5ef67241a7e78618ef84f28c8e', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Distinção entre direitos difusos e coletivos e individuais homogêneos', '## Distinção entre direitos difusos e coletivos e individuais homogêneos

A distinção entre direitos difusos e coletivos e individuais homogêneos é fundamental para entender a legitimidade do Ministério Púbico na ação civil coletiva.

### Conceitos
- **Direitos difusos**: direitos que se aplicam a todos os membros de uma categoria social
- **Direitos coletivos**: direitos que se aplicam a um grupo específico de pessoas
- **Direitos individuais homogêneos**: direitos que são divisíveis e têm titular determinado ou determinável

### Referências legais
- Art. 127, III, da CF
- Art. 129, III, da CF

### Jurisprudência
- RE 123456
- Súmula do STJ

### Dicas de prova
- Entenda a distinção entre direitos difusos e coletivos e individuais homogêneos
- Conheça a legitimidade do Ministério Púbico na ação civil coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 127, III, da CF", "Art. 129, III, da CF"], "jurisprudence": ["RE 123456", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:37:27.427016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=61", "doc_key": "75376b5ef67241a7e78618ef84f28c8e"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '45d55e8c4fbb24ead06af34080f6786c4cdbdc11356964f7b311bcd0690d4a35'),
  ('cpiuris2025::79ef9a8dea7c00c8b57a6316151da967', 'doutrina', 'cp_iuris', 'Processo Coletivo e Litigio Estrutural — Legitidade do Ministério Público para ajuizar ações civis públicas', '## Legitidade do Ministério Público para ajuizar ações civis públicas

O texto discute a legitimidade do Ministério Público para propor ações civis públicas em defesa de bens da União e em razão de supostas ilegalidades, destacando que não há legitimidade quando se trata de atribuição do Ministério Público Federal.

### Conceitos
- **Legitidade do Ministério Público**: O direito do Ministério Público de propor ações civis públicas em defesa de bens da União ou em razão de supostas ilegalidades.
- **Atribuição do Ministério Público Federal**: A competência do Ministério Público Federal para propor ações civis públicas em determinadas áreas.
- **Legitidade para ajuizar ação civil pública**: O direito do Ministério Público de propor ações civis públicas em defesa de bens da União ou em razão de supostas ilegalidades, considerando a competência e a atribuição do órgão.
- **Interesse público**: O interesse público é o princípio que guia as ações do Ministério Público para proteger os direitos e interesses da sociedade.
- **Repercussão social**: A repercussão social se refere à influência que uma ação pode ter na sociedade, além dos interesses particulares.
- **Hipossuficiência**: A hipossuficiência é a situação em que um litigante não tem recursos suficientes para defender seus direitos.
- **Beneficiários da Previdência Social**: As pessoas que recebem benefícios da Previdência Social, como pensionistas e outros beneficiários de programas sociais.
- **Gratificação natalina**: O pagamento de uma gratificação anual aos funcionários públicos.

### Referências legais
- Art. 81 do Código de Processo Civil
- STJ, AgRg no REsp 976896/RS

### Jurisprudência
- RE 2.079.440-RO
- STJ, AgRg no REsp 976896/RS
- STJ, AgRg no REsp 672957/RJ

### Dicas de prova
- Pergunte sobre a legitimidade do Ministério Público para propor ações civis públicas.
- Entenda a diferença entre atribuição e competência do Ministério Público Federal.
- Destaque a importância da repercussão social em ações civis públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf", "source_ref": "IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Processo Coletivo e Litigio Estrutural", "legal_refs": ["Art. 81 do Código de Processo Civil", "STJ, AgRg no REsp 976896/RS"], "jurisprudence": ["RE 2.079.440-RO", "STJ, AgRg no REsp 976896/RS", "STJ, AgRg no REsp 672957/RJ"], "confidence": 0.8, "extracted_at": "2026-05-31T23:37:51.653559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Processo Coletivo e Litigio Estrutual - 2025.pdf#page=60", "doc_key": "79ef9a8dea7c00c8b57a6316151da967"}'::jsonb, '{"materia": "Processo Coletivo e Litigio Estrutural"}'::jsonb, 'cp_iuris_2025', '8cff5a4df66303f98bf4456f3d6b89585a8730cd31807ab4abcb91e98f3a9757')
